  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer

  // toIntとか+7とかするならvalにしろ
  @inline private def MOD = 1000000007

  def solve(): Unit = {
    val N, M = ni()
    val g = nm(N, M)

    def test(x: Int): Boolean = {
      debug(s"test($x)")
      val ix = Array.ofDim[Int](N)
      val disable = Array.ofDim[Boolean](M + 1)
      val count = Array.ofDim[Int](M + 1)
      REP(N) { i =>
        count(g(i)(0)) += 1
      }
      def step(): Boolean = {
        var mxCnt = 0
        var mxNum = 0
        REP(N) { i =>
          while(disable(g(i)(ix(i)))) {
            ix(i) += 1
            count(g(i)(ix(i))) += 1
          }
//          debug(count)
          if (count(g(i)(ix(i))) > mxCnt) {
            mxCnt = count(g(i)(ix(i)))
            mxNum = g(i)(ix(i))
            debug(s"change mxCnt:$mxCnt mxNum:$mxNum")
          }
        }
        debug(s"step mxCnt:$mxCnt mxNum:$mxNum")
        disable(mxNum) = true // 次のstepに備えて
        mxCnt <= x
      }

      REP(N) { _ =>
        if (step()) return true
      }
      false
    }

    val ans = findMin(test, 1, N)
    out.println(ans)
  }

  def findMin(f: Int => Boolean, min: Int, max: Int): Int = {
    var l = min - 1
    var h = max
    while(h - l > 1) {
      val x = (h + l) / 2
      if (f(x)) h = x
      else l = x
    }
    h
  }
}

