int solve(vector< int > p)
{
  int ans = N;
  int maxNum;
  int loopCnt = p.size();
  while (loopCnt--){

    map< int, int > m;

    REP(ni, N) {
      REP(mi, M) {
	if (binary_search(ALL(p), A[ni][mi])) {
	  m[A[ni][mi]]++;
