    int N, M;
    cin >> N >> M;

    vector<vector<int>> A(N, vector<int>(M));
    for (vector<int>& xs : A)
    {
        for (int& x : xs)
        {
            cin >> x;
            x--;
        }
        reverse(begin(xs), end(xs));
    }

    const auto works = [&](const int limit)
    {
        vector<vector<int>> preferences = A;
        for (int i = 0; i < M; i++)
        {
            vector<int> counts(M);
            for (vector<int>& xs : preferences)
            {
                if (xs.empty()) return false;
                else counts[xs.back()]++;
            }

            bool ok = true;
            for (int j = 0; j < M; j++)
            {
                if (counts[j] > limit)
                {
                    ok = false;
                    for (vector<int>& xs : preferences)
                        xs.erase(remove(begin(xs), end(xs), j), end(xs));
                    break;
                }
            }
            if (ok) return true;
        }
        return false;
    };

    int lower = 1, upper = N;
    while (lower < upper)
    {
        const int guess = (lower + upper) / 2;
        if (works(guess)) upper = guess;
        else lower = guess+1;
    }
    cout << lower << endl;
}

