bool check(const vector<vector<int>>& M, int border)
{
    int h = M.size();
    int w = M[0].size();

    vector<int> ixs(h, 0);
    vector<bool> use(w, false);

    for (;;) {
        // for (int i = 0; i < h; i++) {
        //     cout << i << ", " << ixs[i] << endl;
        // }

        map<int, int> mm;
        for (int i = 0; i < h; i++) {
            if (ixs[i] < 0)
                continue;
            mm[M[i][ixs[i]]]++;
        }

        int maxc = 0, maxv = -1;
        for (auto& p : mm) {
            if (maxc < p.second) {
                maxv = p.first;
                maxc = p.second;
            }
        }

        if (maxc <= border)
            return true;

        if (maxv < 0)
            return false;

        // cout << "* " << maxc << ", " << maxv << endl;

        use[maxv] = true;

        for (int i = 0; i < h; i++) {
            if (ixs[i] < 0)
                continue;

            if (M[i][ixs[i]] != maxv)
                continue;

            while (ixs[i] < w && use[M[i][ixs[i]]])
                ixs[i]++;

            if (ixs[i] == w)
                return false;
        }
    }

    return false;
}

