{
    int h, w;
    cin >> h >> w;

    vector<vector<int>> M(h, vector<int>(w));

    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            cin >> M[y][x];
            M[y][x]--;
        }
    }

    int lo = 0, hi = h;

    while (hi - lo > 1) {
        int mi = (lo + hi) / 2;

        if (check(M, mi))
            hi = mi;
        else
            lo = mi;
    }

    return lo + 1;
}

