int cnt[N];

int check(int x) {
    memset(cnt,0,sizeof(cnt));
    for (int i=0;i<n;i++) {
        cnt[a[i][idx[i]]]++;
    }
    int mx=0,num=0;
    for (int i=1;i<=m;i++) {
        if (cnt[i]>mx) {
            mx=cnt[i];
            num=i;
        }
    }
    if (mx>x) return -num;
    else return num;
}

bool ok(int x) {
    if (x==n) return true;
    memset(idx,0,sizeof(idx));
    for (int i=0;i<m-1;i++) {
        int res=check(x);
        if (res>0) return true;
        for (int j=0;j<n;j++) {
            a[j][pos[-res][j]]=0;
        }
        for (int j=0;j<n;j++) {
            while (a[j][idx[j]]==0&&idx[j]<m) idx[j]++; 
        }
    }
    return false;
}

