    for (int i=0;i<n;i++) {
        for (int j=0;j<m;j++) {
            scanf("%d",&a[i][j]);
            pos[a[i][j]][i]=j;
        }
    }
    int lo=1,hi=n;
    while (lo<hi) {
        int mid=(lo+hi)>>1;
        if (!ok(mid)) lo=mid+1;
        else hi=mid;
    }
    printf("%d\n",lo);
}

