    int pok=n,png=0;
    int pmid=(pok+png)/2;
    while(pok-png!=1){
        pmid=(pok+png)/2;
        if(canmake(pmid,m,n,a))pok=pmid;
        else png=pmid;
    }
    std::cout<<pok<<std::endl;
    return 0;
}

