bool check(int mid, int n, int m, VVI &perm) {
    VI pos(n, 0);
    VB alive(m, true);

    while (true) {
        if (*max_element(pos.begin(), pos.end()) == m) {
            return false;
        }

        VI cnt(m, 0);
        FOR(i,0,n-1) {
            cnt[perm[i][pos[i]]]++;
        }

        auto it = max_element(cnt.begin(), cnt.end());

        if (*it <= mid) {
            return true;
        }

        int toKill = it - cnt.begin();
        alive[toKill] = false;

        FOR(i,0,n-1) while (pos[i] < m && !alive[perm[i][pos[i]]]) {
            pos[i]++;
        }
    }
}

