struct Manacher {
  template <typename T>
  Manacher(const T &s) {
    T str;
    int n = s.size();
    REP(i, n) {
      str.push_back(s[i]);
      if (i + 1 < n) str.push_back('$');
    }
    n = str.size();
    radius.resize(n);
    int j = 1;
    for (int i = 0; i < n;) {
      while (i - j >= 0 && i + j < n && str[i - j] == str[i + j]) ++j;
      radius[i] = j;
      int k = 1;
      while (i - k >= 0 && i + k < n && k + radius[i - k] < j) {
        radius[i + k] = radius[i - k];
        ++k;
      }
      i += k;
      j -= k;
    }
  }

  int odd(int idx) { return (radius[idx * 2] + 1) / 2; }

  int even(int idx) { return radius[idx * 2 + 1] / 2; }

  bool is_palindrome(int left, int right) {
    int mid = (left + right - 1) / 2;
    return (((right - left) & 1) ? odd(mid) * 2 - 1 : even(mid) * 2) >= right - left;
  }

private:
  vector<int> radius;
};

int main() {
  int n, m; cin >> n >> m;
  vector<vector<int> > a(n, vector<int>(m)); REP(i, n) REP(j, m) cin >> a[i][j], --a[i][j];
  int lb = 0, ub = n;
  while (ub - lb > 1) {
    int mid = (lb + ub) >> 1;
    vector<int> idx(n, 0);
    vector<bool> era(m, false);
    REP(_, m) {
      bool ok = true;
      map<int, vector<int> > mp;
      REP(i, n) {
        while (idx[i] < m && era[a[i][idx[i]]]) ++idx[i];
        if (idx[i] == m) {
          ok = false;
          break;
        }
        mp[a[i][idx[i]]].emplace_back(i);
      }
      if (!ok) break;
      ok = true;
      for (auto &pr : mp) {
        const vector<int> &id = pr.second;
        if (id.size() > mid) {
          for (int e : id) ++idx[e];
          ok = false;
        }
      }
      if (ok) break;
    }
    bool ok = true;
    REP(i, n) ok &= idx[i] < m;
    (ok ? ub : lb) = mid;
  }
  cout << ub << '\n';
  return 0;
}

