struct UnionFind {
  vector<int> parent;  // parent[root] is the negative of the size.
  UnionFind(int n)
      : parent(n, -1){};
  bool unite(int u, int v) {
    u = root(u);
    v = root(v);
    if (u == v) return false;
    if (parent[u] > parent[v]) swap(u, v);
    parent[u] += parent[v];
    parent[v] = u;
    return true;
  }
  bool find(int u, int v) {
    return root(u) == root(v);
  }
  int root(int u) {
    return parent[u] < 0 ? u : parent[u] = root(parent[u]);
  }
  int size(int u) {
    return -parent[root(u)];
  }
};

bool check(const vec<int, 2>& A, const vec<int, 2>& B, int L) {
  int N = A.size(), M = A[0].size();
  vector<UnionFind> uf(N, UnionFind(M + 1));
  int rem = M;
  while (rem > 0) {
    vector<int> cnt(M, 0);
    for (int i = 0; i < N; i++) {
      int j = uf[i].size(0) - 1;
      ++cnt[A[i][j]];
    }
    bool cont = false;
    for (int k = 0; k < M; k++) {
      if (cnt[k] > L) {
        cont = true;
        --rem;
        for (int i = 0; i < N; i++) {
          int j = B[i][k];
          uf[i].unite(j, j + 1);
        }
      }
    }
    if (!cont) {
      return true;
    }
  }
  return false;
}

