int max(int x,int y)
{
    return x>y?x:y;
}

int main()
{
    int n,m,ma,mi,x;
    while (scanf ("%d%d",&n,&m) != EOF)
    {
        for (int i=0;i<n;i++)
        {
            for (int j=0;j<m;j++)
            {
                scanf("%d",&map[i][j]);
            }
            vec[i] = 0;
            index[i] = 0;
        }
        mi=0;
        for (int i=0;i<m;i++)
        {
            for (int j=0;j<n;j++)
            {
                vec[map[index[j]][i]]++;
            }
            ma = map[0][i];
            x = 0;
            for (int j=0;j<n-1;j++)
            {
                ma = max(ma,map[j+1][i]);
            }
            for (int j=0;j<n;j++)
            {
                if (map[j][i] == ma)
                {
                    vec[j] = 0;
                    x++;
                    index[j]++;
                }
            }
            if (mi < x)
            {
                mi = x;
            }
        }
        printf ("%d\n",mi);
    }
    return 0;
}

