bool check(vvi sport, int K) {

	//cout << "K: " << K << endl;

	vi cur(N, 0);
	vb ban(M, false);
	int cnt = 0;
	while (cnt < N) {
		vi num(M, 0);

		rep(i, N) {
			num[sport[i][cur[i]]]++;
		}
		rep(i, M) {
			if (num[i] > K) {
				ban[i] = true;
			}
		}
		/*
		cout << "cur: ";
		rep(i, N) {
			cout << cur[i] << " ";
		}
		cout << endl;
		cout << "num: ";
		rep(i, M) {
			cout << num[i] << " ";
		}
		cout << endl;
		*/
		bool flag = true;
		rep(i, N) {
			if (num[sport[i][cur[i]]] > K) {
				flag = false;
				while (cur[i] < M && ban[sport[i][cur[i]]])cur[i]++;
				if (cur[i] >= M)return false;
			}
		}
		if (flag) {
			return true;
		}
	}
	return false;
}

int main() {
	cin >> N >> M;
	s = vvi(N, vi(M));
	rep(i, N) {
		rep(j, M) {
			cin >> s[i][j];
			s[i][j]--;
		}
	}
	int ok = N, ng = 0;
	while (ok - ng > 1) {
		int m = (ok + ng) / 2;
		if (check(s, m)) {
			ok = m;
		}
		else {
			ng = m;
		}
	}
	cout << ok << endl;
	return 0;
}

