using namespace std;

int a[301][301], sports[301], offset[301];
bool deleted[301];

int main()
{
    int N, M, min_max, locmax;
    bool flag = false;
    cin >> N >> M;
    for (int i = 1; i <= N; i++)
        for (int j = 1; j <= M; j++)
            scanf("%d", &a[i][j]);
    for (int i = 1; i <= N; i++)
        sports[a[i][1]]++;
    locmax = 1;
    for (int j = 1; j <= M; j++) {
        if (sports[j] > sports[locmax])
            locmax = j;
    }
    min_max = sports[locmax];
    for (int i = 1; i <= N; i++)
        offset[i] = 1;
    while (!flag) {
        deleted[locmax] = true;
        sports[locmax] = 0;
        for (int i = 1; i <= N; i++) {
            bool flag1 = false;
            while (deleted[a[i][offset[i]]]) {
                flag1 = true;
                offset[i]++;
                if (offset[i] > M){
                    flag = true;
                    break;
                }
            }
            if (flag)
                break;
            if (flag1) {
                sports[a[i][offset[i]]]++;
            }
        }
        if (flag)
            break;
        for (int j = 1; j <= M; j++) {
            if (sports[j] > sports[locmax])
                locmax = j;
        }
        if (min_max > sports[locmax])
            min_max = sports[locmax];
    }
    cout << min_max << endl;
    return 0;
}

