int N, M, A[303][303];

bool check(int x) {
    int now[303] = {};
    int played[303] = {};
    int nouse[303] = {};
    int cntall = 0;
    int loop = 0;
    while (true) {
        loop++;
        if (loop >= 1000)
            return 0;
        int MAX = 0;
        int cnt[303] = {};
        for (int i = 0; i < N; i++) {
            if (played[i])
                continue;
            while (nouse[A[i][now[i]]]) {
                now[i]++;
                if (now[i] >= M)
                    return false;
            }
            cnt[A[i][now[i]]]++;
        }
        bool flag = true;
        for (int i = 0; i < M; i++) {
            if (cnt[i] > x) {
                nouse[i] = 1;
                flag = false;
            }
        }
        if (flag)
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (!played[j])
                        if (A[j][now[j]] == i) {
                            played[j]++;
                            cntall++;
                        }
                }
            }
        if (cntall == N)
            return true;
    }
}


void solve() {
    int ok = N;
    int ng = 0;
    while (abs(ok - ng) > 1) {
        int mid = (ok + ng) / 2;
        if (check(mid)) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    cout << ok << endl;
}

