    int i, j;
    for (i = 0; i < n; i++) {
        for (j = 0; j < m; j++) {
            scanf("%d", &a[i][j]);  a[i][j]--;
        }
    }

    int l = 0, r = m;   //r:ok
    while (r - l > 1) {
        int mm = (l + r) / 2;

        vector<int> curr(n);
        vector<int> flag(m);
        int fin = 0;
        while (1) {
            vector<vector<int> > z(m);
            for (i = 0; i < n; i++) {
                while (curr[i] < m && flag[a[i][curr[i]]]) {
                    curr[i]++;
                }
                if (curr[i] == m) {
                    fin = 1;
                    break;
                }
                int tmp = a[i][curr[i]];
                assert(flag[tmp] == 0);
                z[tmp].push_back(i);
            }
            if (fin) {
                break;
            }
            int del = 0;
            for (i = 0; i < m; i++) {
                if (z[i].size() > mm) {
                    for (j = 0; j < (int)z[i].size(); j++) {
                        int id = z[i][j];
                        curr[id]++;
                    }
                    flag[i] = 1;
                    del = 1;
                    break;
                }                
            }
            if (del == 0) {
                break;
            }
        }
        if (fin) {
            l = mm;
        }
        else {
            r = mm;
        }
    }
    printf("%d\n", r);

    return;
}


