	cin >> N >> M;
	REP(i, N) REP(j, M) scanf("%d", &A[i][j]), A[i][j]--;

	int l = 0, r = M + 1;

	while (r - l > 1) {
		int m = (r + l) / 2;

		if (solve(m)) r = m;
		else l = m;
	}

	cout << max(r, 1) << endl;

	return 0;
}

