using namespace std;

bool test(int N, int M, const vector<vector<int>>& A, int k)
{
    vector<bool> used(M, false);

    vector<vector<int>::const_iterator> ps(N);
    vector<vector<int>::const_iterator> ends(N);
    for (int i = 0; i < N; ++i) {
        ps[i] = A[i].begin();
        ends[i] = A[i].end();
    }

    while (true) {
        vector<int> cnt(M);
        for (int i = 0; i < N; ++i) {
            if (ps[i] != ends[i])
                ++cnt[*ps[i]];
        }

        vector<pair<int, int>> rank;
        for (int i = 0; i < M; ++i) {
            rank.push_back(make_pair(cnt[i], i));
        }
        sort(rank.begin(), rank.end(), greater<pair<int, int>>());

        if (rank[0].first > k) {
            for (auto pr : rank) {
                int c = pr.first;
                int i = pr.second;
                used[i] = true;

                if (c <= k)
                    break;
            }

            for (int i = 0; i < N; ++i) {
                if (ps[i] == ends[i])
                    continue;

                while (ps[i] != ends[i] && used[*ps[i]])
                    ++ps[i];
                if (ps[i] == ends[i])
                    return false;
            }
        } else {
            break;
        }
    }

    return true;
}

int main()
{
    int N, M;
    cin >> N >> M;

    vector<vector<int>> A(N, vector<int>(M));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            cin >> A[i][j];
            --A[i][j];
        }
    }

    int mn = 0;
    int mx = 300;
    while (mx - mn > 1) {
        int mid = (mn + mx) / 2;
        if (test(N, M, A, mid))
            mx = mid;
        else
            mn = mid;
    }

    cout << mx << '\n';

    return 0;
}

