vector<int> cnt;

int f(int id) {
  vector<Node> nd;
  for(int j = 0; j < m; j++) {
    Node nds(j, 0);
    nd.push_back(nds);
  }
  for(int j = 0; j < n; j++) {
    if(a[j][cnt[j]] == id) {
      nd[a[j][cnt[j] + 1]].sum++;
    } else {
      nd[a[j][cnt[j]]].sum++;
    }
  }
  sort(nd.begin(), nd.end());
  return nd[0].sum;
}

