const int MAX = 2000000 ;

//宣言するときはstaticをつけて静的変数にするかグローバル変数として宣言
class SGT{
public :
	int n ;
//	d変数は単位元、計算の邪魔をしない値に設定する、INFや0など
	ll d = 0 ;
	ll num[MAX] ;

	void init(vector<ll> &a){
		n = 1 ;
		while(a.size()>n) n *= 2 ;
		for(int i=0;i<n;i++){
			if(i<a.size()) num[n-1+i] = a.at(i) ;
			else num[n-1+i] = d ;
		}
		for(int i=n-2;i>=0;i--){
			num[i] = max(num[i*2+1],num[i*2+2]) ;
		}
	}

//	内容次第でwhile内の計算式を書き換える
	void update(int i,ll a){
		i += n-1 ;
		num[i] = a ;
		while(i>0){
			i = (i-1)/2 ;
			num[i] = max(num[i*2+1],num[i*2+2]) ;
		}
	}

	ll query(int a,int b,int l,int r,int now){
		if(r<=a||b<=l) return d ;
		if(a<=l&&r<=b) return num[now] ;
		ll r1 = query(a,b,l,(l+r)/2,now*2+1) ;
		ll r2 = query(a,b,(l+r)/2,r,now*2+2) ;
		return max(r1,r2) ;
	}
};

int main(){
	ll n,m ;
	cin >> n >> m ;
	vvll a(n,vll(m)) ;
	for(auto &i:a) for(auto &j:i) cin >> j ;
	for(int i=0;i<n;i++) a.at(i).push_back(0) ;
	ll l=0,r=n,mid ;
	static SGT sgt ;
	while(l+1<r){
		mid = (l+r)/2 ;
//		ll mx = 0 ;
		vector<bool> ok(m+1,true) ;
		vll cnt(m+1,0) ;
		for(int i=0;i<n;i++) cnt.at(a.at(i).at(0))++ ;
		sgt.init(cnt) ;
		vll pos(n,0) ;
		bool flag = false ;
		ll rem = n ;
		while(rem){
			if(sgt.num[0]<=mid){
				flag = true ;
				break ;
			}
			for(int i=1;i<=m;i++){
				if(sgt.num[i+sgt.n-1]>mid){
					ok.at(i) = false ;
					rem-- ;
					sgt.update(i,0) ;
				}
			}
			for(int i=0;i<n;i++){
				if(!ok.at(a.at(i).at(pos.at(i)))){
					while(!ok.at(a.at(i).at(pos.at(i)))) pos.at(i)++ ;
					sgt.update(a.at(i).at(pos.at(i)),sgt.num[a.at(i).at(pos.at(i))+sgt.n-1]+1) ;
				}
			}
		}
		if(flag) r = mid ;
		else l = mid ;
	}
	cout << r << endl ;
}

