bool C(int ppl)
{
    bool choose[305]; //choose i-th sport
    memset(choose, true, sizeof(choose));

    while(true) {
        int cnt[305]; //count of i-th sport
        memset(cnt, 0, sizeof(cnt));
        bool used = true;

        for(int i=1; i<=n; i++) {
            int now = 1; //place of i-th sport that can be choose
            for(now=1; now<=m; now++) {
                if(choose[a[i][now]]) break;
            }
            if(now > m) return false;
            cnt[a[i][now]]++;
            if(cnt[a[i][now]] > ppl) {
                choose[a[i][now]] = false;
                used = false;
            }
        }
        if(used) return true;
    }
}

