using namespace std;

using VDI = vector<deque<int>>;

void show(VDI &vd) {
	for (auto d : vd) {
		for (auto e : d) {
			cout << e << " ";
		}
		cout << endl;
	}
}

map<int, int> count_sports(VDI &vd) {
	map<int, int> sports;
	for (auto d : vd) {
		sports[d.front()]++;
	}
	return sports;
}

bool pop_fronts(VDI &vd, vector<bool> &valids) {
	for (auto &deq : vd) {
		while (!valids[deq[0]]) {
			deq.pop_front();
			if (deq.empty()) {
				return false;
			}
		}
	}
	return true;
}

int main() {
	int n, m;
	cin >> n >> m;

	vector<deque<int>> a(n, deque<int>(m, 0));
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			cin >> a[i][j];
		}
	}

	int ans = 1e6;
	vector<bool> valids(m + 1, true);
	while(1) {
		auto sports = count_sports(a);
		pair<int, int> max_sports = *sports.begin();

		for (pair<int, int> p : sports) {
			if (p.second > max_sports.second) {
				max_sports = p;
			}
		}

		ans = min(ans, max_sports.second);
		valids[max_sports.first] = false;

		bool go_next = pop_fronts(a, valids);

		// show(a);
		// cout << endl;

		if (!go_next) {
			break;
		}
	}


	cout << ans << endl;
	return 0;
}

