bool check(int x, int N, int M) {
     memset(gone, 0, sizeof(gone));
     vector<deque<int>> cand;
     for (int i = 0; i < N; i++) {
         deque<int> tmp;
         for (int j = 0; j < M; j++) {
             tmp.push_back(a[i][j]);
         }
         cand.push_back(tmp);
     }
     for (int i = 0; i < M; i++) {
         memset(cnt, 0, sizeof(cnt));
         for (int j = 0; j < N; j++) {
             while (gone[cand[j].front()]) {
                   cand[j].pop_front();
             }
             cnt[cand[j].front()]++;
         }
         bool upd = false;
