template <typename T>
T make_v(T init) { return init; }

template <typename T, typename... Tail>
auto make_v(T init, size_t s, Tail... tail) {
#define rec make_v(init, tail...)
    return V<decltype(rec)>(s, rec);
#undef rec
}

int main() {
    ll N, M;
    cin >> N >> M;
    auto A = make_v(0, N, M);
    for(auto &v : A) for(auto &e : v) {
        cin >> e;
        e--;
    }

    for(ll ans = 1; ans <= N; ans++) {
        V<bool> ok(N, true);
        V<ll> idxv(N, 0);
        bool suc = true;
        while(true) {
            V<ll> cnt(M, 0);
            V<bool> ng(M, false);
            for(ll i = 0; i < N; i++) {
                ll idx = idxv[i];
                cnt[A[i][idx]]++;
            }
            for(ll i = 0; i < M; i++) ng[i] = (cnt[i] > ans);
            bool bflag = false;
            bool check = true;
            for(ll i = 0; i < N; i++) {
                ll &idx = idxv[i];
                if(!ok[A[i][idx]] || ng[A[i][idx]]) {
                    check = false;
                    idx++;
                    if(idx >= M) {
                        bflag = true;
                        break;
                    }
                }
            }
            if(check) break;
            if(bflag) {
                suc = false;
                break;
            }
        }
        if(suc) {
            cout << ans << endl;
            return 0;
        }
    }
    assert(false);
}

