using namespace std;

class Node {
public:
  int id, sum;
  Node(int i, int s) {
    id = i;
    sum = s;
  }
  bool operator<(const Node &rhs) const {
    return this->sum > rhs.sum;
  }
  bool operator>(const Node &rhs) const {
    return this->sum < rhs.sum;
  }
};

vector<bool> b;
int n, m;
vector<vector<int>> a;
vector<int> cnt;

int f(int id) {
  vector<Node> nd;
  for(int j = 0; j < m; j++) {
    Node nds(j, 0);
    nd.push_back(nds);
  }
  for(int j = 0; j < n; j++) {
    if(a[j][cnt[j]] - 1 == id) {
      nd[a[j][cnt[j] + 1]].sum++;
    } else {
      nd[a[j][cnt[j]] - 1].sum++;
    }
  }
  sort(nd.begin(), nd.end());
  return nd[0].sum;
}

int main() {
  cin >> n >> m;
  a.resize(n);
  cnt.resize(n);
  b.resize(n);
  for(int i = 0; i < n; i++) {
    a[i].resize(m);
    b[i] = true;
    for(int j = 0; j < m; j++)
      cin >> a[i][j];
  }

  int ans = n;

  for(int i = 0; i < m - 1; i++) {
    vector<Node> nd;
    for(int j = 0; j < m; j++) {
      Node nds(j, 0);
      nd.push_back(nds);
    }
    for(int j = 0; j < n; j++) {
      nd[a[j][cnt[j]] - 1].sum++;
    }
    sort(nd.begin(), nd.end());
    ans = min(ans, nd[0].sum);

    int c = nd[0].sum, id = nd[0].id, mm = f(nd[0].id);

    for(int i = 1; i < n && nd[i].sum == c; i++) {
      int d = f(nd[i].id);
      if(d < mm) {
        mm = d;
        id = nd[i].id;
      }
    }
    b[id] = false;
    for(int j = 0; j < n; j++) {
      if(a[j][cnt[j]] - 1 == id) {
        cnt[j]++;
      }
    }

  }
  cout << ans << endl;
  return 0;
}

