inline int solve() {
    int ans = N;
    for(int k = 0; k < M - 1; k++) {
        for(int i = 0; i < M; i++) cnt[i] = 0;
        for(int i = 0; i < N; i++) {
            while(selected[A[i][current[i]]]) current[i]++;
            cnt[A[i][current[i]]]++;
        }
        int tmp = 0, max_id;
        for(int i = 0; i < M; i++) {
            if(tmp < cnt[i]) {
                tmp = cnt[i];
                max_id = i;
            }
        }
        ans = min(ans, tmp);
        selected[max_id] = 1;
    }
    return ans;
}

