  この状態よりも参加人数が最大の種目を減らすなら、最も参加人数が多い種目を中止するしか無い
  以下繰り返しで解ける...はず。
 */


// m番目の種目をやめる
void cancelHighest(const int m, vector<bool> &canceled, vector< vector<int> > &order, vector<vector<int> > &pnum, int N, int M){
  canceled[m] = true;
  for(int i=0;i<pnum[m].size();++i){
    for(int j=0;j<M;++j){
      if(!canceled[order[pnum[m][i]][j]]){
	pnum[order[pnum[m][i]][j]].push_back(pnum[m][i]);
	break;
      }
    }
  }
  pnum[m].clear();
}

void pcount(int &maxido, int &maxnumo, vector< vector<int> > &pnum, int N, int M){
  // 最初の時点でのmaxを取得しておく
  int maxnum = 0; //参加人数
  int maxid = 0; //種目ID
  for(int i=0;i<M;++i){
    if(maxnum < pnum[i].size()){
      maxid = i;
      maxnum = pnum[i].size();
    }
  }
  maxido = maxid;
  maxnumo = maxnum;
}

int main(){
  int N;
  int M;

  cin >> N >> M;

  vector< vector<int> > order;
  vector<bool> canceled; //種目がcancelされたか
  vector<vector<int> > pnum; // 現状どの種目に誰が参加希望しているか

  order.resize(N);
  canceled.resize(M);
  pnum.resize(M);

  for(int i=0;i<N;++i){
    order[i].resize(M);
    for(int j=0;j<M;++j){
      cin >> order[i][j];
      order[i][j] -= 1;
    }
    pnum[order[i][0]].push_back(i);
  }

  int maxid = -1;
  int maxnum = -1;
  pcount(maxid, maxnum,pnum, N, M );

  // debug
  //cout <<"max"<< maxid<<","<<maxnum<<endl;
  for(int loop = 0; loop < M-1 ;++loop){
    int after = 0;
    int afterid =0;
    cancelHighest(maxid, canceled, order, pnum, N, M);
    pcount(afterid, after,pnum, N, M);
    //cout <<"max"<< maxid<<","<<maxnum<<endl;
    if(maxnum >= after){
      maxnum = after;
    }
    maxid = afterid;
  }
  cout<<maxnum;
  return 0;
}

