// (0..n-1)のn個の要素について、nCkの組み合わせに対して関数fを適用する
template<typename Function> void foreach_comb(ll n, ll k, Function f) {
	vector<ll> indexes(k);
	auto recursive_comb = [&](auto recursive_comb, vector<ll> &indexes, ll s, ll rest, Function f){
		if (rest == 0) {
			f(indexes);
		} else {
			if (s < 0) return;
			recursive_comb(recursive_comb, indexes, s - 1, rest, f);
			indexes[rest - 1] = s;
			recursive_comb(recursive_comb, indexes, s - 1, rest - 1, f);
		}
	};
	recursive_comb(recursive_comb, indexes, n - 1, k, f);
}
