ll N, M;
vector<vector<ll>> A;

void solve() {
  	scanf("%lld%lld", &N, &M);
	A.assign(N, vector<ll>(M, 0));
	rep(i, N) rep(j, M) {scanf("%lld", &A[i][j]); A[i][j]--;}

	ll minval=INF;
	vector<ll> kaisai(M,0);//1開催、-1非開催、0まだわからない
	vector<ll> nindex(N,0);//人がどのindexのスポーツに参加するか
	while(1){
		vector<vector<ll>> kaisaininzu(M);//どのスポーツに誰が参加するか
		rep(i,N){
			kaisaininzu[A[i][nindex[i]]].push_back(i);
		}
		ll maxval=0;
		ll sportsnum=-1;
		rep(i,M){
			if(chmax(maxval,(ll)kaisaininzu[i].size())){
				sportsnum=i;
			}
		}
		chmin(minval,maxval);

		kaisai[sportsnum]=-1;
		//全て探索終了なら終わる
		if([&]{
			rep(i,M){if(kaisai[i]!=-1)return false;}
			return true;
		}()){
			p(minval);return;
		}

		for(ll hito:kaisaininzu[sportsnum]){
			while(kaisai[A[hito][nindex[hito]]]==-1){
				nindex[hito]++;
			}
		}
		debug(kaisai);
		debug(nindex);
	}
}

