const ll N=310;
ll a[N][N],vis[N],sum[N],n,m,cur[N];
bool calc(ll x){
	memset(vis,0,sizeof vis);
	memset(sum,0,sizeof sum);
	bool fl=1;
	For(i,1,n)	cur[i]=1,sum[a[i][1]]++,vis[i]=1;
	while(fl){
		fl=0;
		For(i,1,m)	if (sum[i]>x)	sum[i]=0;
		For(i,1,n)	if (!sum[a[i][cur[i]]])	vis[i]=0,fl=1;
		For(i,1,n)	if (!vis[i]){
			vis[i]=1;
			sum[a[i][++cur[i]]]++;
			if (cur[i]>m)	return 0;
		}
	}
	For(i,1,n)	if (!vis[i])	return 0;
	return 1;
}
