	For(i,1,n)	For(j,1,m)	a[i][m-readint()+1]=j;
	ll l=0,r=n,ans=n;
	calc(1);
	while(l<=r){
		ll mid=(l+r)>>1;
		if (calc(mid))	r=mid-1,ans=mid;
		else	l=mid+1;
	}writeln(ans);
}

