bool test(int bound)
{
	memset(p,0,sizeof(p));
	memset(num,0,sizeof(num));
	memset(off,0,sizeof(off));
	for (int i = 1; i<=n; i++)
	{
		p[i] = 1;
		num[a[i][1]]++;
	}

	for (int q = 0; q<m; q++)
	{
		int i;
		for (i = 1; i<=m; i++)
		{
			if (num[i]>bound)
			{
				break;
			}
		}
		if (i > m) return true;
		num[i] = 0;
		off[i] = true;
		for (int j = 1; j<=n; j++)
		{
			if (a[j][p[j]] == i)
			{
				while (off[a[j][p[j]]])
				{
					p[j]++;
					if (p[j]>m) return false;
				}
				num[a[j][p[j]]]++;
			}
		}
	}
	return true;
}

int main()
{
	scanf("%d%d", &n, &m);
	for (int i = 1; i<=n; i++)
		for (int j = 1; j<=m; j++)
			scanf("%d", &a[i][j]);
	int l = 0; 
	int r = m;
	int mid;
	//printf("%d", test(2));
	while(l + 1 < r)
	{
		mid = (l+r)/2;
		if (test(mid))
		{
			r = mid;
		}
		else
		{
			l = mid;
		}
	}
	printf("%d", r);

}

