int n,m;
#define maxn 311
int a[maxn][maxn];
int tmp[maxn],cnt[maxn];
int que[maxn],tail;
bool no[maxn];
bool judge(int x)
{
	memset(tmp,0,sizeof(tmp));
	memset(cnt,0,sizeof(cnt));
	memset(no,0,sizeof(no));
	tail=0;
	for (int i=1;i<=n;i++)
		que[++tail]=i;
	while (tail)
	{
		for (int i=1;i<=tail;i++)
		{
			const int now=que[i];
			while (tmp[now]<=m && no[a[now][tmp[now]]]) tmp[now]++;
			if (tmp[now]>m) return 0;
			cnt[a[now][tmp[now]]]++;
			if (cnt[a[now][tmp[now]]]>x) no[a[now][tmp[now]]]=1;
		}
		tail=0;
		for (int i=1;i<=n;i++)
			if (no[a[i][tmp[i]]])
			{
				cnt[a[i][tmp[i]]]--;
				que[++tail]=i;
			}
	}
	return 1;
}
int main()
{
	scanf("%d%d",&n,&m);
	for (int i=1;i<=n;i++)
		for (int j=1;j<=m;j++)
			scanf("%d",&a[i][j]);
	int L=1,R=n;
	while (L<R)
	{
		int mid=(L+R)>>1;
		if (judge(mid)) R=mid;
		else L=mid+1;
	}
	printf("%d\n",L);
	return 0;
}

