bool chk(int x)
{
	queue<int>q[305];
	for(int i=1;i<=n;i++)for(int j=1;j<=m;j++)q[i].push(a[i][j]);
	for(int i=1;i<=m;i++)vis[i]=true;
	for(int tt=1;tt<=m;tt++)
	{
		for(int i=1;i<=m;i++)cc[i]=0;
		for(int i=1;i<=n;i++)
		{
			if(q[i].empty())return false;
			while(!q[i].empty()&&!vis[q[i].front()])q[i].pop();
			cc[q[i].front()]++;
		}
		bool f=false;
		for(int i=1;i<=m;i++)if(cc[i]>x)
		{
			f=true;
			vis[i]=false;
		}
		if(!f)break;
	}
	for(int i=1;i<=n;i++)
	{
		int cc=0;
		for(int j=1;j<=m;j++)
		{
			if(vis[j]==1)cc=1;
		}
		if(!cc)return false;
	}
	return true;
}
