void solve() {
	cin >> n >> m;

	for(int i = 0; i < n; ++i) {
		for(int j = 0; j < m; ++j) {
			A[i][j] = fetch<int>() - 1;
		}
	}

	int answ = INT_INF;
	for(int i = 0; i < m; ++i) {
		cur[i] = 1;
	}

	for(int ph = 0; ph < m - 1; ++ph) {
		memset(cnt, 0, sizeof(cnt));
		for(int i = 0; i < n; ++i) {
			for(int j = 0; j < m; ++j) {
				int s = A[i][j];

				if(cur[s]) {
					++cnt[s];
					break;
				}
			}
		}

		int pos = max_element(cnt, cnt + m) - cnt;
		answ = min(answ, cnt[pos]);
		cur[pos] = 0;
	}

	cout << answ << '\n';
}

