	vector<vector<int>> priorities(n, vector<int>(m));
	for(int i = 0; i < n; ++i){
		for(int j = 0; j < m; ++j){
			cin >> priorities[i][j];
			--priorities[i][j];
		}
	}
	int answer = n;
	vector<bool> alive(m, true);
	for(int iter = 0; iter < m; ++iter){
		vector<int> b(m);
		for(int i = 0; i < n; ++i){
			for(const int s : priorities[i]){
				if(alive[s]){
					++b[s];
					break;
				}
			}
		}
		const int x = max_element(b.begin(), b.end()) - b.begin();
		answer = min(answer, b[x]);
		alive[x] = false;
	}
	cout << answer << endl;
	return 0;
}

