int main()
{
	int N, M;
	cin >> N >> M;
	vector<vector<int>> A(N, vector<int>(M));
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < M; j++) {
			cin >> A[i][j]; A[i][j]--;
		}
	}
	int l = 0, r = N;
	while (l + 1 < r) {
		int c = (l + r) / 2;
		vector<int> v(N);
		vector<int> ex(M);
		bool flag = true;
		int cnt = M;
		while (true) {
			vector<int> cc(M);
			int ma = 0, val = 0;
			for (int i = 0; i < N; i++) {
				cc[A[i][v[i]]]++;
				if (ma < cc[A[i][v[i]]]) {
					ma = cc[A[i][v[i]]];
					val = A[i][v[i]];
				}
			}
			if (ma <= c) {
				break;
			}
			else {
				ex[val] = 1;
				cnt--;
			}
			if (cnt == 0) {
				flag = false;
				break;
			}
			for (int i = 0; i < N; i++) {
				while (ex[A[i][v[i]]]) {
					v[i]++;
				}
			}
		}
		if (flag) {
			r = c;
		}
		else {
			l = c;
		}
	}
	cout << r << endl;
	return 0;
}

