bool abl(int x)
{
	tot = m;
	for(int i = 1; i <= m; i++) hav[i] = true, peo[i] = 0;
	for(int i = 1; i <= n; i++) peo[like[i][1]]++, cho[i] = 1;
	while(tot > 0)
	{
		int w = 0;
		for(int i = 1; i <= m; i++)
			if(peo[i] > x) { w = i; break; }
		if(w == 0) return true;
		hav[w] = false, tot--, peo[w] = 0;
		if(tot == 0) break;
		for(int i = 1; i <= n; i++)
			if(like[i][cho[i]] == w)
			{
				while(not hav[like[i][cho[i]]]) cho[i]++;
				peo[like[i][cho[i]]]++;
			}
	}
	return false;
}
