        int max_ind = -1;
        for (int h = 0; h < M; h++) {
            if (maxi < num_[h]) {
                maxi = num_[h];
                max_ind = h;
            }
        }
        if (maxi <= n) {
            return true;
        }
        assert(max_ind >= 0);
        for (int h = 0; h < N; h++) {
            if (prefer[h][ind[h]] == max_ind) {
                ind[h]++;
            }
        }
    }
    return false;
}

