        }
    }

    int inf = 0;
    int sup = N;
    while (inf < sup) {
        const int mid = (inf + sup) / 2;
        if (ok(mid)) {
            sup = mid;
        } else {
            if (inf == mid) {
                break;
            }
            inf = mid;
        }
    }
    cout << sup << endl;
    return 0;
}

