			for (int j = 0; j < m; ++j)
			{
				if (!visited[a[i][j]])
				{
					if (j < chosenSport)
					{
						chosenSport = j;
						++values[a[i][j]];

						if (values[a[i][j]] > popularSport)
						{
							popularSport = values[a[i][j]];
							indexOfPopularSport = a[i][j];
						}
					}
				}
			}
		}

		if (popularSport < ans)
			ans = popularSport;

		visited[indexOfPopularSport] = true;
	}

	std::cout << ans;
