    cin >> n >> m;
    for(int i = 0; i < n; i++){
        for(int j = 0; j < m; j++){
            cin >> mat[i][j];
        }
    }
    int best = n;
    for(int i = 0; i < m; i++){
        vector<int> cur(n, 0);
        vector<int> mx(m, 0);
        vector<int> wh(n, 0);
        for(int k = 0; k < n; k++){
            cur[k] = mat[k][i];
            mx[i]++;
            wh[k] = i;
        }
        int ans = n;
        for(int j = i + 1; j < m; j++){
            for(int k = 0; k < n; k++){
                if(mat[k][j] > cur[k]){
                    mx[wh[k]]--;
                    mx[j]++;
                }
            }
            int maxx = 0;
            for(auto u: mx) maxx = max(maxx, u);
            if(maxx < ans){
                ans = maxx;
                for(int k = 0; k < n; k++){
                    if(mat[k][j] > cur[k]){
                        cur[k] = mat[k][j];
                        wh[k] = j;
                    }
                }
            }
            else{
                for(int k = 0; k < n; k++){
                    if(mat[k][j] > cur[k]){
                        mx[wh[k]]++;
                        mx[j]--;
                    }
                }
            }
        }
        best = min(ans, best);
    }
    cout << best << endl;
    return 0;
}

