    cin >> n >> m;
    FOR(i,n){
        FOR(j,m){
            cin >> grid[i][j];
            grid[i][j]--;
        }
    }
   // vi x;FOR(i,n)x.pb(i);
    FOR(i,n)take[i] = 1;
    recurse();
    cout << best << endl;
}


