	FOR(i, 0, n)
		if (wanted[i] != -1)
			t[wanted[i]]++;

	int ma = 0;
	for (auto i : t)
		ma = max(ma, i.second);

	if (ma <= ans)
		return true;

	for (auto i : t)
		if (i.second > ans)
			is[i.first] = false;

	int cc = 0;
