					wanted[i] = a[i][j];
					ch = true;
					break;
				}
			if (!ch)
				wanted[i] = -1;
		}
	}
	return check(ans);
}

int solve(int l, int r)
{
	is.assign(m, true);
	wanted.assign(n, 0);
	FOR(i, 0, n)
		wanted[i] = a[i][0];

	if (r - l <= 1)
		if (check(l))
			return l;
		else
			return r;
	int mi = (l + r) / 2;
	if (check(mi))
		return solve(l, mi);
	else
		return solve(mi, r);
}

