using namespace std;

class TaskB {
public:
	void solve(std::istream& in, std::ostream& out) {
		int n, m;
		in >> n >> m;
		auto a = make_vector<int>(n, m, 0);

		for (int i: range(n)) {
			for (int j: range(m)) {
				in >> a[i][j];
				--a[i][j];
			}
		}

		auto can = [&](int mx) {
			vector<int> pos(n);
			vector<int> used(m);

			while (true) {
				vector<int> cnt(m);
				for (int i: range(n)) {
					while (pos[i] < m && used[a[i][pos[i]]]) {
						++pos[i];
					}
					if (pos[i] == m) {
						return false;
					}
					++cnt[a[i][pos[i]]];
				}
				bool all_ok = true;
				for (int i: range(m)) {
					if (cnt[i] > mx) {
						all_ok = false;
						used[i] = true;
					}
				}
				if (all_ok) {
					return true;
				}
			}
		};

		int l = 0, r = n;
		while (r - l > 1) {
			int M = (l + r) / 2;
			if (can(M)) {
				r = M;
			}  else {
				l = M;
			}
		}
		out << r << "\n";
	}
};


int main() {
	std::ios_base::sync_with_stdio(false);
	TaskB solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	in.tie(nullptr);
	out << std::fixed;
	out.precision(20);
	solver.solve(in, out);
	return 0;
}

