int gi() {
    int x=0,o=1;char ch=getchar();
    while((ch<'0'||ch>'9')&&ch!='-') ch=getchar();
    if(ch=='-') o=-1,ch=getchar();
    while(ch>='0'&&ch<='9') x=x*10+ch-'0',ch=getchar();
    return x*o;
}
int n,m,a[N][N],cnt[N],ban[N];
bool check(int mid) {
    memset(ban,0,sizeof(ban));
    int t=m;
    for(int i=1;i<=n;i++) ++cnt[a[i][1]];
    while(t) {
        int p=0;
        for(int i=1;i<=m;i++) if(cnt[i]>cnt[p]) p=i;
        if(cnt[p]<=mid) break;
        ban[p]=1;
        memset(cnt,0,sizeof(cnt));
        for(int i=1;i<=n;i++)
            for(int j=1;j<=m;j++)
                if(!ban[a[i][j]]) { ++cnt[a[i][j]];break; }
        --t;
    }
    return t>0;
}
int main() {
    n=gi(),m=gi();
    for(int i=1;i<=n;i++)
        for(int j=1;j<=m;j++) a[i][j]=gi();
    int l=1,r=n,ret=n;
    while(l<=r) {
        int mid=(l+r)>>1;
        if(check(mid)) ret=mid,r=mid-1;
        else l=mid+1;
    }
    printf("%d\n",ret);
    return 0;
}

