int n, m;
int mat[300][300];
int mat2[301][301];
char in[300];
vector<int> have(300, 0);
vector<int> curmx(300, 0);
vector<int> where(300, 0);

int main()
{
    ios_base::sync_with_stdio(0);
    cin >> n >> m;
    for(int i = 0; i < n; i++){
        for(int j = 0; j < m; j++){
            cin >> mat[i][j];
            mat2[i][ mat[i][j] ] = j;
        }
    }
    int best = 0;
    for(int i = 0; i < m; i++) in[i] = true;
    for(int i = 0; i < n; i++){
        for(int j = 0; j < m; j++){
            if(mat[i][j] == m){
                have[j]++;
                best = max(best, have[j]);
                curmx[i] = m;
                where[i] = j;
            }
        }
    }
    while(1){
        int curDelete = -1;
        int bestAns = best;
        for(int i = 0; i < m; i++){
            if(in[i]){
                int here = 0;
                for(int j = 0; j < n; j++){
                    if(mat[j][i] == curmx[j]){
                        have[where[j]]--;
                        int cur = curmx[j] - 1;
                        while(1){
                            int sp = mat2[j][cur];
                            if(in[sp]) break;
                            cur--;
                        }
                        int sp = mat2[j][cur];
                        have[sp]++;
                    }
                }
                for(int j = 0; j < m; j++){
                    here = max(here, have[j]);
                }
                if(here < bestAns){
                    bestAns = here;
                    curDelete = i;
                }
                for(int j = 0; j < n; j++){
                    if(mat[j][i] == curmx[j]){
                        have[where[j]]++;
                        int cur = curmx[j] - 1;
                        while(1){
                            int sp = mat2[j][cur];
                            if(in[sp]) break;
                            cur--;
                        }
                        int sp = mat2[j][cur];
                        have[sp]--;
                    }
                }
            }
        }
        if(curDelete == -1) break;
        for(int j = 0; j < n; j++){
            if(mat[j][curDelete] == curmx[j]){
                have[where[j]]--;
                int cur = curmx[j] - 1;
                while(1){
                    int sp = mat2[j][cur];
                    if(in[sp]) break;
                    cur--;
                }
                int sp = mat2[j][cur];
                have[sp]++;
                curmx[j] = sp;
            }
        }
        in[curDelete] = false;
        int here = 0;
        for(int j = 0; j < m; j++){
            here = max(here, have[j]);
        }
        best = here;
    }
    cout << best << endl;
    return 0;
}

