bool is_active[302], bad[302];


bool possible(int mid){

    memset(cnt, 0, sizeof(cnt));
    memset(is_active, 0, sizeof(is_active));
    memset(bad, 0, sizeof(bad));

    for(int i=1;i<=n;i++)
        while(!qq[i].empty())   qq[i].pop();

    for(int j=1;j<=m;j++){

        for(int i=1;i<=n;i++){
            int val = arr[i][j];
            if(bad[val])    continue;
            qq[i].push(val);
            if(qq[i].front() == val)    cnt[val]++;
            if(!bad[val] && cnt[val] > mid) bad[val] = true;
        }

        bool another_iteration = true;
        while(another_iteration){
            another_iteration = false;
            for(int i=1;i<=n;i++){
                bool atleast_one = false;
                while(!qq[i].empty() && bad[qq[i].front()]){
                    atleast_one = true;
                    qq[i].pop();
                }
                if(atleast_one && !qq[i].empty()){
                    cnt[qq[i].front()]++;
                    if(!bad[qq[i].front()] && cnt[qq[i].front()] > mid){
                        bad[qq[i].front()] = true;
                        another_iteration = true;
                    }
                }
            }
        }

// cout<<"after j = "<<j<<endl;
// cout<<"bad: ";for(int k=1;k<=m;k++) cout<<bad[k]<<" ";cout<<endl;
// cout<<"qq: ";for(int k=1;k<=n;k++) cout<<(qq[k].empty()?-1:qq[k].front())<<" ";cout<<endl;

    }

    for(int i=1;i<=n;i++)
        if(qq[i].empty())
            return false;
    return true;
}



