	memset(ct, 0, sizeof ct);
	for (int i = 1;i <= n;++i)
	{
		pos[i] = 1;
		ct[a[i][1]]++;
		if (ct[a[i][1]] > x) tf = false;
	}
	if (tf) return true;
	while (true)
	{
		for (int i = 1;i <= m;++i) if (ct[i] > x) ok[i] = false;
		for (int i = 1;i <= n;++i)
		{
			while (pos[i] <= m && !ok[a[i][pos[i]]]) pos[i]++;
			if (pos[i] == m + 1) return false;
		}
		tf = true;
		memset(ct, 0, sizeof ct);
		for (int i = 1;i <= n;++i)
		{
			ct[a[i][pos[i]]]++;
			if (ct[a[i][pos[i]]] > x)
			{
				tf = false;
				break;
			}
		}
