int n, m;
vector<vector<int>> a(300, vector<int>(300, -1));

int solve(vector<int>& indice){
    int res = 1e5;

    set<int> keyset;
    map<int, int> mapp;
    rep(i, n){
        int k = a[i][indice[i]];
        keyset.insert(k);
        mapp[k]++;
    }

    int maxx = 0;
    for(auto k : keyset)    maxx = max(mapp[k], maxx);
    res = min(res, maxx);
    set<int> keys;
    for(auto k : keyset){
        if(maxx == mapp[k])    keys.insert(k);
    }

    for(auto k : keys){
        vector<int> v = indice;
        bool ok = true;
        rep(i, n){
            if(a[i][v[i]] == k){
                v[i]++;
                if(m <= v[i]){
                    ok = false;
                    break;
                }
            }
        }

        if(ok)  res = min(res, solve(v));
    }

    return res;
}

