        if(!omitted[k]){
          if(max_like<person[k]){
            max_like=person[k];
            join_id=k;
          }
        }
      }
      if(join_id==-1){
        cout<<result<<endl;
        return 0;
      }
      contestants[join_id]++;
    }

    int max_contestants=0;
    std::vector<int> omit_id;
    for(int j=0;j<m;j++){
      if(max_contestants<contestants[j]){
        omit_id.clear();
        omit_id.push_back(j);
        max_contestants=contestants[j];

      }else if(max_contestants==contestants[j]){
        omit_id.push_back(j);
      }
    }
