int N, M, arr[305][305];
int No[305];
int solve() {
	int ret = N;
	for (int c = M; c;) {
		for (int j = 1; j <= M; ++j) {
			if (No[j] != -1) {
				No[j] = 0;
			}
		}
		for (int i = 1; i <= N; ++i) {
			for (int j = 1; j <= M; ++j) {
				if (No[arr[i][j]] != -1) {
					No[arr[i][j]]++;
					break;
				}
			}
		}
		int x = 0;
		for (int j = 1; j <= M; ++j) {
			if (No[j] != -1) x = max(x, No[j]);
		}
		ret = min(x, ret);
		for (int j = 1; j <= M; ++j) {
			if (No[j] == x) {
				No[j] = -1;
				c--;
			}
		}
	}
	return ret;
}
