int cnt[N];

int calc() {
	memset(check, 0, sizeof(check));
	for (int i = 1; i <= m; ++i) {
		cnt[i] = 0;
		if (state[i] == 0) {
			for (int j = 1; j <= n; ++j) {
				check[j][a[j][i]] = 1;
			}
		}
	}


	for (int i = 1; i <= n; ++i) {
		int f = -1;
		for (int j = 1; j <= m; ++j) {
			if (check[i][j]) {
				f = j;
				break;
			}
		}
		if (f == -1) return inf;
		cnt[b[i][f]]++;
	}

	int mx = 0;
	for (int i = 1; i <= m; ++i) if (state[i] == 0) {
		if (!mx || cnt[mx] < cnt[i]) mx = i;
	}
	state[mx] = 1;
//	for (int i  )
//	cout << mx << ' ' << cnt[mx] << '\n';
	return cnt[mx];
}

