int main()
{
	int N, M;
	cin >> N >> M;
	int** arr = new int*[N];
	for (int i = 0; i < N; i++)
	{
		arr[i] = new int[M];
		for (int j = 0; j < M; j++)
		{
			int tmp;
			cin >> tmp;
			arr[i][j] = tmp;
		}
	}

	//init point
	int *point = new int[N];
	bool *deleted = new bool[M];
	for (int i = 0; i < N; i++)
		point[i] = 0;
	for (int i = 0; i < M; i++)
		deleted[i] = false;

	//compute
	int min_people = 0x0fffffff;
	int count = M;
	while (count > 0)
	{
		vector<int> people(M, 0);
		int max_people = -1;
		for (int j = 0; j < N; j++)
		{
			while (deleted[arr[j][point[j]] - 1])
				point[j]++;
			max_people = max(max_people, ++people[arr[j][point[j]] - 1]);
		}
		for (int i = 0; i < M; i++)
		{
			if (people[i] == max_people)
			{
				deleted[i] = true;
				count--;
			}
		}
		min_people = min(min_people, max_people);
	}
	cout << min_people << endl;

	delete[] deleted;
	delete[] point;

	for (int i = 0; i < N; i++)
	{
		delete[] arr[i];
	}
	delete[] arr;
}

