ll n, m;
pair<ll,ll> calc(vector<int> &removed, vector<vector<ll>> &a){

    vector<ll> cnt(m, 0);

    rep(i, n){
        rep(j, m){
            if(removed[a[i][j]]) continue;
            cnt[a[i][j]]++;
            break;
        }
    }

    ll maidx = 0;
    ll ma = 0;
    rep(i, m){
        if(removed[i]) continue;
        if(ma < cnt[i]){
            maidx = i;
            ma = cnt[i];
        }
    }

    return {ma, maidx};
}
bool check(vector<int> &removed){
    bool res = false;;
    rep(i, m){
        if(!removed[i]){
            res = true;
        }
    }

    return res;
}
