    rep(i, n){
        rep(j, m){
            cin >> a[i][j];
            a[i][j]--;
        }
    }
    ll ans = INF;
    vector<int> removed(m, 0);
    pair<ll,ll> result = calc(removed, a);
    ans = min(ans, result.first);
    removed[result.second] = 1;

    while(check(removed)){
        result = calc(removed, a);
        ans = min(ans, result.first);
        removed[result.second] = 1;
    }
    cout << ans << endl;
    return 0;

}

