using namespace std;
int N, M;
int a[305][305];
int main() {
  ios::sync_with_stdio(false);
  cin >> N >> M;
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < M; ++j) {
      int c;
      cin >> c;
      c--;
      a[i][j] = c;
    }
  }
  vector<int> valid(M, 1);
  vector<vector<int>> head(M);
  vector<int> pos(M, 0);
  int ret = INT_MAX;
  for (int row = 0; row < N; ++row) {
    int h = a[row][0];
    head[h].push_back(row);
  }

  int cmax = 0;
  int ci = -1;
  for (int i = 0; i < M; ++i) {
    if (head[i].size() > cmax) {
      cmax = head[i].size();
      ci = i;
    }
  }

  ret = min(ret, cmax);
  int last = M;
  while (last > 1) {
    valid[ci] = 0;
    for (auto row : head[ci]) {
      int &ind = pos[row];
      while (valid[a[row][ind]] == 0) ind++;
      head[a[row][ind]].push_back(row);
    }

    head[ci].clear();
    int cmax = 0;
    for (int i = 0; i < M; ++i) {
      if (head[i].size() > cmax) {
        cmax = head[i].size();
        ci = i;
      }
    }

    ret = min(ret, cmax);
    last--;
  }

  cout << ret << endl;
}

