int sum[maxn];
bool dp[maxn*maxn+5];
bool cal(int mid){
    string buf="";string neu="0";
    for(int con=1;con<=m;con++)
    {
        rfl.clear();
        for(int i=1;i<=n;i++)
        {
            buf="";
            for(int j=1;j<=m;j++)
            {
                if(a[i][j]==con) break;
                neu+=a[i][j];
                buf+=neu;
                neu="0";
            }
            sort(buf.begin(),buf.end());
            rfl[buf]++;
        }
        int cnt=0,ALL=0;
        for(map<string ,int >::iterator ite=rfl.begin();ite!=rfl.end();ite++)
            {sum[++cnt]=ite->second;ALL+=sum[cnt];}
        memset(dp,0,sizeof(dp));
        dp[0]=dp[sum[1]]=true;
        for(int i=2;i<=cnt;i++)
            for(int j=sum[i];j<=ALL;j++)
            {
                if(dp[j]) continue;
                else dp[j]|=dp[j-sum[i]];
            }
        if(dp[mid]){return true;}
    }
    return false;
}
