{
    scanf("%d%d",&n,&m);
    for(int i=1;i<=n;i++)
        for(int j=1;j<=m;j++)
            scanf("%d",&a[i][j]);
    int l=1,r=n;
    while(r-l>1){
        int mid=l+(r-l)/2;
        if(cal(mid)) r=mid;
        else l=mid+1;
    }
    printf("%d\n",r);
    return 0;
}

