using P = pair<int, int>;

bool check(const vec<int, 2>& A, const vec<int, 2>& B, int L) {
  int N = A.size(), M = A[0].size();
  vector<set<P>> top(A.size());
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < M; j++) top[i].insert(P(j, A[i][j]));
  }
  int rem = M;
  while (rem > 0) {
    vector<int> cnt(M, 0);
    for (int i = 0; i < N; i++) {
      auto p = *top[i].begin();
      ++cnt[p.snd];
    }
    bool cont = false;
    for (int k = 0; k < M; k++) {
      if (cnt[k] > L) {
        cont = true;
        --rem;
        for (int i = 0; i < N; i++) top[i].erase(P(B[i][k], k));
      }
    }
    if (!cont) {
      return true;
    }
  }
  return false;
}

