bool check(int k) {
    memset(idx, 0, sizeof(idx));
    memset(rem, true, sizeof(rem));
    vector<int> s;
    for (int i = 0; i < n; i++) {
        b[a[i][0]].push_back(i);
    }
    while (true) {
        s.clear();
        for (int i = 0; i < m; i++) {
            if (b[i].size() > k) {
                s.push_back(i);
                rem[i] = false;
            }
        }
        if (s.size() == 0) return true;
        for (int i = 0; i < s.size(); i++) {
            int v = s[i];
            for (int j = 0; j < b[v].size(); j++) {
                int w = b[v][j];
                while (idx[w] < m && !rem[a[w][idx[w]]]) idx[w]++;
                if (idx[w] >= m) return false;
                b[a[w][idx[w]]].push_back(w);
            }
            b[v].clear();
        }
    }
    return false;
}

int solve() {
    int lb = 0, ub = m;
    while (ub - lb > 1) {
        int mid = (lb + ub) / 2;
        if (check(mid)) {
            ub = mid;
        } else {
            lb = mid;
        }
    }
    return ub;
}

