bool possible(vector<queue<int>> A, int k){
  cout << "k = " << k << endl;
  int N = A.size();
  int M = A[0].size();
  vector<bool> use(M, true);
  for (int i = 0; i < M - 1; i++){
    map<int, int> freq;
    int next = -1;
    for (int j = 0; j < N; j++){
      while (!use[A[j].front()]){
        A[j].pop();
      }
      freq[A[j].front()]++;
      if (freq[A[j].front()] > k){
        next = A[j].front();
      }
    }
    if (next == -1){
      return true;
    } else {
      use[next] = false;
    }
  }
  return false;
}
int main(){
  int N, M;
  cin >> N >> M;
