      A[i].push(a);
    }
  }
  int tv = N;
  int fv = 0;
  while (tv - fv > 1){
    int mv = (tv + fv) / 2;
    if (possible(A, mv)){
      tv = mv;
    } else {
      fv = mv;
    }
  }
  cout << tv << endl;
}

