const int MaxN = 300;

using namespace std;
int n , m , vis[MaxN + 5] , cnt[MaxN + 5];
int a[MaxN + 5][MaxN + 5];
void Init(){
	memset(vis , 0 , sizeof(vis));
	for(int i = 1;i <= n;i++) {
		for(int j = 1;j <= m;j++){
			scanf("%d" , &a[i][j]);
		}
	}
	for(int i = 1;i <= n;i++) cnt[i] = 1;
}
void Solve(){
	int Min = 1 << 30;
	while(1){
		int Max = 0 , pos = 0;
		for(int i = 1;i <= m;i++) vis[i] = 0;
		for(int i = 1;i <= n;i++){
			if(++vis[a[i][cnt[i]]] > Max){
				Max = vis[a[i][cnt[i]]];
				pos = a[i][cnt[i]];
			}
		}
		Min = min(Min , Max);
		for(int i = 1;i <= n;i++){
			if(a[i][cnt[i]] == pos){
				if(cnt[i] < m) cnt[i]++;
			}
		}
		int tot = 0;
		for(int i = 1;i <= n;i++) {
			if(cnt[i] >= m) tot++;
		}
		if(tot >= n) break;
	}
	printf("%d\n" , Min);
}
int main()
{
	while(~scanf("%d%d" , &n , &m)){
		Init();
		Solve();
	}
}

