/* do your best */
pair<int, int> culc(vector<vector<int>> a, vector<bool> canUse) {

  int n = a.size();
  int m = a[0].size();
  vector<int> score(m, 0);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (!canUse[a[i][j]]) continue;
      score[a[i][j]]++;
      break;
    }
  }

  int val = 0;
  int id;
  for (int i = 0; i < m; i++) {
    if (val < score[i]) {
      val = score[i];
      id = i;
    }
  }

  return make_pair(val, id);
}

