      a[i][j]--;
    }
  }

  vector<bool> canUse(m, true);
  int ans = n + 1;
  while (1) {

    // 全部使えないなら，終わり
    bool end = true;
    for (int i = 0; i < m; i++) {
      if (canUse[i]) end = false;
    }
    if (end) break;

    int tmp;
    int id;
    tie(tmp, id) = culc(a, canUse);
    ans = min(ans, tmp);
    canUse[id] = false;
  }

  cout << ans << endl;
  return 0;
}

