int solve(int step = m) {
  int ret = 1 << 30;
  if (step == 0) return ret;
  for (int i = 0; i <= m; i++) cnt[i] = 0;
  int best = 1;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      cnt[a[i][j]]++;
      if (a[i][j] > 0 && cnt[a[i][j]] > cnt[best]) best = a[i][j];
      if (a[i][j] > 0) break;
    }
  }
  for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) if (a[i][j] == best) a[i][j] = 0;
  int cnt_best = cnt[best];
  ret = min(cnt_best, solve(step - 1));
  return ret;
}

