void rec(i32 ni) {
    if (ni == n) {
        i32 t = 0;
        upto(1, m, mi) {
            t = max(t, c[mi]);
        }
        ans = min(ans, t);
        return;
    }
    i32 max_mi = 0;
    times(m, mi) {
        if (c[a[ni][mi]] < 0) continue;
        if (mi > 0) {
            if (c[a[ni][mi-1]] > 0) break;
            max_mi = mi;
            c[a[ni][mi-1]]--;
        }
        c[a[ni][mi]]++;
        rec(ni+1);
        c[a[ni][mi]]--;
    }
    times(max_mi, mi) {
        c[a[ni][mi]]++;
    }
}

