PII max_sports(vector<vector<int>> &A, vector<int> &ptr)
{
    map<int, int> cnt;
    int mx = 0, mx_idx = -1;

    rep(i, A.size()) {
        int sp = A[i][ptr[i]];
        cnt[sp]++;
        if (cnt[sp] >= mx) {
            mx = cnt[sp];
            mx_idx = sp;
        }
    }

    return PII(mx, mx_idx);
}

