  rep(i, n) if(used[i] == 0) return 0;
  return 1;
}

bool can(int x){
  vector<bool> used(N, 0);
  vector<bool> dont(M, 0);
  while(!allUsed(used)){
    if(allUsed(dont)) return 0;
    vector<int> cnt(M, 0);
    rep(i, N){
      if(used[i]) continue;
      rep(j, M){
        if(dont[A[i][j]]) continue;
        cnt[A[i][j]]++;
        break;
      }
    }
    bool l = 0;
    rep(i, M) if(cnt[i] > x){
      dont[i] = 1;
      l = 1;
    }
    if(l) continue;
    return 1;
  }
  return 1;
}

int main(void){
  cin >> N >> M;
  rep(i, N)rep(j, M){
    cin >> A[i][j];
    A[i][j]--;
  }
  int ng = 0, ok = M;
  while(ok - ng > 1){
    int mid = (ng + ok) / 2;
    if(can(mid)) ok = mid;
    else ng = mid;
  }
  cout << ok << endl;
}

