bool chk(int mid){
	mem(del,0);
	mem(cnt,0);
	rep(i,1,n){
		p[i]=1;
		++cnt[a[i][p[i]]];
	}
	while(true){
		int cur=0;
		rep(i,1,m)if(!del[i]){
			if(cnt[i]<=mid)continue;
			cur=i;
			del[i]=1;
			break;
		}
		if(!cur)break;
		rep(i,1,n)if(a[i][p[i]]==cur){
			--cnt[a[i][p[i]]];
			for(++p[i];del[a[i][p[i]]];++p[i]);
			if(p[i]>m)return false;	
			++cnt[a[i][p[i]]];
		}
	}
	return true;
}

