namespace tre
{
	inline bool check_min(int a,int &b){return (a<b)?(b=a,1):0;}
	inline bool check_max(int a,int &b){return (a>b)?(b=a,1):0;}
	const int N=305,INF=2147483647;
	int s[N][N],ind[N],cnt[N];
	bool sel[N];
	int n,m,ans;
	int push()
	{
		for(int i=1;i<=n;i++)
			while(!sel[s[i][ind[i]]] && ind[i]<=m)ind[i]++;
		memset(cnt,0,sizeof(cnt));
		for(int i=1;i<=n;i++)
			cnt[s[i][ind[i]]]++;
		int ret=0,tmp=0;
		for(int i=1;i<=m;i++)
			if(check_max(cnt[i],tmp))ret=i;
		check_min(tmp,ans);
		return ret;
	}
	void initialize()
	{
		scanf("%d%d",&n,&m);
		for(int i=1;i<=n;i++)
			for(int j=1;j<=m;j++)
				scanf("%d",&s[i][j]);
	}
	void solve()
	{
		initialize();
		for(int i=1;i<=m;i++)
			sel[i]=1,ind[i]=1;
		ans=INF;
		for(int i=1;i<=m;i++)
		{
			int p=push();
			sel[p]=0;
		}
		printf("%d\n",ans);
	}
}
