	for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) {
		cin >> A[i][j];
		A[i][j]--;
	}

	int l = 0, r = m;
	while (r - l > 1) {
		int mid = (l + r) / 2;

		vector<int> ind(n), fail(m);

		int ok = 1;
		for (int it = 0; ; it++) {
			for (int i = 0; i < n; i++) if (ind[i] != -1) {
				while (ind[i] < m && fail[A[i][ind[i]]]) ind[i]++;
				if (ind[i] == m) ok = 0;
			}	
			if (!ok) break;

			map<int, int> cnt;
			for (int i = 0; i < n; i++) if (ind[i] != -1) {
				cnt[A[i][ind[i]]]++;
			}

			if (cnt.empty()) break;

			int bad = 0;
			for (auto c : cnt) {
				if (c.second > mid) {
					fail[c.first] = 1;
					bad = 1;
				}
			}
			if (!bad) {
				for (auto c : cnt) {
					for (int i = 0; i < n; i++) if (ind[i] != -1 && A[i][ind[i]] == c.first)
						ind[i] = -1;
				}
			}
		}

		if (*max_element(ind.begin(), ind.end()) > -1 || !ok) l = mid;
		else r = mid;
	}
	cout << r << "\n";
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
using vec = vector<int>;
using mat = vector<vec>;

int N, M;
mat A;

int solve(vector<bool> &v) {
  vec cnt(M, 0);
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < M; j++) {
      if (v[A[i][j]]) {
        cnt[A[i][j]]++;
        break;
      }
    }
  }
  int P, Q = 0;
  for (int i = 0; i < M; i++) {
    if (Q < cnt[i]) {
      P = i;
      Q = cnt[i];
    }
  }
  if (Q == 0) {
    return M;
  } else {
    v[P] = false;
    return min(solve(v), Q);
  }
}

main() {
  cin >> N >> M;
  A.resize(N, vec(M));
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < M; j++) {
      int a; cin >> a;
      A[i][j] = --a;
    }
  }
  vector<bool> sports(M, true);
  cout << solve(sports) << endl;
}

