const int INF=1e9;

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n,m;
	cin>>n>>m;
	vector<vector<int>> a(n,vector<int>(m));
	int ans=0;
	map<int,int> cnt;
	rep(i,n){
		rep(j,m){
			cin>>a[i][j];
		}
		cnt[a[i][0]]++;
	}
	priority_queue<Pi> que;
	for(auto itr:cnt){
		chmax(ans,itr.se);
		que.push(Pi(itr.se,itr.fi));
	}
	int ret=m-1;
	set<int> ng;
	while(ret--){
		Pi v=que.top();
		while(!que.empty() && que.top().fi==v.fi){
			ng.insert(que.top().se);
			que.pop();
		}
		map<int,int> now;
		rep(i,n){
			rep(j,m){
				if(ng.count(a[i][j])) continue;
				now[a[i][j]]++;
				break;
			}
		}
		int nans=0;
		for(auto itr:now){
			chmax(nans,itr.se);
			que.push(Pi(itr.se,itr.fi));
		}
		chmin(ans,nans);
	}
	cout<<ans<<endl;
}

