bool check(ll x) { // x以下
  for (ll i = 0; i < m; i++) people[i].clear(), removed[i] = false;
  for (ll i = 0; i < n; i++) {
    now[i] = 0;
    people[a[i][now[i]]].push_back(i);
  }
  for (ll k = 0; k < m-1; k++) {
    ll mx = 0;
    for (ll i = 0; i < m; i++) {
      if (people[mx].size() < people[i].size()) mx = i;
    }
    if (people[mx].size() <= x) return true;
    removed[mx] = true;
    for (ll i : people[mx]) {
      while (removed[a[i][now[i]]]) now[i]++;
      people[a[i][now[i]]].push_back(i);
    }
    people[mx].clear();
  }
  return false;
}

