int solve(){
	int ans = n;

	memset(del, 0, sizeof(del));

	int key;

	for(int k=1; k<=m; k++){
		key = -1;
		for(int i=1; i<=m; i++)	cnt[i] = 0;
		for(int i=1; i<=n; i++){
			for(int j=1; j<=m; j++){
				if(del[j])	continue;
				if(key==-1 || a[i][j]>a[i][key])	key = j;
			}
			cnt[key]++;
		}
		key = -1;
		for(int i=1; i<=m; i++){
			if(del[i])	continue;
			if(key==-1 || cnt[i] > cnt[key])	key = i;
		}
		ans = min(ans, cnt[key]);
		del[key] = 1;
	}

	return ans;
}

