const int MAX_SIZE = 310;

#define pb push_back

vector<int> arr[MAX_SIZE];

vector<bool> deleted(MAX_SIZE);

vector<int> taken[MAX_SIZE];

void delUpd(int x)
{
	int i = 0;
	while(deleted[arr[x][i]] == true) i++;
	taken[arr[x][i]].pb(x);
}

int main()
{
	int n, m;
	cin >> n >> m;
	int x;
	for(int i = 1; i <= m; i++)
		deleted[i] = false;
	for(int i = 1; i <= n; i++)
	{
		for(int j = 0; j < m; j++)
		{
			cin >> x;
			arr[i].pb(x);
		}
	}
	int ans = 1000;
	if(m == 1)
	{
		cout << n << endl;
		return 0;
	}
	for(int j = 1; j <= n; j++)
	{
		delUpd(j);
	}
	for(int i = 1; i < m; i++)
	{
		int next, mm = 0;
		for(int j = 1; j <= m; j++)
		{
			if(taken[j].size() > mm)
			{
				mm = taken[j].size();
				next = j;
			}
		}
		ans = min(ans, mm);
		deleted[next] = true;
		for(auto &j: taken[next])
		{
			delUpd(j);
		}
		taken[next].clear();
	}
	cout << ans << endl;
	return 0;
}

