int N, M;
int G[310][310];

bool solve(int L) {
	int T[310];
	bool D[310];
	memset(D, 0, sizeof(D));
	int rem = M;
	int r = 0;
	while (rem > 0) {
		r++;
		memset(T, 0, sizeof(T));
		for (int i = 0;i < N;i++) {
			bool ok = 1;
			for (int j = 0;j < M && ok;j++) {
				int k = G[i][j];
				if (D[k] == 0) {
					ok = 0;
					T[k]++;
				}
			}
		}
		bool ck = 1;
		for (int i = 1;i <= M;i++) {
			if (T[i] > L) {
				ck = 0;
				D[i] = 1;
				rem--;
			}
		}
		if (ck) return 1;
	}
	return 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin >> N >> M;
    for (int i = 0;i < N;i++) {
    	for (int j = 0;j < M;j++) cin >> G[i][j];
    }
    int s = 0, b = N;
    while (s + 1 < b) {
    	int m = s + (b - s) / 2;
    	if (solve(m)) b = m;
    	else s = m;
    }
    cout << b << endl;
    return 0;
}

