bool check(int x)
{
	memset(vis,0,sizeof(vis));
	while(true)
	{
		memset(cnt,0,sizeof(cnt));
		int num=0;
		for(int i=1;i<=n;i++)
		{
			for(int j=1;j<=m;j++)
			{
				if(!vis[a[i][j]])
				{
					cnt[a[i][j]]++;
					num++;
					break;
				}
			}
		}
		bool flag=true;
		for(int i=1;i<=m;i++)
		{
			if(cnt[i]>x)
			{
				vis[i]=1;
				flag=false;
			}	
		}
		if(num<n)
			return false;
		if(num==n&&flag)
			return true;	
	}
} 
