bool chck(int x) {
    for (int i = 1; i <= m; i++) {
        dl[i] = 0;
        cnt[i] = 0;
    }
    for (int i = 1; i <= n; i++) {
        cnt[a[i][1]]++;
        ll[i] = 1;
    }
    while (1) {
        bool ok = true;
        for (int i = 1; i <= m; i++)
            if (cnt[i] > x) {
                del(i);
                ok = false;
            }
        if (ok) break;
    }
    for (int i = 1; i <= m; i++)
        if (dl[i] == 0) return true;
    return false;
}
