const auto INF = 0x3f3f3f3f;
const int N = 3e2+5;

int a[N][N], n, m, answer, num[N];
int visit[N];

void dfs(int u) {
    if(u == n+1) {
        int sum = 0;
        for(int i=1; i<=m; i++)
            sum = max(sum, num[i]);
        answer = min(answer, sum);
        return;
    }
    int cnt = 0, dis[305];
    for(int i=1; i<=m; i++) {
        if(visit[a[u][i]] == 1) {
            num[a[u][i]]++;
            dfs(u+1);
            num[a[u][i]]--;
            break;
        } else if(visit[a[u][i]] == -1)
            continue;
        visit[a[u][i]] = 1;
        num[a[u][i]]++;
        dfs(u+1);
        num[a[u][i]]--;
        visit[a[u][i]] = -1;
        dis[++cnt] = a[u][i];
    }
    for(int i=1; i<=cnt; i++)
        visit[dis[i]] = 0;
    return;
}

