int N, M;
constexpr int MAX = 300;

bool nibu(int c, vector<queue<int> > A)
{
    set<int> del;
    while (true)
    {
        map<int, int> d;
        for (auto v : A) d[v.front()]++;
        bool endflg = true;
        for (auto k : d) if (k.second > c) {
            del.insert(k.first);
            endflg = false;
        }
        if (endflg) return true;
        for (auto &v : A) while (true) {
            if (del.find(v.front()) == del.end()) break;
            v.pop();
            if (v.empty()) return false;
        }
    }
}

