{
	int i, j, t;
//	freopen ("input.txt", "r", stdin);
	cin >> n >> m;
	for (i = 1; i <= n; i++) {
		for (j = 1; j <= m; j++) {
			scanf ("%d", &a[i][j]);
		}
	}
	l = 1;
	r = n + 1;
	while (l < r) {
		md = (l + r) / 2;
		w = true;
		for (i = 1; i <= n; i++) k[i] = 1;
		for (i = 1; i <= m; i++) z[i] = false;
		while (1) {
			h = true;
			for (i = 1; i <= m; i++) cnt[i] = 0;
			for (i = 1; i <= n; i++) {
