bool check(int x)
{
	memset(ban,0,sizeof ban);
	for(int i=1;i<=n;i++)cur[i]=1;
	for(;;)
	{
		unordered_map<int,int> M;
		for(int i=1;i<=n;i++)
		{
			while(cur[i]<=m&&ban[a[i][cur[i]]])cur[i]++;
			if(cur[i]>m)return false;
			M[a[i][cur[i]]]++;
		}
		bool f=true;
		for(auto i:M)
			if(i.second>x){f=false;ban[i.first]=1;}
		if(f)return true;
	}
}
int main()
{
