int n, m;
vvi a;

vb is;
vi wanted;

bool check(int ans)
{	
	map<int, int> t;
	FOR(i, 0, n)
		if (wanted[i] != -1)
			t[wanted[i]]++;

	int ma = 0;
	for (auto i : t)
		ma = max(ma, i.second);

	if (ma <= ans)
		return true;

	for (auto i : t)
		if (i.second > ans)
			is[i.first] = false;

	int cc = 0;
	FOR(i, 0, m)
		if (is[i])
			cc++;

	if (cc == 0)
		return 0;

	bool ch;
	FOR(i, 0, n)
	{
		ch = false;
		if (wanted[i] != -1)
		{
			FOR(j, 0, m)
				if (is[a[i][j]])
				{
					wanted[i] = a[i][j];
					ch = true;
					break;
				}
			if (!ch)
				wanted[i] = -1;
		}
	}
	return check(ans);
}

int main()
{
	ios_base::sync_with_stdio(false), cin.tie(0), cout.tie(0);
	//freopen("In.txt", "r", stdin);

	cin >> n >> m;
	vi vvv(m);
	a.assign(n, vvv);
	FOR(i, 0, n)
		FOR(j, 0, m)
		cin >> a[i][j], a[i][j]--;

	FOR(ans, 1, n + 1)
	{
		is.assign(m, true);
		wanted.assign(n, 0);
		FOR(i, 0, n)
			wanted[i] = a[i][0];

		if (check(ans))
		{
			cout << ans;
			return 0;
		}
	}

	return 0;
}
