#include <set>
#include <queue>

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n, m;
    cin >> n >> m;
    auto dp = make_v(n, m, 0);
    REP(i, 0, n) {
        REP(j, 0, m) {
            cin >> dp[i][j];
        }
    }
    set<int> s;
    vector<int> process(n, 0);
    queue<int> q;
    int ans = n;
    while (s.size() < m) {
        {
            vector<int> cnt(m, 0);
            REP(i, 0, n) {
                cnt[dp[i][process[i]] - 1]++;
            }
            int mx = *max_element(cnt.begin(), cnt.end());
            REP(i, 0, m) {
                if (cnt[i] == mx) {
                    q.emplace(i + 1);
                }
            }
            chmin(ans, mx);
        }

        while (q.size()) {
            auto t = q.front();
            q.pop();
            s.insert(t);
            if (s.size() == m) continue;

            REP(i, 0, n) {
                while (process[i] < m && s.count(dp[i][process[i]])) {
                    process[i]++;
                }
            }
            vector<int> cnt(m, 0);
            REP(i, 0, n) {
                cnt[dp[i][process[i]] - 1]++;
            }
            int mx = *max_element(cnt.begin(), cnt.end());
            chmin(ans, mx);
        }
    }
    cout << ans << endl;

    return 0;
}

