    memset(cnt,0,sizeof(cnt));
    for (int i=1;n>=i;i++)
    {
        int mx=-1;
        int mx_id = -1;
        for (int j:v)
        {
            if (a[i][j] > mx)
            {
                mx = a[i][j];
                mx_id = j;
            }
        }
        cnt[mx_id]++;
    }
    int mx=-1;
    for (int i:v)
    {
        mx = max(mx,cnt[i]);
    }
    ans = min(ans,mx);
    vector<int> vv;
    bool found = false;
    for (int i:v)
    {
        if (found) vv.push_back(i);
        else if (cnt[i] == mx) found = true;
        else vv.push_back(i);
    }
    solve(vv);
}

