	while ( high - low > 1) {
		mid = (low + high) / 2;
		vector<int> cnt(M+1);
		vector<bool> checked(M+1);
		if (check(mid, cnt, checked, 0) == -1) high = mid;
		else low = mid;
	}
	cout << high << endl;
}

