class Node {
public:
  int id, sum;
  Node(int i, int s) {
    id = i;
    sum = s;
  }
  bool operator<(const Node &rhs) const {
    return this->sum > rhs.sum;
  }
  bool operator>(const Node &rhs) const {
    return this->sum < rhs.sum;
  }
};

vector<bool> b;
int n, m;
vector<vector<int>> a;
vector<int> cnt;

int f(int id) {
  vector<Node> nd;
  for(int j = 0; j < m; j++) {
    Node nds(j, 0);
    nd.push_back(nds);
  }
  for(int j = 0; j < n; j++) {
    if(a[j][cnt[j]] == id) {
      nd[a[j][cnt[j] + 1]].sum++;
    } else {
      nd[a[j][cnt[j]]].sum++;
    }
  }
  sort(nd.begin(), nd.end());
  return nd[0].sum;
}

