      int jid = 0, jma = 0;
      for(int j = 0; j < M; j++){
        if(!done[j]) continue;
        if(A[i][j] > jma) {
          jma = A[i][j];
          jid = j;
        }
      }
      join[jid]++;
    }

    int ma = 0;
    for(int i = 0; i < M; i++){
      ma = max(ma, join[i]);
    }
    ans = min(ans, ma);

    bool cont = false;
    for(int i = 0; i < M; i++){
      if(join[i] == ma){
        done[i] = false;
      }
      if(done[i]) cont = true;
    }
    if(!cont) break;
  }
  cout << ans << endl;
}

