int cur[N], cnt[N];

bool baned[N];

vector<int> pos[N];

bool decrement(int color, int k) {
    //cout << "delete " << color << endl;
    baned[color] = true;
    for (auto x: pos[color]) {
        while (baned[matrix[x][cur[x]]]) {
            cur[x]++;
            if (cur[x] >= m) {
                return false;
            }
        }
        cnt[matrix[x][cur[x]]]++;
        pos[matrix[x][cur[x]]].pb(x);
        cnt[color]--;
        //cout << color << "-- " << cnt[color] << endl;
        //cout << matrix[x][cur[x]] << "++ " << cnt[matrix[x][cur[x]]] << endl;
        if (cnt[matrix[x][cur[x]]] > k) {
            bool res = decrement(matrix[x][cur[x]], k);
            //cout << "deleted\n";
            if (!res) {
                return false;
            }
        }
    }
    return true;
}

bool check(int k) {
    //cout << endl << endl;
    //cout << "!!! " << k << endl;
    fill(cur, cur + N, 0);
    fill(cnt, cnt + N, 0);
    fill(baned, baned + N, false);
    for (int i = 1; i <= m; i++) {
        pos[i].clear();
    }
    for (int i = 0; i < n; i++) {
        while (baned[matrix[i][cur[i]]]) {
            cur[i]++;
            if (cur[i] >= m) {
                return false;
            }
        }
        cnt[matrix[i][cur[i]]]++;
        pos[matrix[i][cur[i]]].pb(i);
        //cout << matrix[i][cur[i]] << "++ " << cnt[matrix[i][cur[i]]] << endl;
