ll bisection(ll low, ll high, std::function<bool(ll)> check) {
	if (high - low == 1) return high;
	ll mid = (high + low) / 2;
	if (check(mid)) return bisection(low, mid, check);
	else            return bisection(mid, high, check);
}

signed main() {
	INIT;
	VAR(int, n, m);
	MAT(int, a, n, m);

	auto check = [&](int k) {
		std::vector<int> used(m, false);
		REP(j, m) {
			int cnt = 0;
			REP(i, n) {
				if (a[i][j] == m) ++cnt;
			}
			if (cnt <= k) used[j] = true;
		}
		std::vector<int> max(n, -1);
		REP(i, n) REP(j, m) {
			if (!used[j]) continue;
			CHMAX(max[i], a[i][j]);
		}
		int res = 0;
		REP(j, m) {
			int cnt = 0;
			REP(i, n) {
				if (max[i] == a[i][j]) ++cnt;
			}
			CHMAX(res, cnt);
		}
		return res <= k;
	};

	OUT(bisection(0, n, check))BR;
