int cnt[MAXN];
bool dead[MAXN];
int id[MAXN];

bool ok(int x)
{
	int i, j;
	fill(cnt, cnt + m, 0);
	fill(dead, dead + m, false);
	fill(id, id + n, 0);

	for (i = 0; i < n; ++i)
		++cnt[mat[i][0]];

	bool again;
	do
	{
		again = false;
		for (i = 0; i < m; ++i) if (cnt[i] > x)
		{
			dead[i] = true;
			again = true;

			for (j = 0; j < n; ++j)
			{
				while (dead[mat[j][id[j]]])
				{
					--cnt[mat[j][id[j]]];
					++id[j];
					if (id[j] == m)
						return false;
					++cnt[mat[j][id[j]]];
				}
			}
		}
	} while (again);

	return true;
}

