bool can(int x){
	for(int i=1; i<=N; i++){
		it[i] = 1;
	}
	for(int i=1; i<=M; i++){
		check[i] = false;
	}
	while(1){
		bool flag = false;
		for(int i=1; i<=M; i++) cnt[i] = 0;
		for(int i=1; i<=N; i++){
			if(it[i] > M) return false;
			cnt[a[i][it[i]]]++;
		}
		for(int i=1; i<=N; i++){
			if(cnt[a[i][it[i]]] > x){
				check[a[i][it[i]]] = true;
				flag = true;
			}
		}
		for(int i=1; i<=N; i++){
			while(check[a[i][it[i]]]){
				it[i]++;
			}
		}
		if(!flag) break;
	}
	return true;
}

