int n,m,ans,mark[305],cnt[305],g[305][305];
//贪心，每次选择人数最多的项目去掉，记录最大值
int main(){
    scanf("%d%d",&n,&m);
    for(int i=1; i<=n; i++){
        for(int j=1; j<=m; j++)
          scanf("%d",&g[i][j]);
    }
    ans=n+1;
    for(int i=1; i<=m; i++){
        memset(cnt,0,sizeof(cnt));
        for(int j=1; j<=n; j++){
            int k=1; //选择未标记的最大爱好项目
            while(mark[g[j][k]]==1) k++;
            cnt[g[j][k]]++;
        }
        int mx=0;
        for(int j=1; j<=m; j++)
          if(cnt[j]>cnt[mx]) mx=j;
        ans=min(ans,cnt[mx]);
        mark[mx]=1;
    }
    printf("%d\n",ans);
    return 0;
}

