int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int N,M;
  cin >> N >> M;
  vector<vector<int>> G(N,vector<int> (M));
  for(int i=0; i<N; i++){
    for(int j=0; j<M; j++){
      cin >> G[i][j];
      G[i][j]--;
    }
  }
  vector<vector<int>> pos(N,vector<int>(M));
  for(int i=0; i<N; i++){
    for(int j=0; j<M; j++){
      for(int k=0; k<M; k++){
        if(G[i][k] == j){
          pos[i][j] = k;
        }
      }
    }
  }
  // i番目のスポーツに今何人集まってるか
  vector<int> cnt(M,0);
  for(int i=0; i<N; i++){
    for(int j=0; j<M; j++){
      if(G[i][j] == M-1){
        cnt[j]++;
      }
    }
  }
  // 最小値をmnにできるか判定
  for(int mn=1; mn<=N; mn++){
    vector<int> now = cnt;
    vector<vector<int>> rem = pos;
    vector<bool> use(M,true);
    // 最小値超えるものがあればそのスポーツは選ばない
    bool can = true;
    while(1){
      // j番目のスポーツは選ばない
      int j = -1;
      for(int i=0; i<M; i++){
        if(!use[i]) continue;
        if(now[i] > mn) j = i;
      }
      if(j == -1) break;
      use[j] = false;
      for(int i=0; i<N; i++){
        while(1){
          if(use[rem[i].back()]) break;
          now[rem[i].back()]--;
          rem[i].pop_back();
          if(rem[i].size() == 0){
            can = false;
            break;
          }
          now[rem[i].back()]++;
        }
      }
      if(!can) break;
    }
    if(can){
      cout << mn << "\n";
      return 0;
    }
  }
  return 0;
}

