int check(int x){
    vector< queue<int> > vq(N);
    vector<int> used(M,0);
    for(int i=0;i<N;i++){
        for(int j=0;j<M;j++) vq[i].push(A[i][j]);
    }

    while(true){
        map<int,int> M;
        for(int i=0;i<N;i++){
            M[vq[i].front()]++;
        }
        vector<int> ng;
        for(auto p:M){
            if(x<p.second) ng.push_back(p.first);
        }
        if(ng.size()==0) return 1;
        for(auto j:ng){
            used[j]=1;
        }

        for(int i=0;i<N;i++){
            while(!vq[i].empty() && used[vq[i].front()]) vq[i].pop();
            if(vq[i].empty()) return 0;
        }
    }

}

