int mp[400][400];
int vis[400];
struct node {
    int val, pos;
} c[400];

bool cmp(node a, node b) {
    return a.val < b.val;
}

int n, m;

void slove() {
    int cnt = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (!vis[mp[i][j]]) {
                cnt++;
                c[mp[i][j]].val += cnt * cnt;
                c[mp[i][j]].pos = mp[i][j];
            }
        }
    }
    for (int i = 1; i <= m; i++) {
        if (c[i].val == 0) c[i].val = 0x3f3f3f3f;
    }
    sort(c + 1, c + 1 + m, cmp);
}

int main() {
    scanf("%d %d", &n, &m);
    for (int i = 1; i <= m; i++) {
        c[i].val = 0;
        c[i].pos = 0;
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            scanf("%d", &mp[i][j]);
        }
    }
    int cnt[310];
    int ans = n;
    int temp;
    for (int i = 1; i < m; i++) {
        temp = 0;
        slove();
        vis[c[1].pos] = 1;
        memset(cnt, 0, sizeof(cnt));
        for (int j = 1; j <= n; j++) {
            for (int k = 1; k <= m; k++) {
                if (!vis[mp[j][k]]) {
                    cnt[mp[j][k]]++;
                    temp = max(temp, cnt[mp[j][k]]);
                    break;
                }
            }
        }
        ans = min(ans, temp);
    }
    printf("%d\n", ans);
    return 0;
}

