        a(n, std::vector<int>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            std::cin >> a[i][j];
            a[i][j] = m - a[i][j];
        }
    }
    bool used[303] = {};
    auto func = [&](auto &self, int pos = 0) -> int {
        if (pos >= m) return 1e9;
        std::vector<int> cnt(m);
        for (int i = 0; i < n; i++) {
            int mi = 1e9, p = 0;
            for (int j = 0; j < m; j++) {
                if (used[j]) continue;
                if (a[i][j] < mi) {
                    mi = a[i][j];
                    p = j;
                }
            }
            cnt[p]++;
        }
        int ma = 0, p = 0;
        for (int i = 0; i < m; i++) {
            if (ma < cnt[i]) {
                ma = cnt[i];
                p = i;
            }
        }
        used[p] = true;
        return std::min(ma, self(self, pos + 1));
    };
    std::cout << func(func) << std::endl;
    return 0;
}

