  auto check = [&](int x) -> bool {

    vector<queue<int>> Q(n);
    rep(i, n) rep(j, m) {
      Q[i].emplace(A[i][j]);
    }

    vb X(m, 1);
    map<int, int> C;

    while (1) {
      int ma = 0;
      int mai = -1;
      rep(i, n) {
        while (!Q[i].empty() && X[Q[i].front()] == 0) Q[i].pop();
        if (Q[i].empty()) return false;
        if (amax(ma, ++C[Q[i].front()])) {
          mai = Q[i].front();
        }
      }
      if (ma <= x) return true;
      X[mai] = 0;
    }
  };

  while (abs(ok - ng) > 1) {
    int mid = (ok + ng) / 2;
    bool c = check(mid);
    // cout << "ok: " << ok << ", ng: " << ng << ", ";
    // cout << "check(" << mid << ") -> " << c << endl;
    if (c) ok = mid;
    else ng = mid;
  }

  return ok;
}

