int body(int &argc, char **argv) {
    using namespace debug;
    auto N = read<i32>();
    auto M = read<i32>();
    auto A = V<V<i32>>(N);
    REP (i, N) {
        A[i] = read<i32>(M);
        REP (j, M) {
            A[i][j] -= 1;
        }
    }

    auto table = V<V<i32>>(M, V<i32>(M, 0));

    REP (i, N) {
        REP(j, M) {
            auto m = A[i][j];
            table[m][j] += 1;
        }
    }

    V<bool> is_added(M, false);
    i64 ans = N + 1; // max
    while (true) {
        // 追加する競技を決める
        V<bool> exclude = is_added;
        i32 add_M = -1;
        REP (i, M) {
            // i番目
            i32 min = N + 1;
            REP (j, M) {
                if (exclude[j]) continue ;
                // j競技
                min = std::min(min, table[j][i]);
            }
            i32 cnt = 0;
            REP (j, M) {
                if (exclude[j]) continue ;
                if (table[j][i] != min) {
                    exclude[j] = true;
                } else {
                    add_M = j;
                    cnt += 1;
                }
            }
            // Check
            if (cnt == 1) {
                break ;
            }
        }

        if (add_M < 0) {
            break ;
        }

        is_added[add_M] = true;

        // add_Mを追加した場合の値
        V<i32> cnt(M, 0);
        V<bool> is_decided(N, false);
        REP(j, M) {
            REP(i, N) {
                if (is_decided[i]) {
                    continue ;
                }
                if (is_added[A[i][j]]) {
                    cnt[A[i][j]] += 1;
                    is_decided[i] = true;
                }
            }
        }

        auto new_ans = *max_element(cnt.begin(), cnt.end());

        if (ans < new_ans) {
            break ;
        } else {
            ans = new_ans;
        }
    }

    cout << ans << endl;

    return 0;
}

