i32 n, m;
i32 a[300][300];

i32 solve() {
    in(n, m);
    times(n, i) {
        times(m, j) {
            in(a[i][j]);
        }
    }

    i32 min_ans = max(1, n-m+1);
    i32 c = m;

    times(m, mi) {
        i32 t[301] = {};
        times(n, ni) {
            t[a[ni][mi]]++;
        }
        i32 max_t = 0;
        upto(1, m, mj) {
            max_t = max(max_t, t[mj]);
        }
        if (max_t > min_ans) {
            c--;
            min_ans = max(min_ans, n - c + 1);
        }
        else {
            break;
        }
    }

    return min(min_ans, n);
}

