const int N = 310;

int n, m;
vector <int> v[N];
int front[N];

bool can(int x) {
  for (int i = 0; i < n; ++i) {
    front[i] = 0;
  }
  set <int> del;
  while (1) {
    map <int, vector <int> > mp;
    for (int i = 0; i < n; ++i) {
      if (front[i] < v[i].size()) {
	int c = v[i][front[i]];
	mp[c].push_back(i);
      } else {
	return 0;
      }
    }
    vector <int> fail;
    for (auto &kv : mp) {
      if (kv.second.size() > x) {
	del.insert(kv.first);
	for (int i : kv.second) {
	  fail.push_back(i);
	}
      }
    }
    if (fail.empty()) return 1;
    for (auto i : fail) {
      for (++front[i]; front[i] < v[i].size(); ++front[i]) {
	if (del.count(v[i][front[i]]) == 0) break;
      }
    }
  }
  return 1;
}

int main() {
  scanf("%d%d", &n, &m);
  for (int i = 0, x; i < n; ++i) {
    for (int j = 0; j < m; ++j) {
      scanf("%d", &x);
      v[i].push_back(x);
    }
  }
  int l = 0, r = n;
  while (l + 1 < r) {
    int md = (l + r) / 2;
    if (can(md)) {
      r = md;
    } else {
      l = md;
    }
  }
  printf("%d\n", r);
  return 0;
}

