const int N = 505;

int a[N][N], r[N][N], n, m;
int cnt[N];
set<pair<int, int> > prio[N];
int main() {
  scanf("%d %d", &n, &m);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      scanf("%d", a[i]+j);
      a[i][j]--;
      r[i][a[i][j]] = j;
      prio[i].insert(make_pair(j, a[i][j]));
    }
    cnt[a[i][0]]++;
  }
  set<int> st;
  int ans = 0;
  for (int i = 0; i < m; i++) {
    st.insert(i);
    ans = max(ans, cnt[i]);
  }
  for (int i = 0; i < m; i++) {
    memset(cnt, 0, sizeof cnt);
    for (int j = 0; j < n; j++)
      cnt[prio[j].begin()->second]++;
    int cur = 0;
    int del = 0;
    for (int c : st) {
      if (cur < cnt[c]) {
        cur = max(cur, cnt[c]);
        del = c;
      }
    }
    ans = min(ans, cur);
    st.erase(del);
    for (int j = 0; j < n; j++) {
      prio[j].erase(make_pair(r[j][del], del));
    }
  }
  printf("%d\n", ans);
  return 0;
}

