int body(int &argc, char **argv) {
    using namespace debug;
    auto N = read<i32>();
    auto M = read<i32>();
    auto A = V<V<i32>>(N);
    REP (i, N) {
        A[i] = read<i32>(M);
        REP (j, M) {
            A[i][j] -= 1;
        }
    }

    i64 ans = M + 1;
    V<bool> is_added(M, true);
    REP (_, M - 1) {
        V<i32> cnt(M, 0);
        V<bool> is_decided(N, false);
        REP(j, M) {
            REP(i, N) {
                if (is_decided[i]) {
                    continue ;
                }
                if (is_added[A[i][j]]) {
                    cnt[A[i][j]] += 1;
                    is_decided[i] = true;
                }
            }
        }

        auto new_ans = *max_element(cnt.begin(), cnt.end());
        if (new_ans == 0) {
            break ;
        }

        if (ans >= new_ans) {
            ans = new_ans;
        }

        REP(j, M) {
            if (cnt[j] >= ans) {
                is_added[j] = false;
            }
        }
    }

    cout << ans << endl;

    return 0;
}

