template<typename T>
bool chmax(T& a, T b){
    if(a < b){
        a = b;
        return true;
    }
    return false;
}

template<typename T>
bool chmin(T& a, T b){
    if(b < a){
        a = b;
        return true;
    }
    return false;
}

int n, m;
int a[300][300];
bool s[300];

int solve(void){
    int cnt[300];
    fill(cnt, cnt + m, 0);

    int res = -1, id = -1;
    rep(i, n){
        for(auto j : a[i]){
            if(s[j]){
                ++cnt[j];
                if(chmax(res, cnt[j])){
                    id = j;
                }
                break;
            }
        }
    }

    if(id == -1){
        return n;
    }

    s[id] = false;

    return min(res, solve());
}

