    cout << fixed << setprecision(10);

    cin >> n >> m;

    rep(i, n){
        rep(j, m){
            cin >> a[i][j];
            --a[i][j];
        }
    }

    fill(s, s + m, true);

    int ans = solve();
    cout << ans << endl;

    cout << flush;

    return 0;
}

