pair<int,int> get_max_col(vector<bool>& erased, vector<vector<int>>& a) {
	vector<int> freq(m+1);

	for (int i = 1; i <= n; ++i) {
		for (int j = 1; j <= m; ++j) {
			if (!erased[a[i][j]]) {
				++freq[a[i][j]];
				break;
			}
		}
	}

	int mi = 1;
	for (int i = 1; i <= m; ++i) {
		if (freq[i] > freq[mi])
			mi = i;
	}

	return make_pair(mi, freq[mi]);
}

