    auto A = make_v(0, N, M);
    for(auto &v : A) for(auto &e : v) {
        cin >> e;
        e--;
    }

    for(ll ans = 1; ans <= N; ans++) {
        V<bool> ok(M, true);
        V<ll> idxv(N, 0);
        bool suc = true;
        while(true) {
            V<ll> cnt(M, 0);
            V<bool> ng(M, false);
            for(ll i = 0; i < N; i++) {
                ll idx = idxv[i];
