			rep(j, m) {
				if (count[j] > max_val) { max_val = count[j]; max_pot = j; }
			}
			if (max_val <= i) { end_pr(i); }
			rep(j, n) {
				del(a[j], max_pot);
			}
		}
		a = stab_a;
	}
	return 0;
}

