bool judge(int x) {
    memset(vis, 0, sizeof(vis));
    int cnt = m;
    while (cnt > 0) {
        bool flag = false;
        memset(num, 0, sizeof(num));
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (vis[a[i][j]]) continue;
                num[a[i][j]]++;
                break;
            }
        }
        for (int j = 1; j <= m; j++) {
            if (num[j] > x) {
                vis[j] = true;
                flag = true;
                cnt--;
            }
        }
        if (!flag) return true;
    }
    return false;
}
int erfen() {
    int l = 1, r = n, ans = n;
    while (l <= r) {
        int mid = (l + r) / 2;
        if (judge(mid)) {
            ans = mid;
            r = mid - 1;
        }
        else l = mid + 1;
    }
    return ans;
}
