    std::vector<std::vector<int>>
        a(n + 2, std::vector<int>(m + 2, 1e9)),
        mi(n + 2, std::vector<int>(m + 2, m + 1)),
        pref(n + 2, std::vector<int>(m + 2, m + 1)),
        dp(m + 2, std::vector<int>(m + 2, 1e9));
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            std::cin >> a[i][j];
            mi[i][j] = std::min(mi[i][j - 1], a[i][j]);
            pref[i][j] = a[i][j] == mi[i][j] ? j : pref[i][j - 1];
        }
    }
    std::fill(dp[0].begin(), dp[0].end(), 0);
    dp[0][m + 1] = n;
    std::vector<int> buf(m + 2);
    for (int i = 1; i <= m; i++) {
        for (int j = 0; j < i; j++) {
            buf = dp[j];
            for (int k = 1; k <= n; k++) {
                if (a[k][i] < mi[k][j]) {
                    buf[i]++;
                    buf[pref[k][j]]--;
                }
            }
            if (*std::max_element(buf.begin(), buf.end())
                < *std::max_element(dp[i].begin(), dp[i].end())) {
                dp[i] = buf;
            }
        }
    }
