int N, M, A[300][300], ans = INT_MAX;

void dfs(int K, set<int> st){
    int attend[301];            // 参加する種目
    for(int i=0;i<N;i++){       // 人
        for(int j=0;j<M;j++){   // 種目
            auto itr = st.find(A[i][j]);
            if(itr != st.end()) { // 見つかった
                attend[i] = A[i][j];
                break;
            }
        }
    }
    pair<int , int> sport[301]; // 参加人数
    for(int i=0;i<301;i++)
        sport[i] = make_pair(0, i);
    for(int i=1;i<=M;i++){       // 種目
        for(int j=0;j<N;j++){   // 人
            if(attend[j] == i){
                sport[i].first++;
            }
        }
    }
    // 降順ソート
    sort(sport, sport + 301, greater<pair<int , int>>());
    if(sport[0].first < ans)
        ans = sport[0].first;
    int min;
    if(N%K == 0) min = N/K;
    else min = (N/K)+1;
    if(ans != min){
        for(int i=0;i<K;i++){
            if(sport[i].first == sport[0].first){
                st.erase(sport[i].second);
                if(K-1 > 0)
                    dfs(K-1, st);
            }else{
                break;
            }
        }
    }
}

