void solve(){
    set<int> used;
    unordered_map<int,int> cnt;
    int ans=N+1;
    while(used.size()<N){

        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < M; j++)
            {
                if(used.find(A[i][j])!=used.end()) continue;
                cnt[A[i][j]]++;
                break;
            }
        }
        auto itr = max_element(cnt.begin(),cnt.end(),[](pii a, pii b){return a.second < b.second;});
        ans = min(ans,itr->second);
        used.insert(itr->first);
    }
    cout << ans << endl;
}

