int a[305][305],n,m,mark[305],cnt[305],ptr[305];

int get(int row){
	for (int j=ptr[row];j<=m;j++){
		if(mark[a[row][j]]){
			return j;
		}
	}

	return -1;
}

int fun(int lim,int maxi){
	for (int i=1;i<=lim;i++){
		int indx=get(i);

		if(indx==-1)
		return 0;
		while(cnt[a[i][indx]]+1>maxi){
			mark[a[i][indx]]=0;
			int y=fun(i-1,maxi);
			if(y==0)
			return 0;
			indx=get(i);

			if(indx==-1)
			return 0;
		}

		ptr[i]=indx;
		cnt[a[i][indx]]++;
	}

	return 1;
}

int check(int val){

	for (int i=1;i<=n;i++){
		ptr[i]=1;
	}

	for (int i=1;i<=m;i++){
		cnt[i]=0;
		mark[i]=1;
	}

	return fun(n,val);
}

