			scanf("%d",&a[i][j]);
		}
	}

	int l=1,r=n,best=n;

	while(l<=r){
		int mid=(l+r)>>1;

		if(check(mid)){
			best=min(best,mid);
			r=mid-1;
		}

		else l=mid+1;
	}

	printf("%d\n",best);
}

