bool fin(int ma) {
    for (int i=1;i<=m;i++) {
        cnt[i]=0;
        choose[i]=true;
    }
    for (int i=1;i<=n;i++) {
        cnt[a[i][1]]++;
        sport[i]=1;
    }
    for (int times=1;times<=m;times++) {
        int id=-1;
        for (int i=1;i<=m;i++)
            if (cnt[i]>ma) {
                id=i;
                break;
            }
        if (id==-1) return true;
        if (times==m) return false;
        choose[id]=false;
        for (int i=1;i<=n;i++) {
            cnt[a[i][sport[i]]]--;
            while (!choose[a[i][sport[i]]]) sport[i]++;
            cnt[a[i][sport[i]]]++;
        }
    }
}

