const int N = 310;
int a[N][N];
bool sub[N];
bool no_pick[N];
int sum[N];
int n, m;
int ans = 0x3f3f3f3f;

void dfs (int row, int max_sum) {
	if (max_sum >= ans) return;
	if (row == n+1) {
		ans = max_sum;
		return;
	}

	For (j, 1, m) {
		if (sub[a[row][j]]) {
			For (k, 1, j-1) no_pick[a[row][k]] = false;
			++sum[a[row][j]];
			dfs (row+1, max(max_sum, sum[a[row][j]]) );
			--sum[a[row][j]];
			return;
		}

		if (!no_pick[a[row][j]]) {
			sub[a[row][j]] = true;
			sum[a[row][j]] = 1;
			no_pick[a[row][j]] = true;
			dfs (row+1, max_sum);
			sub[a[row][j]] = false;
			sum[a[row][j]] = 0;
		}
	}
}

