using namespace std;

pair<int, int> simulate(int N, int M, const vector<vector<int>> &A, const vector<bool> &valid)
{
	map<int, int> h;
	int mx = 0;
	for (auto &p : A) {
		for (auto x : p) {
			if (valid[x]) {
				mx = max(mx, ++h[x]);
				break;
			}
		}
	}
	for (const auto &e : h) {
		if (e.second == mx) {
			return e;
		}
	}
	return make_pair(-1, -1);
}

int solve(int N, int M, const vector<vector<int>> &A)
{
	int ans = N;
	vector<bool> valid(M, true);
	for (int i = 0; i < M; ++i) {
		auto r = simulate(N, M, A, valid);
		ans = min(ans, r.second);
		valid[r.first] = false;
	}
	return ans;
}

