int count(const vvi& cur, set<int> &there)
{
	int n = SZ(cur);
	int m = SZ(cur[0]);
	int ans = 0;
	map<int, int> cnt;

	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < m; ++j)
		{
			if (there.count(cur[i][j]))
			{
				cnt[cur[i][j]]++;
				ans = max(ans, cnt[cur[i][j]]);
				break;
			}
		}
	}

	return ans;
}


signed main()
{
	ios::sync_with_stdio(false);
	cin.tie(0); cout.tie(0);

