	for (int i = 0; i < n; ++i)
	{
		mp[i].resize(m);
		for (int j = 0; j < m; ++j)
			cin >> mp[i][j];
	}

	int ans = n;

	for (int i = 0; i < n; ++i)
		for (int j = 0; j < m; ++j)
		{
			set<int> there;
			for (int z = j; z < m; ++z)
				there.insert(mp[i][z]);

			ans = min(ans, count(mp, there));
		}

	cout << ans;
}

