bool pass(int lim)
{
	int i,j;
	bool flag=1;
	memset(vis,1,sizeof(vis));
	while (flag)
	{
		flag=0;
		memset(cnt,0,sizeof(cnt));
		for (i=1;i<=n;i++)
		for (j=1;j<=m;j++)
			if (vis[a[i][j]])
			{
				cnt[a[i][j]]++;
				break;
			}
		for (i=1;i<=m;i++)
			if (cnt[i]>lim)
				vis[i]=0,flag=1;
	}
	for (i=1;i<=n;i++)
		if (vis[i]) return 1;
	return 0;
}

