bool can(int x){
	for(int i=1; i<=N; i++) it[i] = 1;
	for(int i=1; i<=M; i++) check[i] = false;
	while(1){
		bool flag = false;
		for(int i=1; i<=M; i++) cnt[i] = 0;
		for(int i=1; i<=N; i++){
			if(it[i] > M) return false;
			cnt[a[i][it[i]]]++;
		}
