bool solve(ll n)
{
    memset(B, 0, sizeof(B));
    memset(U, 0, sizeof(U));
    while (true)
    {
        memset(C, 0, sizeof(C));
        REP(i, N)
        {
            C[A[i][B[i]]]++;
        }
        bool e = true;
        REP(i, M)
        {
            if (C[i] > n)
            {
                U[i] = true;
                e = false;
            }
        }
        if (e)
            return true;
        REP(i, N)
        {
            while (B[i] < M && U[A[i][B[i]]])
                B[i]++;
            if (B[i] >= M)
                return false;
        }
    }
    return false;
}

