bool pass(int lim)
{
	int i,j;
	bool flag=1;
	memset(vis,1,sizeof(vis));
	while (flag)
	{
		flag=0;
		memset(cnt,0,sizeof(cnt));
		for (i=1;i<=n;i++)
		for (j=1;j<=m;j++)
