const int MAXN = 305;
int n, m, ar[MAXN][MAXN], jml[MAXN], piv[MAXN];
vi ad[MAXN];

stack < int > st;

bool ganti (int x) {
	while (piv[x]<=m) {
		int no = ar[x][piv[x]++];
		if (jml[no]<0) continue;
		jml[no]++;
		ad[no].psb(x);
		return 1;
	}
	return 0;
}

bool coba (int x) {
	for (int i=1; i<=m; i++) ad[i].clear();
	setnul(jml);
	for (int i=1; i<=n; i++) {
		piv[i] = 2;
		jml[ar[i][1]]++;
		ad[ar[i][1]].psb(i);
	}
	while (!st.empty()) st.pop();
	while (1) {
		for (int i=1; i<=m; i++)
			if (jml[i]>x) {
				st.push(i);
				jml[i] = -1;
			}
		if (st.empty()) return 1;
		while (!st.empty()) {
			int tp = st.top(); st.pop();
			for (auto xx : ad[tp])
				if (!ganti(xx)) return 0;
		}
	}
	return 1;
}

int solve() {
	int l=1, r=n;
	while (l<r) {
		int mid = (l+r)>>1;
		if (coba(mid)) r = mid;
		else l = mid+1;
	}
	return l;
}

