const int MAX = 2000010;
long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

long long extGCD(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a%b, y, x);
    y -= a/b * x;
    return d;
}
// 負の数にも対応した mod (a = -11 とかでも OK) 
inline long long mod(long long a, long long m) {
    return (a % m + m) % m;
}

// 逆元計算 (ここでは a と m が互いに素であることが必要)
long long modinv(long long a, long long m) {
    long long x, y;
    extGCD(a, m, x, y);
    return mod(x, m); // 気持ち的には x % m だが、x が負かもしれないので
}
ll GCD(ll a, ll b){

    if(b == 0) return a;
    return GCD(b, a%b);
}

typedef vector<ll> vec;
typedef vector<vec> mat;

mat mul(mat &A, mat &B) {
    mat C(A.size(), vec((int)B[0].size()));
    for(int i=0; i<A.size(); ++i){
        for(int k=0; k<B.size(); ++k){
            for(int j=0; j<B[0].size(); ++j){
                C[i][j] = (C[i][j] + A[i][k] * B[k][j] %MOD) % MOD;
            }
        }
    }
    return C;
}
mat matPow(mat A, ll n) {
    mat B(A.size(), vec((int)A.size()));

    for(int i=0; i<A.size(); ++i){
        B[i][i] = 1;
    }

    while(n > 0) {
        if(n & 1) B = mul(B, A);
        A = mul(A, A);
        n >>= 1;
    }
    return B;
}

int N, M;
int a[310][310];
int id[310];
int pid[310];
int cnt[310];
bool ban[310];
bool C(int x){

    //最少人数をxで収まるような分け方は存在するか?
    REP(i,M) cnt[i] = 0;
    REP(i,N) id[i] = 0, pid[i] = -1;
    REP(i,N) ban[i] = false;
    while(1){

        for(int i=0; i<N; i++){
            if(id[i] < M && id[i] != pid[i]) cnt[a[i][id[i]]]++;
            pid[i] = id[i];
        }

        for(int i=0; i<M; i++){
            if(cnt[i] > x){
                ban[i] = true;
                cnt[i] = -1;
                for(int j=0; j<N; j++){
                    while(id[j] < M && ban[a[j][id[j]]]){
                        id[j]++;
                    }
                }
            }
        }
        bool isfail = true;
        for(int i=0; i<N; i++){
            if(id[i] == M) return false;
        }
        for(int i=0; i<M; i++){
            if(ban[i] == false) isfail = false;
        }

        if(isfail) return false;
        bool ok = true;

        for(int i=0; i<N; i++){
            if(id[i] != pid[i]) ok = false;
        }
        if(ok) break;
    }
    return true;
}
