    ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);

    cin >> N >> M;
    REP(i,N)REP(j,M) cin >> a[i][j], a[i][j]--;

    int lb = 0, ub = 310;
    //cout << C(2) << endl;
    while(ub-lb>1){
        int mid = (lb+ub)/2;
        if(C(mid)){
            ub = mid;
        }else{
            lb = mid;
        }
    }
    cout << ub << endl;

    return 0;
}

