using namespace std;

using int64 = long long;
using Matrix = vector<vector<int64>>;

bool IsPossible(const int64 n, const int64 m, const Matrix& as, const int64 k) {
  vector<bool> not_used(m + 1, false), used(m + 1, false);
  vector<int64> sports(n, 0);
  for (int64 s = 0; s < m; ++s) {
    vector<int64> numbers(m + 1, 0);
    for (int64 i = 0; i < n; ++i) {
      if (sports[i] > 0)
        continue;
      for (int64 j = 0; j < m; ++j) {
        int64 sp = as[i][j];
        if (used[sp]) {
          sports[i] = sp;
          break;
        }
        if (not_used[sp])
          continue;
        ++numbers[sp];
        break;
      }
    }

    auto it = max_element(numbers.begin(), numbers.end());
    int64 id = it - numbers.begin();
    if (*it <= k) {
      used[id] = true;
    } else {
      not_used[id] = true;
      if (s == m - 1)
        return false;
    }
  }

  return true;
}

int main() {
  int64 n, m;
  cin >> n >> m;
  Matrix as(n, vector<int64>(m));
  for (int64 i = 0; i < n; ++i) {
    for (int64 j = 0; j < m; ++j) {
      cin >> as[i][j];
    }
  }

  int64 low = 0, up = n;
  while (low + 1 < up) {
    int64 k = (low + up) / 2;
    if (IsPossible(n, m, as, k)) {
      up = k;
    } else {
      low = k;
    }
  }
  cout << up << "\n";
  return 0;
}

