t2 maxt2(t2 a, t2 b)
{
    return max(a, b);
}

bool judge(const V<V<ll>> &alist, ll n, ll m, ll border)
{
    SegmentTree<t2> tree(400, t2(-1e18, -1e18), maxt2);
    rep (i, 400) tree.update(i, t2(0, i));
    V<ll> spt_to_psn[400];

    rep (psn, n) {
        ll spt = alist[psn][0];
        auto now = tree.query(spt, spt+1);
        ll cnt = get<0>(now);
        ll lspt = get<1>(now);
        assert(spt == lspt);
        tree.update(spt, t2(cnt+1, spt));
        spt_to_psn[spt].pb(psn);
    }

    bool ngspts[400] = {};
    ll psnidx[400] = {};

    while (1) {
        auto item = tree.query(0, 400);
        ll cnt = get<0>(item);
        ll spt = get<1>(item);
        if (cnt <= border) return true;

        ngspts[spt] = true;
        tree.update(spt, t2(-1e18, spt));

        for (auto psn : spt_to_psn[spt]) {
            while (psnidx[psn] < m && ngspts[alist[psn][psnidx[psn]]]) psnidx[psn]++;
            if (psnidx[psn] >= m) return false;

            ll spt = alist[psn][psnidx[psn]];
            auto now = tree.query(spt, spt+1);
            ll cnt = get<0>(now);
            ll lspt = get<1>(now);
            assert(spt == lspt);
            tree.update(spt, t2(cnt+1, spt));
            spt_to_psn[spt].pb(psn);
        }
    }

    assert(false);
}

void _main()
{
    ll n;llin(n);
    ll m; llin(m);
    V<V<ll>> alist;
    rep (i, n) {
        V<ll> tmp; llina(tmp, m);
        alist.pb(tmp);
    }

    ll left = 1;
    ll right = n;
    ll now = (left + right) / 2LL;
    ll ans = n;

    for ( ; left <= right; now = (left + right) / 2LL) {
        if (judge(alist, n, m, now)) {
            ans = min(ans, now);
            right = now - 1LL;
        }
        else {
            left = now + 1LL;
        }
    }

    debug_printf("----- ans\n");
    cout << ans << endl;
}

