	clr(sum,0); clr(flag,0);
	rep(i,1,n) pos[i]=1,sum[a[i][1]]++;
	int rm=m;
	while (1){
		int cnt=0;
		rep(i,1,m) {
			if (!flag[i]&&sum[i]>mid) ++cnt,flag[i]=1;
		}
		if (!cnt) return 1;
		rm-=cnt;
		if (rm<=0) return 0;
		rep(i,1,n) {
			int &x=pos[i];
			if (flag[a[i][x]]){
				while (flag[a[i][x]]) x++;
				sum[a[i][x]]++;
			}	 
		} 
	}
	return 0;
}
