//checked: もう使ってはならない
//cnt: 各競技の参加人数 numを越えてはならない
//depth: 何人目を見ているか
//selected: どの競技を選択したのか
//return: ダメだった番号
//retrun: -1 OK
//retrun: -100 NG
int check(int num, vector<int>& cnt, vector<bool>& checked, int depth) {
	if (depth == N) return -1;
	REP(j, M) {
		if (checked[A[depth][j]]) continue;
		if (cnt[A[depth][j]] < num) {
			cnt[A[depth][j]]++;
		}
		else {
			checked[A[depth][j]] = true;
			return A[depth][j];
		}

		int c = check(num, cnt, checked, depth + 1);
		if (c == -1) {
			return -1;
		}
		//違ってた場合はダメだったやつが消えるまで遡る
		else {
			cnt[A[depth][j]]--;
			if (cnt[c] > 0) return c;
		}
	}
	return -100;
}

void solve() {
	cin >> N >> M;
	REP(i, N) REP(j, M) cin >> A[i][j];

	vector<int> cnt(M+1);
	vector<bool> checked(M+1);
	int high = M;
	int low = 0;
	int mid;
	while ( high - low > 1) {
		mid = (low + high) / 2;
		checked.clear();
		cnt.clear();
		if (check(mid, cnt, checked, 0) == -1) high = mid;
		else low = mid;
	}
	cout << high << endl;
}

