//全ての競技を開催したとき，最も多くの人数Qが参加する競技を中止する．
//順次中止していって，最も最大参加人数が小さかった組み合わせが答え

int main(void){
	ll n,m,a[310][310],top[310]={},stop[310]={},ans=inf;
	cin>>n>>m;
	rep(i,n)rep(j,m)cin>>a[i][j];
	rep(i,m){
		ll c[310]={},max_id=1;
		rep(j,n){
			while(stop[a[j][top[j]]]!=0)top[j]++;//j人目の先頭位置を更新
			c[a[j][top[j]]]++;
		}
		reg(j,1,m){
			if(c[max_id]<c[j])max_id=j;
		}
		ans=min(ans,c[max_id]);
		stop[max_id]=1;//参加人数が最も多い競技を中止
	}
	cout<<ans<<endl;
	return 0;
}

