pair<int, int> calc(int n, int m) {
    for (int i = 1; i <= m; i++) {
        cnt[i] = 0;
    }
    for (int i = 1; i <= n; i++) {
        int j = 1;
        while (banned[a[i][j]]) j++;
        cnt[a[i][j]]++;
    }
    pair<int, int> ans(-1, -1);
    for (int i = 1; i <= m; i++) {
        ans = max(ans, make_pair(cnt[i], i));
    }
    return ans;
}

