using namespace std;
typedef long long LL;
const int MAXN = 305;

int A[MAXN + 5][MAXN + 5];

int N, M;

bool Check(int ans)
{
	int f[MAXN + 5], sum[MAXN + 5];
	bool t[MAXN + 5];
	for(int i = 1; i <= N; i++) f[i] = 1;
	for(int i = 1; i <= M; i++) t[i] = true;
	bool check = false;
	while(!check){
		memset(sum, 0, sizeof(sum));
		for(int i = 1; i <= N; i++){
			int tot = f[i], c = A[i][tot];
			sum[c]++;
		}
		bool ok = true;
		for(int i = 1; i <= M; i++){
			if(sum[i] > ans) ok = false;
		}
		if(ok){
			check = true;
			break;
		}
		else{
			for(int i = 1; i <= N; i++){
				int tot = f[i], c = A[i][tot];
				if(sum[c] > ans){
					t[c] = false;
					while(f[i] <= M && !t[A[i][f[i]]]) f[i]++;
				}
				if(f[i] > M) ok = true;
			}
			if(ok) break;
		}
	}
	return check;
}

int main()
{
   //freopen("in.txt","r",stdin);
   //freopen("out.txt","w",stdout);
	scanf("%d %d", &N, &M);
	for(int i = 1; i <= N; i++) for(int j = 1; j <= M; j++) scanf("%d", &A[i][j]);
	int L = 1, R = 305, tot = 0;
	while(L <= R){
		int mid = (L + R) >> 1;
		if(Check(mid)) tot = mid, R = mid - 1;
		else L = mid + 1;
	}
	printf("%d\n", tot);
    return 0;
}

