#define FOR(i, start, end) for(int i = (start); i < (end); ++i)
#define REP(i, n) FOR(i, 0, n)

int N, M;
int A[302][302];

pair<int, int> simulate(bool choice[302])
{
    int cnts[302];
    fill(begin(cnts), end(cnts), 0);

    FOR(i, 1, N+1) {
        FOR(j, 1, M+1) {
            int sport = A[i][j];
            if(choice[sport]) {
                ++cnts[sport];
                break;
            }
        }
    }

    auto it = max_element(cnts+1, cnts+M+1);
    int idx = 1 + distance(cnts+1, it);
    int cnt = *it;
    return make_pair(idx, cnt);
}

void solve()
{
    bool choice[302];
    fill(begin(choice), end(choice), true);

    auto idxcnt = simulate(choice);
    //cout << idxcnt.second << "\n";
    int result = idxcnt.second;
    for(int m = M; m > 1; --m) {
        choice[idxcnt.first] = false;
        idxcnt = simulate(choice);
        int cnt = idxcnt.second;
        //cout << cnt << "\n";
        if(result < cnt) {
            break;
        }
        else {
            result = cnt;
        }
    }

    cout << result << "\n";
}

int main()
{
    cin >> N >> M;
    FOR(i, 1, N+1) {
        FOR(j, 1, M+1) {
            cin >> A[i][j];
            //cout << A[i][j] << " ";
        }
        //cout << "\n";
    }

    solve();

    return 0;
}

