    if(n == 1) {
        cout << 1 << endl;
        ret();
    }

    vector<vector<int>> spots(n, vector<int>(m));
    rep(i, n) rep(j, m) {
            int s;
            cin >> s;
            s--;
            spots[i][s] = j;
        }

    set<int> close;
    ll ans = INF;
    rep(i, m - 1) {
        Res r = f(spots, close, n, m);
        cmin(ans, r.max_count);
        close.insert(r.remove_sport);
    }
    cout << ans << endl;

}

