		}
		//for(int i = 1; i <= m; i++) if(sports[i]) printf("%d : %d\n", i, cnt[i]);
		//printf("\n");
		for(int i = 1; i <= m; i++) if(sports[i] && cnt[i] > v){
			sports[i] = false;
			fails = true;
		}
		start = false;
		if(!fails) return true;
	}
}
