template<class Type>
Type solve(Type res = Type()){
    int N,M; cin >> N >> M;
    vector<vector<int>> A(N,vector<int>(M));
    for(auto& vec:A) for(auto& in: vec) cin >> in,in--;

    for(int i = 0; i < N;i++){
        reverse(A[i].begin(),A[i].end());
    }
    res = N;
    vector<int> selected(M,true);
    // cout << A << endl;

    int K = M;
    while(K--){
        vector<int> cnt(M);
        for(int i = 0; i < N;i++){
            cnt[A[i].back()]++;
        }

        ll max_v = *max_element(cnt.begin(),cnt.end());
        res = min(res,max_v);

        for(int i = 0; i < M; i++){
            if(cnt[i] == max_v){
                selected[i] = false;
                for(int i = 0; i < N;i++){
                    while(A[i].size() && !selected[A[i].back()]){
                        A[i].pop_back();
                    }
                }
            }
        }
        // cout << "!!!" << endl;
        // cout << A << endl;
    }

    return res;
}
