int n, m;
const int N = 500;
int a[N][N];
int pt[N];
int cnt[N];
bool bad[N];

bool check(int mx) {
	for (int i = 0; i < n; i++) {
		pt[i] = 0;
	}

	for (int i = 0; i < m; i++) {
		cnt[i] = 0;
		bad[i] = 0;
	}

	for (int i = 0; i < n; i++) {
		cnt[a[i][pt[i]]]++;
	}

	for ( ; ; ) {
		int ind = -1;
		for (int j = 0; j < m; j++) {
			if (cnt[j] > mx) {
				ind = j;
				break;
			}
		}
		if (ind == -1) return true;
		cnt[ind] = 0;
		bad[ind] = 1;

		for (int i = 0; i < n; i++) {
		    if (!bad[a[i][pt[i]]]) continue;
			while (pt[i] < m && bad[a[i][pt[i]]]) pt[i]++;
			if (pt[i] == m) {
				return false;
			} else {
				cnt[a[i][pt[i]]]++;
			}
		}
	}
}

int main() {
	ios_base::sync_with_stdio(0);
	cin >> n >> m;
	for (int i = 0; i < n; i++) {
