			cin >> a[i][j];
			a[i][j]--;
		}
	}

	int l = 0;
	int r = n;
	while (r - l > 1) {
		int m = (r + l) >> 1;
		if (check(m)) {
			r = m;
		} else {
			l = m;
		}
	}
	cout << r;

	return 0;

}

