const int N = 310;
int n, m, cnt[N], ans, max, mid, a[N][N];
bool l[N];

int main() {
    memset(l, true, sizeof l);
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++) {
            static int t;
            scanf("%d", &t);
            a[i][m + 1 - t] = j;
        }
    for (int i = 1; i <= n; i++)
        cnt[a[i][1]]++;
    for (int i = 1; i <= m; i++)
        if (ans < cnt[i]) {
            ans = cnt[i];
            mid = i;
        }
    for (int i = 1; i < m; i++) {
        l[mid] = false;
        max = 0;
        memset(cnt, 0, sizeof cnt);
        for (int j = 1; j <= n; j++)
            for (int k = 1; k <= m; k++)
                if (l[a[j][k]]) {
                    cnt[a[j][k]]++;
                    break;
                }
        for (int j = 1; j <= m; j++)
            if (l[j] && max < cnt[j]) {
                max = cnt[j];
                mid = j;
            }
        ans = std::min(ans, max);
    }
