#include <bits/stdc++.h>

using namespace std;

const int N = 305;

int n, m, a[N][N];
int activ[N], tot[N];
int ans;

void calc(){
	memset(tot, 0, sizeof(tot));
	for(int i = 1; i <= n; ++i){
		for(int j = 1; j <= m; ++j){
			if(activ[a[i][j]]){
				++tot[a[i][j]];
				break;
			}
		}
	}
	int ret = 0;
	for(int i = 1; i <= m; ++i){
		if(activ[i]) ret = max(ret, tot[i]);
	}
	ans = min(ans, ret);
}

int main(){
	scanf("%d %d", &n, &m);
	for(int i = 1; i <= n; ++i){
		for(int j = 1; j <= m; ++j){
			scanf("%d", &a[i][j]);
		}
	}
	for(int i = 1; i <= m; ++i) activ[i] = 1;
	ans = m;
	calc();
	for(int i = 1; i < m; ++i){
		int mx = -1;
		for(int j = 1; j <= m; ++j){
			if(!activ[j]) continue;
			if(mx == -1) mx = j;
			if(tot[j] > tot[mx]) mx = j;
		}
		activ[mx] = 0;
		calc();
	}
	printf("%d\n", ans);
	return 0;
}

