namespace solve30 { //O(n*m*2^m)

	bool chose[15];

	void main() {
		for(int i=1;i<=n;i++)
			for(int j=1;j<=m;j++)
				input(a[i][j]),a[i][j]--;
		int ans=2147483647;
		for(int s=1;s<1<<m;s++) {
			for(int i=0;i<m;i++)
				if(s&(1<<i)) chose[i]=true;
			for(int i=1;i<=n;i++)
				for(int j=1;j<=m;j++)
					if(chose[a[i][j]]) {
						sum[a[i][j]]++;
						break;
					}
			int Max=0;
			for(int i=0;i<m;i++) {
				Max=max(Max,sum[i]),
				sum[i]=0,chose[i]=false;
			}
			ans=min(ans,Max);
		}
		printf("%d\n",ans);
		return;
	}

}

namespace solve70 { // O(n*m*log n)

	int cnt[MAXN];
	bool not_chose[MAXM];

	bool Judge(int mid) {
		memset(not_chose,0,sizeof(not_chose));
		for(int i=1;i<=n;i++) cnt[i]=1;
		while(true) {
			memset(sum,0,sizeof(sum));
			bool flag=true;
			for(int i=1;i<=n;i++) {
				for(;cnt[i]<=m&&not_chose[a[i][cnt[i]]];cnt[i]++);
				if(cnt[i]>m) return false;
				if(++sum[a[i][cnt[i]]]>mid)
					not_chose[a[i][cnt[i]]]=true,flag=false;
			}
			if(flag) return true;
		}
		return false;
	}

	void main() {
		for(int i=1;i<=n;i++)
			for(int j=1;j<=m;j++)
				input(a[i][j]);
		int l=1,r=n,ans;
		while(l<=r) {
			int mid=l+r>>1;
			if(Judge(mid)) ans=mid,r=mid-1;
			else l=mid+1;
		}
		printf("%d\n",ans);
		return;
	}

}

