vector<int> s[N];

bool check(int lim){
	memset(vis, false, sizeof vis);
	For(i, 1, n) pos[i] = 1, s[A[i][1]].pb(i);
	For(i, 1, m){
		int p = 0;
		For(j, 1, m) if(!vis[j] && int(s[j].size()) > lim){
			p = j; 
			break;
		}

		if(!p) return true;
		if(i == m) break;

		vis[p] = true;
		for(int o : s[p]){
			while(vis[A[o][pos[o]]]) ++pos[o];
			s[A[o][pos[o]]].pb(o);
		}
	}
	return false;
}

