using namespace std;

const int N = 310;

int n, m;
vector <int> v[N];
int front[N];

bool can(int x) {
  for (int i = 0; i < n; ++i) {
    front[i] = 0;
  }
  while (1) {
    map <int, vector <int> > mp;
    for (int i = 0; i < n; ++i) {
      int c = v[i][front[i]];
      mp[c].push_back(i);
    }
    vector <int> fail;
    for (auto &kv : mp) {
      if (kv.second.size() > x) {
	fail.push_back(kv.first);
      }
    }
    if (fail.empty()) return 1;
    for (auto i : fail) {
      auto &ps = mp[i];
      for (auto j : ps) {
	front[j]++;
	if (front[j] >= v[j].size())
	  return 0;
      }
    }
  }
  return 1;
}

int main() {
  scanf("%d%d", &n, &m);
  for (int i = 0, x; i < n; ++i) {
    for (int j = 0; j < m; ++j) {
      scanf("%d", &x);
      v[i].push_back(x);
    }
  }
  int l = 0, r = n;
  while (l + 1 < r) {
    int md = (l + r) >> 1;
    if (can(md)) {
      r = md;
    } else {
      l = md;
    }
  }
  printf("%d\n", r);
  return 0;
}

