using namespace std;


int n, m;
vector<vector<int>> a(300, vector<int>(300, -1));

int solve(vector<int>& indice, set<int> ex){
    int res = 1e5;

    set<int> keyset;
    map<int, int> mapp;
    rep(i, n){
        int k = a[i][indice[i]];
        while(0 < ex.count(k)){
            indice[i]++;
            if(m <= indice[i])  break;
            k = a[i][indice[i]];
        }
        if(m <= indice[i])  return 1e6;
        keyset.insert(k);
        mapp[k]++;
    }

    int maxx = 0;
    for(auto k : keyset)    maxx = max(mapp[k], maxx);
    res = min(res, maxx);


    set<int> keys;
    for(auto k : keyset){
        if(maxx == mapp[k])    keys.insert(k);
    }

    for(auto k : keys){
        vector<int> v = indice;
        bool ok = true;
        rep(i, n){
            if(a[i][v[i]] == k){
                v[i]++;
                if(m <= v[i]){
                    ok = false;
                    break;
                }
            }
        }
        set<int> exx = ex;
        exx.insert(k);

        if(ok)  res = min(res, solve(v, exx));
    }

    return res;
}

int main(){
    cin >> n >> m;
    rep(i, n){
        rep(j, m){
            cin >> a[i][j];
            a[i][j]--;
        }
    }

    vector<int> indice(n, 0);

    cout << solve(indice, set<int>()) << endl;


    return 0;
}

