std::vector<int> tak[305] = {};
int arr[305][305] = {};
bool rej[305] = {}; //rejected
bool has[305] = {};
int n, m;

bool can(int k)
{
    for (int i = 0; i < n; i++)
        has[i] = false;
    for (int i = 0; i < m; i++)
    {
        rej[i] = false;
        tak[i].clear();
    }
    for (int j = 0; j < m; j++)
    {
        for (int i = 0; i < n; i++)
        {
            if (!has[i] && !rej[arr[i][j]])
            {
                has[i] = true;
                tak[arr[i][j]].push_back(i);
                if (tak[arr[i][j]].size() > k)
                {
                    for (std::vector<int>::iterator it = tak[arr[i][j]].begin(); it != tak[arr[i][j]].end(); it++)
                        has[*it] = false;
                    tak[arr[i][j]].clear();
                    rej[arr[i][j]] = true;
                }
            }
        }
    }
    for (int i = 0; i < n; i++)
    {
        if (!has[i])
            return false;
    }
    return true;
}

