void add(int x, int row){
	s.erase({-cnt[x], x});
	cnt[x]++;
	s.insert({-cnt[x], x});
	saf[x].insert(row);
}

bool check(int x){
	for(int i = 0; i < m; i++){
		cnt[i] = 0;
		mark[i] = false;
		saf[i].clear();
	}

	s.clear();

	for(int i = 0; i < n; i++){
		id[i] = 1;
		add(a[i][0], i);
	}
	while(-(s.begin() -> F) > x){
		int k = s.begin() -> S;
		s.erase(s.begin());
		mark[k] = true;
		for(auto it : saf[k]){
			while(mark[a[it][id[it]]] && id[it] < m)
				id[it]++;
			if(id[it] == m){
				return false;
			}
			add(a[it][id[it]], it);
		}
	}
	return true;
}

