            sup[i].insert( mk(ar[i][j], j) );

            if (ar[i][j] == m)
                cur[j]++;
        }

    int l = 0, r = 300;

    while (r - l > 1)
    {
        int md = (l + r) >> 1;
        if ( check(md) )
            r = md;
        else
            l = md;
    }
    cout << l;
}

