ll count_max(vector<queue<ll>>& A, vector<bool>& already)
{
  vector<ll> cnt(M, 0);
  for (ll i = 0; i < N; ++i) {
    while (true) {
      if (already.at(A.at(i).front())) {
        A.at(i).pop();
