struct Solver {
   Solver() { fprintf(stderr, "--------Solver begin--------\n"); }
   ~Solver() { fprintf(stderr, "--------Solver end--------\n"); }
   long gcd(long x, long y) {
      if( y == 0 ) return x;
      return gcd(y, x%y);
   }
   long table[333][333];
   void solve() {
      long n, m; scan(n, m);
      for(long i = 0; i < n; ++i) {
         for(long k = 0; k < m; ++k) {
            scan(table[i][k]);
         }
      }
      long res = (1LL << 53);
      for(long t = 1; t <= m; ++t) {
         LI count(m+1, 0);
         for(long i = 0; i < n; ++i) {
            for(long k = 0; k < m; ++k) {
               if( table[i][k] == t ) break;
               count[table[i][k]] += 1;
            }
         }
         LI pass(m+1, 0);
         for(long i = 1; i <= m; ++i) {
            if( count[i] < n / 2 ) pass[i] = 1;
         }
         LI count2(m+1, 0);
         for(long i = 0; i < n; ++i) {
            for(long k = 0; k < m; ++k) {
               if( pass[table[i][k]] == 1 ) {
                  count2[table[i][k]] += 1;
                  break;
               }
            }
         }
         long temp = 0;
         for(long i = 1; i <= m; ++i) {
            temp = std::max(temp, count2[i]);
         }
         res = std::min(res, temp);
      }
      printf("%ld\n", res);
   }
};

