	cin >> N >> M;
	for(int i=1; i<=N; i++) for(int j=1; j<=M; j++) scanf("%d", &Nr[i][j]);
	for(int i=1; i<=N; i++) for(int j=1; j<=M; j++) Ix[i][Nr[i][j]] = j;

