ll solve(ll n,ll m,vector<vector<ll>> &v,vector<ll> &itr,vector<vector<ll>> &s){
  bool nop[m]={};
  ll ans=n;
  while(1){
    bool ok=1;
    vector<ll> te;
    rep(l,m){
      if(s[l].size()>ans){
        for(auto w:s[l])te.push_back(w);
        s[l].clear();
        nop[l]=1;
      }
    }
    for(auto w:te){
      ok=0;
      while(1){
        itr[w]++;
        if(itr[w]==m)return ans+1;
        if(nop[v[w][itr[w]]]==0)break;
      }
      s[v[w][itr[w]]].push_back(w);
    }
    if(ok)ans--;
  }
  return -1;
}

