inline int read() {
	char ch = getchar(); int x = 0, op = 1;
	while (ch < '0' || '9' < ch) { if (ch == '-') op = -1; ch = getchar(); }
	while ('0' <= ch && ch <= '9') { x = x*10 + ch-'0'; ch = getchar(); }
	return op * x;
}

const int maxn = 309;
int a[maxn][maxn], p[maxn], del[maxn];
vector<int> b[maxn];
int n, m, l = 1, r, mid;

bool check(int limit) {
	int mx = 0, mx2 = 0, cur = 0, cur2 = 0, tmp, now, ty;
	rep (i, 1, n) {
		b[a[i][1]].push_back(i);
		p[i] = 1;
	}
	rep (i, 1, m) {
		if (b[i].size() > mx) {
			mx2 = mx; mx = b[i].size(); cur2 = cur; cur = i;
		}
		else if (b[i].size() > mx2) {
			mx2 = b[i].size(); cur2 = i;
		}
		del[i] = 0;
	}

	while (mx > limit) {
		del[tmp = cur] = 1;
		mx = mx2; cur = cur2; mx2 = cur2 = 0;
		rep (i, 0, b[tmp].size()-1) {
			now = b[tmp][i];
			while (p[now] <= m && del[a[now][p[now]]]) p[now]++;
			if (p[now] > m) return 0;
			b[ty = a[now][p[now]]].push_back(now);

			if (b[ty].size() > mx) {
				if (ty != cur) {
					mx2 = mx; cur2 = cur;
				}
				mx = b[ty].size(); cur = ty;
			}
			else if (b[ty].size() > mx2) {
				mx2 = b[ty].size(); cur2 = ty;
			}
		}
		b[tmp].clear();
	}
	return 1;
}

int main() {
	r = n = read(); m = read();
	rep (i, 1, n) rep (j, 1, m) a[i][j] = read();
	while (l < r) {
		mid = (l + r) >> 1;
		if (check(mid)) r = mid;
		else l = mid + 1;
	}
	printf("%d\n", l);
	return 0;
}

