int n, m, ar[N][N], p[N], cnt[N], pos[N][N], cur[N], u[N], mx, sum;

set < pair <int, int> > st[N], sup[N];

vector <int> bad;

inline bool check(int md)
{
    for (int i = 1; i <= n; i++)
    {
        p[i] = m;
        st[i] = sup[i];
    }

    bad.clear();

    for (int j = 1; j <= m; j++)
        cnt[j] = cur[j],
        u[j] = 0;

    for (int j = 1; j <= m; j++)
    {
        if ( cnt[j] > md )
            bad.pb(j),
            u[j] = 1;
    }
    int j;

    for (int l = 0; l < bad.size(); l++)
    {
        j = bad[l];
        for (int i = 1; i <= n; i++)
        {
            if (st[i].empty() ) return false;

            st[i].erase( st[i].find( mk( j, ar[i][j] ) ) );

            if ( ar[i][j] == p[i] )
            {
                mx = 0;
                for (auto x : st[i])
                    mx = max( x.sc, mx );

                p[i] = mx;

                cnt[ pos[i][ p[i] ] ]++;

                if (cnt[ pos[i][ p[i] ] ] > md && !u[ pos[i][ p[i] ] ] )
                {
                    bad.pb( pos[i][ p[i] ] );
                    u[ pos[i][ p[i] ] ] = 1;
                }
            }
        }
        cnt[j] = 0;
    }
    sum = 0;
