PII f(const VVI& w, const vector<bool>& use) {
	ll N = w.size();
	ll M = w[0].size();
	VI cnt(M);
	REP(n, N) {
		REP(m, M) if(use[w[n][m]-1]) {
			cnt[w[n][m]-1]++;
			break;
		}
	}
	PII Max = MP(0, -1);
	REP(i, M) Max = max(Max, MP(cnt[i], (ll)i));
	return Max;
}

ll naive(const VVI& w) {
	ll N = w.size();
	ll M = w[0].size();
	ll ans = N;
	RANGE(b, 1, 1<<M) {
		vector<bool> use(M);
		REP(i, M) if(b>>i&1) use[i]=true;
		auto rv = f(w, use);
		ll lans = rv.first;
		ans = min(ans, lans);
	}
	return ans;
}

ll solve(const VVI& w) {
	ll N = w.size();
	ll M = w[0].size();
	vector<bool> use(M, true);
	ll v = N;
	REP(i, M) {
		PII rv = f(w, use);
//			DD(rv);
//			DD(use);
		use[rv.second] = false;
		v = min(v, rv.first);
	}
	return v;
}

