i32 n, m;
queue<i32> a[300];

i32 solve() {
    in(n, m);
    times(n, i) {
        times(m, j) {
            indef(i32, ai);
            a[i].push(ai);
        }
    }

    i32 min_ans = max(1, n-m+1);
    i32 c = m;

    set<i32> u;
    times(m, mi) {
        i32 t[301] = {};
        times(n, ni) {
            while (u.find(a[ni].front()) != u.end()) {
                a[ni].pop();
            }
            t[a[ni].front()]++;
        }
        i32 max_t = 0;
        upto(1, m, mj) {
            max_t = max(max_t, t[mj]);
        }
        upto(1, m, mj) {
            if (t[mj] == max_t) {
                u.insert(mj);
                c--;
            }
        }
        if (max_t > min_ans) {
            min_ans = max(min_ans, n - c + 1);
        }
        else {
            break;
        }
    }

    return min(min_ans, n);
}

