bool judge(int x) {
    memset(vis, 0, sizeof(vis));
    int cnt = m;
    while (cnt > 0) {
        bool flag = false;
        memset(num, 0, sizeof(num));
        for (int i = 1; i <= n; i++) {
            int pos = 0;
            for (int j = 1; j <= m; j++) {
                if (vis[j]) continue;
                if (a[i][j] > a[i][pos]) pos = j;
            }
            num[pos]++;
        }
        for (int j = 1; j <= m; j++) {
            if (num[j] > x) {
                vis[j] = true;
                flag = true;
                cnt--;
            }
        }
        if (!flag) return true;
    }
    return false;
}
