inline bool chmax(T &a, const T b) { return a < b && (a = b, true); }

int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int N, M;
	cin >> N >> M;

	vector<vector<int>> grid(N, vector<int>(M));
	for (int i = 0; i < N; i++) for (int j = 0; j < M; j++) cin >> grid[i][j];
	for (int i = 0; i < N; i++) for (int j = 0; j < M; j++) grid[i][j]--;

	struct dat {
		vector<int> mem;
		int size = 0;
	};

	auto select = [&]() {

		int mx = N - 1;
		bool res = true;
		while (res) {

			vector<dat> D(M);
			vector<int> ind(N);
			queue<int> que;
			for (int i = 0; i < N; i++) que.emplace(i);

			while (!que.empty()) {

				int now = que.front();
				que.pop();
				if (ind[now] == M) {
					res = false;
					break;
				}

				auto &Dnow = D[grid[now][ind[now]]];
				if (Dnow.size != -1) {
					if (Dnow.size < mx) {
						Dnow.size++;
						Dnow.mem.emplace_back(now);
					}
					else {
						Dnow.size = -1;
						for (const auto &e : Dnow.mem) que.emplace(e);
						que.emplace(now);
					}
				}
				else que.emplace(now);
				ind[now]++;
			}

			if (res) {
				mx = 0;
				for (int i = 0; i < M; i++) {
					chmax(mx, D[i].size);
				}
				mx--;
			}

		}

		return mx + 1;

	};

	cout << select() << "\n";

	return 0;
}

