		return a.y < b.y;
	}
};

int n, m, a[310][310], p[310], sol;
bool ok[310];
queue<int> q[310];
priority_queue<par> pq;
multiset<int> s;

int main(){
	scanf("%d %d", &n, &m);
	for ( int i = 0; i < n; i++ ){
		p[i] = 0;
		for ( int j = 0; j < m; j++ ){
			scanf("%d", &a[i][j]);
			--a[i][j];
		}
		q[a[i][0]].push(i);
	}

	for ( int i = 0; i < m; i++ ){
		ok[i] = true;
		pq.push(par(i, q[i].size()));
		s.insert(q[i].size());
		sol = max(sol, (int)q[i].size());
	}
	while ( !pq.empty() ){

		par h = pq.top();
		pq.pop();

		if ( !ok[h.x] ) continue;
		ok[h.x] = false;
		s.erase(s.find(q[h.x].size()));

		while ( !q[h.x].empty() ){
			int in = q[h.x].front(); q[h.x].pop();

			for ( ; p[in] < m && !ok[a[in][p[in]]] ; p[in]++ )
				;

			if ( p[in] < m ){
				s.erase(s.find(q[a[in][p[in]]].size()));
				q[a[in][p[in]]].push(in);
				pq.push(par( a[in][p[in]], q[a[in][p[in]]].size() ));
				s.insert(q[a[in][p[in]]].size());
			}
			else{
				printf("%d\n", sol);
				return 0;
			}
		}
		sol = min(sol, *(--s.end()) );

	}

	return 0;
}

