    for (int i = 0; i < n; ++i)
    {
        priority_queue <fun> q;
        for (int j = 0; j < m; ++j)
        {
            fun tmp;
            tmp.ii = j;
            scanf("%d", &tmp.v);
            q.emplace(tmp);
        }
        for (int j = 0; j < m; ++j)
        {
            mapp[i][j] = q.top().ii;
            q.pop();
        }
        vec[mapp[i][cnt[i]++]].emplace_back(i);
    }
    int flag = 1;
    while (flag)
    {
        fun tmp;
        tmp.v = 0;
        for (int i = 0; i < m; ++i)
            if (vec[i].size() > tmp.v)
            {
                tmp.v = vec[i].size();
                tmp.ii = i;
            }
        if (!tmp.v)
            break;
        ans = min(ans, tmp.v);
        for (int i = 0; i < tmp.v; ++i)
        {
            int p = vec[tmp.ii][i];
            vec[mapp[p][cnt[p]++]].emplace_back(p);
            if (cnt[p] == m)
