PII solve(int n, int m){
    int participant[501];
    memset(participant,0,sizeof(participant));
    FREP(i,1,n){
        int cursport = m+2;
        int curpos = m+2;
        FREP(j,0,ans.size()-1){
            if(personpref[i][ans[j]]<curpos){
                cursport = ans[j];
                curpos = personpref[i][ans[j]];
            }
        }
        participant[cursport]++;
    }
    int mxx = 0;
    int mxi = -1;
    FREP(i,1,m){
        if(participant[i]>mxx){
            mxx = participant[i];
            mxi  = i;
        }
    }
    return make_pair(mxx,mxi);
}

int realsolve(int n, int m){
    FREP(i,1,m)ans.PB(i);
    PII curans = solve(n,m);
    while(true){
        int sp = curans.second;
        ans.erase(remove(ans.begin(),ans.end(),sp));
        PII nxtans = solve(n,m);
        if(nxtans.first<curans.first){
            curans = nxtans;
        }
        else{
            break;
        }
    }
    return curans.first;
}

