constexpr int inf = 1e9;

class SolveDreamer{
private:
    const int n, m;
    std::vector<std::vector<int>> A;
public:
    SolveDreamer(int nn, int mm): n(nn), m(mm){
        A.resize(n, std::vector<int>(m));
    }
    std::vector<int>& operator [](int k){ return A[k]; }
    int solve(){
        std::vector<bool> B(m, false);
        std::vector<int> Ptr(n, 0);
        std::vector<int> Counter(m);
        int res = inf;
        REP(_, m){
            REP(i, n) while(Ptr[i] < m and B[ A[i][Ptr[i]] ] ) Ptr[i]++;
            std::fill(Counter.begin(), Counter.end(), 0);
            REP(i, n) Counter[A[i][Ptr[i]]]++;
            int mx = -1, argmx;
            REP(i, m) if(mx < Counter[i]){
                mx = Counter[i];
                argmx = i;
            }
            chmin(res, mx);
            B[argmx] = true;
        }
        return res;
    }
};


