int n, m;
int a[300][300];
int c[300];
int d[300];

P hoge() {
    REP(i,m) {
        d[i] = 0;
    }
    REP(i,n) {
        REP(j,m) {
            if (c[a[i][j]]) {
                d[a[i][j]]++;
                break;
            }
        }
    }
    long mv = 0, mi;
    REP(i,m) {
        if (d[i] > mv) {
            mv = d[i];
            mi = i;
        }
    }
    return P(mv,mi);
}

