#define fo(i,s,t) for(int i = s; i <= t; ++ i)
#define fd(i,s,t) for(int i = s; i >= t; -- i)
const int maxn = 305;

int a[maxn][maxn], n, m;
int sum[maxn],now[maxn];

bool judge(int x)
{
	memset(sum,0,sizeof(sum));
	memset(now,0,sizeof(now));
	fo(i,1,n) sum[a[i][1]] ++, now[i] = 1;
	for(;;)
	{
		int i;
		for(i=1;i<=m;++i)
			if(sum[i]>x)
				break;
		sum[i] = 0;
		if(i==m+1) return true;
		fo(s,1,n) if(a[s][now[s]]==i)
		{
			if(now[s]==m) return false;
			sum[a[s][++now[s]]] ++;
		}
	}
}

int main()
{
	scanf("%d%d",&n,&m);
	fo(i,1,n) fo(j,1,m) scanf("%d",&a[i][j]);
	int lb=0,ub=n,mid,pos;
	while(lb<=ub)
	{
		mid=lb+ub>>1;
		if(judge(mid)) pos=mid,ub=mid-1;
		else lb=mid+1;
	}
	printf("%d\n",pos);
	return 0;
}

