int vec_remove(vi&a, int x)
{
	int i;

	for(i=a.size()-1;i>=0;i--)
	{
		if(a[i]==x)
		{
			break;
		}
	}
	auto it=a.begin()+i;
	a.erase(it);
	return i==a.size();
}


