#include <cstdio>
#include <queue>
#include <unordered_map>

using namespace std;
typedef long long int ll;
#define MAXN    512
#define MOD1    1000000007
#define MOD2    1000000021

int N, M;
int A[MAXN][MAXN];

int ndel[MAXN*MAXN];
int del[MAXN*MAXN][MAXN];
int s[MAXN*MAXN][MAXN];
int ns;

ll myhash(int ps, ll mod)
{
    ll i = 0;
    ll ret = 0;
    ll base = 1;
    for(i = 1;i <= M;++i)
    {
        if(del[ps][i])
            ret = (ret + base*i) % mod;
        base = (base*MAXN) % mod;
    }
    return ret;
}

unordered_map<ll,bool> have1, have2;

int main(void)
{
    int i = 0, j = 0;
    int ans = MAXN;
    queue<int> q;
    scanf("%d%d", &N, &M);
    for(i = 0;i < N;++i)
        for(j = 0;j < M;++j)
            scanf("%d", &(A[i][j]));
    q.push(0);
    while(!q.empty())
    {
        int part[MAXN] = {0};
        int maxp = 0;
        int ps = q.front(); q.pop();
        for(i = 0;i < N;++i)
            part[A[i][s[ps][i]]]++;
        for(i = 1;i <= M;++i)
            if(part[i] > maxp)
                maxp = part[i];
        if(maxp < ans) ans = maxp;
        if(ndel[ps] == M-1) continue;
        for(i = 1;i <= M;++i)
            if(part[i])
            {
                int news = ns++;
                ll hash1 = 0, hash2 = 0;
                for(j = 1;j <= M;++j)
                    del[news][j] = del[ps][j];
                del[news][i] = 1;
                ndel[news] = ndel[ps]+1;
                hash1 = myhash(news,MOD1);
                hash2 = myhash(news,MOD2);
                if(have1[hash1]&&have2[hash2])
                {
                    ns--;
                    continue;
                }
                for(j = 0;j < N;++j)
                {
                    int nxt = s[ps][j];
                    while(del[news][A[j][nxt]]) ++nxt;
                    s[news][j] = nxt;
                }
                q.push(news);
                have1[hash1] = 1;
                have2[hash2] = 1;
            }
    }
    printf("%d\n", ans);
    return 0;
}

