using namespace std;
const int MAXN = 310;
int a[MAXN][MAXN];
int upto[MAXN];
bool sports[MAXN];
int n, m;
int cnt[MAXN];
void bruteforce(){
	int res = n;
	for(int msk = 1; msk < (1 << m); msk++){
		vector<int> kaunt(m + 1);
		for(int i = 1; i <= m; i++) kaunt[i] = 0;
		for(int i = 1; i <= n; i++){
			for(int j = 1; j <= m; j++){
				int val = a[i][j] - 1;
				if(msk & (1 << val)) {
					kaunt[val + 1]++;
					break;
				}
			}
		}
		int tmpmx = 0;
		for(int i = 1; i <= m; i++) tmpmx = max(tmpmx, kaunt[i]);
		res = min(res, tmpmx);
	}
	printf("%d\n", res);
}
bool check(int v){
	//printf("Checking %d\n", v);
	for(int i = 1; i <= m; i++){
		sports[i] = true;
		cnt[i] = 0;
	}
	for(int i = 1; i <= n; i++) upto[i] = 1;
	bool start = true;
	while(true){
		bool fails = false;
		for(int i = 1; i <= n; i++){
			bool moved = false;
			while(upto[i] <= m && !sports[a[i][upto[i]]]) {moved = true; upto[i]++;}
			if(upto[i] > m) return false;
			if(moved || start) cnt[a[i][upto[i]]]++;
		}
		//for(int i = 1; i <= m; i++) if(sports[i]) printf("%d : %d\n", i, cnt[i]);
		//printf("\n");
		for(int i = 1; i <= m; i++) if(sports[i] && cnt[i] > v){
			sports[i] = false;
			fails = true;
		}
		start = false;
		if(!fails) return true;
	}
}
int main(){
	scanf("%d %d", &n, &m);
	for(int i = 1; i <= n; i++)
		for(int j = 1; j <= m; j++){
			scanf("%d", &a[i][j]);
		}
	int ans = n;
	int lo = 1, hi = n - 1;
	while(lo <= hi){
		int md = (lo + hi) / 2;
		if(check(md)) {ans = md; hi = md - 1;}
		else lo = md + 1;
	}
	printf("%d\n", ans);
	//bruteforce();
	return 0;
}

