using namespace std;

const int MAXN = 300+5;
const int MOD = 1e9+7;


int grid[MAXN][MAXN];

int best = MAXN;
int n;
int m;

bool take[MAXN];
void recurse(){
    int cnt = 0;
    FOR(i,m)cnt += take[i];
    if(cnt == 0)return;

    int f[m];FOR(i,m)f[i] = 0;

    FOR(i,n){
        FOR(j,m){
            if(take[grid[i][j]]){
                f[grid[i][j]]++;
                break;
            }
        }
    }
    int x = 0;
    FOR(i,m){
        if(!take[i])continue;
        if(f[x] < f[i])x= i;
    }
    best= min(best,f[x]);
    take[x] = 0;
    recurse();

}


void solve(){

    cin >> n >> m;
    FOR(i,n){
        FOR(j,m){
            cin >> grid[i][j];
            grid[i][j]--;
        }
    }
   // vi x;FOR(i,n)x.pb(i);
    FOR(i,m)take[i] = 1;
    recurse();
    cout << best << endl;
}


