bool check(vec<deque<int>> A, int x)
{
   while (true)
   {
      rep(i, 0, SZ(A)) {
         if (SZ(A[i]) == 0) return false;
      }

      map<int,int> m;
      rep(i, 0, SZ(A)) {
         m[A[i][0]]++;
      }
      set<int> s;
      EACH(i, m) {
         if (i->second > x) s.insert(i->first);
      }
      bool flag = true;
      rep(i, 0, SZ(A)) {
         if (EXIST(s, A[i][0])) {
            A[i].pop_front();
            flag = false;
         }
      }
      if (flag) {
         return true;
      }
   }
}


