void f(int N, int M, vector<vector<int>> &A, int &ans, vector<int> sports) {
    if (sports.size() == 0) {
        return;
    }
    vector<int> can(M, 0);
    for (auto x: sports) can[x] = 1;

    vector<int> use(M, 0);
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            if (can[A[i][j]]) {
                use[A[i][j]]++;
                break;
            }
        }
    }

    int kind = max_element(use.begin(), use.end()) - use.begin();
    ans = min(ans, use[kind]);
    sports.erase(find(sports.begin(), sports.end(), kind));
    f(N, M, A, ans, sports);
}

int main() {

    int N, M;
    cin >> N >> M;

    vector A(N, vector(M, 0));
    for (int i = 0; i < N; i++) for (int j = 0; j < M; j++) cin >> A[i][j], A[i][j]--;

    vector<int> sports(M);
    iota(sports.begin(), sports.end(), 0);

    int ans = N;
    f(N, M, A, ans, sports);

    cout << ans << endl;

}

