template <class T>inline T updmax(T& a, T b) {return a = max(a, b);}
template <class T>inline T updmin(T& a, T b) {return a = min(a, b);}

class Solution {
public:
	void solve() {
		int n, m;
		cin >> n >> m;
		vector<vector<int>> a(n, vector<int>(m, 0));
		for(int i=0; i<n; i++)for(int j=0; j<m; j++)cin >> a[i][j];
		for(int i=0; i<n; i++)for(int j=0; j<m; j++)a[i][j]--;
		vector<int> cnt(m, 0);
		vector<bool> flag(m, 0);
		vector<int> idx(n, 0);
		int ret = n;
		for(int i=0; i < n; i++)cnt[a[i][0]]++;
		for(int i = 0; i < m; i++){
			for(int j = 0; j < n; j++){
				while(idx[j] != m && flag[a[j][idx[j]]]){
					cnt[a[j][idx[j]]]--;
					idx[j]++;
					cnt[a[j][idx[j]]]++;
				}
			}
			int max_cnt = 0;
			int max_idx = -1;
			for(int i=0; i < m; i++){
				if(cnt[i] > max_cnt){
					max_cnt = cnt[i];
					max_idx = i;
				}
			}
			updmin(ret, max_cnt);
			flag[max_idx] = true;
		}
		cout << ret << endl;
		return;
	};
};

