int n, m;

bool check(int x){
	for(int i = 1; i <= m; i++) cnt[i] = 0;
	for(int i = 1; i<= n; i++){
		while(!q[i].empty()) q[i].pop();
		for(int j = 1; j <= m; j++) q[i].push(a[i][j]);
	}
	while(true){
		int p = 0;
		for(int i = 1; i <= n; i++){
			cnt[q[i].front()]++;
			if(cnt[q[i].front()] > x) p = q[i].front();
		}
		if(p == 0) return true;
		for(int i = 1; i <= n; i++){
			cnt[q[i].front()]--;
			if(p == q[i].front()) q[i].pop();
			if(q[i].empty()) return false;
		}
	}
}

void solve(){
	int l = 1, r = n + 1, ans = 0;
	while(l <= r){
		int mid = (l + r) >> 1;
		if(check(mid)) ans = mid, r = mid - 1;
		else l = mid + 1;
	}
	printf("%d\n", ans);
}

