bool cond(int x, vector<queue<int>>dt)
{
	for (;;)
	{
		//数える
		vector<int>cnt(M, 0);
		for (int i = 0; i < N; ++i)
		{
			if (dt[i].empty())return false;//NG
			int match = dt[i].front() - 1;
			cnt[match]++;
		}
		int pill = -1;
		for (int j = 0; j < M; ++j)
		{
			if (cnt[j] > x)
			{
				pill = j;
				break;
			}
		}
		if (pill < 0)break;//OK
		for (int i = 0; i < N; ++i)
		{
			if (dt[i].front() - 1 == pill)
			{
				dt[i].pop();
			}
		}
	}
	return true;
}

