vector<int> calc(vector<bool> use, vector<vector<int>> A) {

    vector<int> num(A[0].size(), 0);
    FOR(i, 0, A.size()) {
        FOR(j, 0, A[0].size()) {
            if (use[A[i][j]]) {
                num[A[i][j]]++;
                break;
            }
        }
    }

    return num;
}

