//最大をx人以下にできるか？
bool check(int x) {
	int rnk[300][300];
	int tmp[300][300];
	int i, j, k;

	for (i = 0; i < n; i++) { for (j = 0; j < m; j++) { rnk[i][j] = _rank[i][j]; } }

	for (i = 0; i < m; i++) {
		for (j = 0; j < m - i; j++) {
			int cnt = 0;
			for (k = 0; k < n; k++) {
				cnt += (rnk[k][j] == 0);
			}
			if (cnt > x) {
				break;
			}
		}
		if (j == m - i) return true;

		int eraseSport = j;	//削除するスポーツの番号
		for (j = 0; j < n; j++) {
			int eraseNum = rnk[j][eraseSport];
			int id = 0;
			for (k = 0; k < m - i; k++) {
				if (rnk[j][k] > eraseNum) { tmp[j][id++] = rnk[j][k] - 1; }
				if (rnk[j][k] < eraseNum) { tmp[j][id++] = rnk[j][k]; }
			}
		}

		for (j = 0; j < n; j++) {
			for (k = 0; k < m - i - 1; k++) {
				rnk[j][k] = tmp[j][k];
			}
		}
	}
	return false;
}

