        result = min(result, max_size);
        bool valid = true;
        used_list.insert(target_idx);

        REP(j, memo[target_idx].size()) {
            while(true) {
                int next_idx = memo[target_idx][j].next();
                if(next_idx == -1) {
                    cout << result << endl;
                    return;
                }
                if(used_list.count(next_idx) == 0) {
                    memo[next_idx].PB(memo[target_idx][j]);
                    break;
                }
            }
        }

        memo[target_idx].clear();
    }
}

