  ios::sync_with_stdio(false);

  cin >> N >> M;
  REP(hi, N)
    REP(wi, M) cin >> A[hi][wi];

  vector< int > p(M);
  iota(ALL(p), 1);

  int ans = solve(p);
  cout << ans << endl;

  return 0;
}

