bool check(int num) {
	fill(cnt, cnt + M + 1, 0);
	for(int i = 1; i <= N; i++) {
		ptr[i] = 1;
		cnt[A[i][1]]++;
	}
	while(1) {
		debug("%d ~ %d\n", num, mx());
		if(mx() <= num) return true;
		int t = 0;
		for(int i = 1; i <= M; i++)
			if(cnt[i] > num) {
				t = i;
				break;
			}
		debug("t = %d\n", t);
		cnt[t] = -1;
		for(int i = 1; i <= N; i++) {
			if(cnt[A[i][ptr[i]]] != -1) continue;
			while(ptr[i] <= M && cnt[A[i][ptr[i]]] == -1)
				ptr[i]++;
			if(ptr[i] > M) return false;
			debug("Add: %d\n", A[i][ptr[i]]);
			cnt[A[i][ptr[i]]]++;
		}
	}
}

