bool Check(int ans)
{
	int f[MAXN + 5], sum[MAXN + 5];
	for(int i = 1; i <= N; i++) f[i] = 1;
	bool check = false;
	while(!check){
		memset(sum, 0, sizeof(sum));
		for(int i = 1; i <= N; i++){
			int tot = f[i], c = A[i][tot];
			sum[c]++;
		}
		bool ok = true;
		for(int i = 1; i <= M; i++){
			if(sum[i] > ans) ok = false;
		}
		if(ok){
			check = true;
			break;
		}
		else{
			for(int i = 1; i <= N; i++){
				int tot = f[i], c = A[i][tot];
				if(sum[c] > ans) f[i]++;
				if(f[i] > M) ok = true;
			}
			if(ok) break;
		}
	}
	return check;
}

