int N, M;
vector<vector<int>> pref;

int count(unordered_set<int>& games) {
    vector<int> cnt(M+1, 0);
    int m = 0;
    for (auto& row : pref) {
        for (auto& g : row) {
            if (games.count(g)) {
                m = max(m, ++cnt[g]);
                break;
            }
        }
    }
    return m;
}

signed main() {
    ios::sync_with_stdio(false);
    cin >> N >> M;
    pref.resize(N);
    for (int i = 0; i < N; i++) {
        pref[i].resize(M);
        for (int j = 0; j < M; j++) {
            cin >> pref[i][j];
        }
    }
    unordered_set<int> games;
    for (int i = 1; i <= M; i++)
        games.insert(i);
    int m = count(games);
    while (true) {
        int best = -1;
        for (int g = 1; g <= M; g++) {
            if (!games.count(g)) continue;
            games.erase(g);
            int t = count(games);
            games.insert(g);
            if (t && t <= m) {
                m = t;
                best = g;
            }
        }
        if (best < 0) {
            assert(m <= N);
            cout << m << endl;
            break;
        }
        games.erase(best);
    }
}

