bool isOk(int mid) {
  int maxVal = 0;
  for (int i = 1; i <= n; ++i) {
    for (int j = m; j > 0; --j) {
      g[i].push_back(a[i][j].id);
    }
  }
  for (int i = 1; i <= m; ++i) {
    cnt[i] = mark[i] = 0;
  }
  for (int i = 1; i <= n; ++i) {
    ++cnt[a[i][1].id];
    maxVal = max(maxVal, cnt[a[i][1].id]);
  }
  int now = m;
  while (now && maxVal > mid && (n + now - 1) / now <= mid) {
    for (int i = 1; i <= m; ++i) {
      if (cnt[i] > mid) {
        cnt[i] = 0;
        --now;
        mark[i] = 1;
        for (int j = 1; j <= n; ++j) {
          if (g[j].back() == i) {
            g[j].pop_back();
            while (mark[g[j].back()]) {
              g[j].pop_back();
            }
            ++cnt[g[j].back()];
          }
        }
        break;
      }
    }
    maxVal = 0;
    for (int i = 1; i <= m; ++i) {
      maxVal = max(maxVal, cnt[i]);
    }
  }
  return maxVal <= mid;
}

