	//各人の参加スポーツb[i]と各スポーツの参加人数c[i]の最大値maxnum
	for (int i = 0; i < n; i++) {
		b[i] = a[i][0];
		c[b[i]] ++;
	}
	int maxnum = 0;
	for (int i = 1; i <= m; i++) {
		maxnum = max(c[i], maxnum);
	}
	answer = maxnum;

	for (int k = 1; k <= m-1; k++) {
		//一番参加人数が多いスポーツを不開催にしていく

		int temp;
		maxnum = 0;
		for (int i = 1; i <= m; i++) {
			if (c[i] > maxnum) {
				temp = i;
				maxnum = c[i];
			}
		}
		flug[temp] = false;

		//flugを元に各人の参加スポーツb[i]を決定

		for (int i = 0; i <= m; i++) {
			c[i] = 0;
		}

		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (flug[a[i][j]]) {
					b[i] = a[i][j];
					c[b[i]]++;
					break;
				}
			}
		}

		int maxnum = 0;
		for (int i = 1; i <= m; i++) {
			maxnum = max(c[i], maxnum);
		}
		answer = min(answer, maxnum);

		//もうゲームを削っても最大参加人数が減らない	
		if (answer <= n / (m - k)) {
			break;
		}
	}

	cout << answer;




	return 0;
}

