const int LOGN = ((int)log2(N)) + 3;
const int LOGM = ((int)log2(M)) + 3;

int a[N][N], cnt[N];
bool mark[N];

bool func(int MAX, int n, int m)
{
	int i, j, k;
	bool flag;
	fo(i,1,m+1)
		mark[i] = 0;
	while(1)
	{
		flag = 1;
		fo(i,1,m+1)
			flag &= mark[i];
		if(flag)
			break;
		fo(i,1,m+1)
			cnt[i] = 0;
		fo(i,1,n+1)
		{
			fo(j,1,m+1)
			{
				if(!mark[a[i][j]])
				{
					cnt[a[i][j]]++;
					break;
				}
			}
		}
		flag = 1;
		fo(i,1,m+1)
		{
			if(cnt[i] > MAX)
			{
				mark[i] = 1;
				flag = 0;
			}
		}
		if(flag)
			return 1;
	}
	return 0;
}

int binsea(int l, int r, int n, int m)
{
	if(l > r)
		return INF;
	int mid = (l+r)>>1;
	if(func(mid,n,m))
		return min(mid, binsea(l,mid-1,n,m));
	return binsea(mid+1,r,n,m);
}

