int a[300][300];
int n, m;

bool solve(int k) {
  set<int> ban;
  vector<int> sel(n);
  for(int j = 0; j < m; j++) {
    vector<int> c(m);
    for(int i = 0; i < n; i++) {
      while(ban.count(a[i][sel[i]])) {
        sel[i]++;
        if(sel[i] >= m) return 0;
      }
      c[a[i][sel[i]]]++;
    }
    int ok = 1;
    for(int t = 0; t < m; t++) {
      if(c[t] > k) ban.emplace(t), ok = 0;
    }
    if(ok) return 1;
  }
  return 0;
}

