            stk[vq[i].front()] += 1;
        }

        auto maxit = max_element(ALL(stk));

        best = min(best, *maxit);

        int target = distance(stk.begin(), maxit);

        repeat(i, n) {
            if (vq[i].front() == target)
                vq[i].pop();

            num_of_tail += !!vq[i].empty();
        }
    }

    cout << best << endl;

    return 0;
}

