int solve(int n, int m, vector<vector<int>> &a){
    vector<int> sports(m, 0);
    int count[m];
    int min_ans = INF;
    int max_num;
    int max_itr;
    for(int loop = 0; loop < m; ++loop){
        for (int i=0; i<m; ++i){
            count[i] = 0;
        }
        for (int i=0; i<n; ++i){
            for (int j=0; j<m; ++j){
                if(sports[a[i][j]] == 0){
                    count[a[i][j]]++;
                    break;
                }
            }
        }
        max_num = -1;
        max_itr = -1;
        for (int i=0; i<m; ++i){
            if(max_num < count[i]){
                max_num = count[i];
                max_itr = i;
            }
        }
        min_ans = min(min_ans, max_num);
        sports[max_itr] = 1;
        debugpair(min_ans, max_itr+1);
    }
    return min_ans;
}

