int n, m;
int mat[300][300];
pii sum[300];
int curmx[300], have[300], where[300];

int main()
{
    ios_base::sync_with_stdio(0);
    cin >> n >> m;
    for(int i = 0; i < n; i++){
        for(int j = 0; j < m; j++){
            cin >> mat[i][j];
            sum[j].first += mat[i][j];
            sum[j].second = j;
        }
    }
    sort(sum, sum + m);
    int beg = sum[0].second;
    int best = 0;
    for(int i = 0; i < n; i++){
        curmx[i] = mat[i][beg];
        have[beg]++;
        best = max(best, have[beg]);
        where[i] = beg;
    }
    for(int i = 1; i < m; i++){
        int beg = sum[i].second;
        for(int j = 0; j < n; j++){
            if(curmx[j] < mat[j][beg]){
                have[beg]++;
                have[where[j]]--;
            }
        }
        int here = 0;
        for(int j = 0; j < m; j++){
            here = max(here, have[j]);
        }
        if(here > best){
            for(int j = 0; j < n; j++){
                if(curmx[j] < mat[j][beg]){
                    have[beg]--;
                    have[where[j]]++;
                }
            }
        }
        else{
            best = here;
            for(int j = 0; j < n; j++){
                if(curmx[j] < mat[j][beg]){
                    curmx[j] = mat[j][beg];
                    where[j] = beg;
                }
            }
        }
    }
    cout << best << endl;
    return 0;
}

