int vote[MAXN];
int n, m;

bool check(int k) {
    unordered_set<int> trash;
    memset(point, 0, sizeof(point));
    while (trash.size() < m) {
        memset(vote, 0, sizeof(vote));
        bool flag = true;
        for (int i = 0; i < n; i++) {
            while (trash.find(data[i][point[i]]) != trash.end()) point[i]++;
            vote[data[i][point[i]]]++;
            if (vote[data[i][point[i]]] > k) {
                trash.insert(data[i][point[i]]);
                flag = false;
                break;
            }
        }
        if (flag) return true;
    }
    return false;
}

