	for (int j = 0; j < m; ++j)
	{
		if (!skip[cur[ind][j]])
		{
			count[cur[ind][j]]++;
			if (!ans)
				ans = solution(cur, ind + 1, skip, count);
			else
				ans = min(ans, solution(cur, ind + 1, skip, count));

			count[cur[ind][j]]--;
		}

		skip[cur[ind][j]]++;

		if (count[cur[ind][j]] || j + 1 == m)
		{
			for (int z = 0; z <= j; ++z)
				skip[cur[ind][z]]--;

			break;
		}
	}

	return ans;
}


