unsigned readUnsigned() {
    int c;
    do { c = ::getchar_unlocked(); } while (c < '0');
    unsigned result = c - '0';
    if ((c = ::getchar_unlocked()) >= '0') {
        result *= 10;
        result += c - '0';
        if ((c = ::getchar_unlocked()) >= '0') {
            result *= 10;
            result += c - '0';
        }
    }
    return result;
}

unsigned N, M;
unsigned A[304][304];

bool valid(unsigned x) {
    unsigned I[304] = {0};
    bool bad[304] = {0};
    for (unsigned sports = M;;) {
        unsigned counts[304] = {0};
        for (unsigned i = 0; i < N; ++i) {
            if (++counts[A[i][I[i]]] > x) {
                unsigned badsport = A[i][I[i]];
                bad[badsport] = true;
                if (--sports * x < N) return false;
                for (unsigned j = 0; j < N; ++j) {
                    while (bad[A[j][I[j]]]) {
                        ++I[j];
                    }
                }
                goto next;
            }
        }
        return true;
next:;
    }
    return false;
}

