	int mid;
	for(int i=0;i<N+1;++i){
		for (auto &c : checked) c = false;
		for (auto &c : cnt) c = 0;
		if (check(i, cnt, checked, 0) == -1) {
			high = i;
			break;
		}
	}
	cout << high << endl;
}

