		numPlayers[maxSport] = -1; //Remove sport
		FOR(j, 0, m, 1) if(numPlayers[j] != -1) numPlayers[j] = 0;
		FOR(j, 0, n, 1) {
			while (numPlayers[matrix[j][curSport[j]]] == -1) {
