void solve(bool read) {
  int n, m;
  cin >> n >> m;
  vector<vector<int>> a(n, vector<int>(m));
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < m; ++j) {
      cin >> a[i][j];
      --a[i][j];
    }
  }

  int ans = n;
  vector<int> uk(n, 0);
  vector<char> used(m, false);
  for (int it = 0; it < m; ++it) {
    vector<int> cnt(m);
    for (int i = 0; i < n; ++i) {
      ++cnt[a[i][uk[i]]];
    }
    int mx = 0;
    int best_id = -1;
    for (int i = 0; i < m; ++i) {
      if (cnt[i] > mx) {
        mx = cnt[i];
        best_id = i;
      }
    }
    relax_min(ans, mx);
    used[best_id] = true;
    for (int i = 0; i < n; ++i) {
      while (uk[i] < m && used[a[i][uk[i]]]) {
        ++uk[i];
      }
    }
  }

  cout << ans << endl;

}

