using namespace std;
inline int rd() {
	int x=0,f=1;char ch=getchar();
	while (ch>'9'||ch<'0') {if(ch=='-')f=-1;ch=getchar();}
	while (ch>='0'&&ch<='9'){x=(x<<1)+(x<<3)+ch-'0';ch=getchar();}
	return x*f;
}
int n,m,a[N][N],vis[N],cnt[N];
int main() {
	n = rd(), m = rd();
	for (int i=1;i<=n;i++)
		for (int j=1;j<=m;j++) a[i][j] = rd();
	for (int i=1;i<=m;i++) vis[i] = 1;
	int ans = n;
	for (int _=1;_<=m;_++) {
		memset(cnt,0,sizeof(cnt));
		for (int i=1;i<=n;i++)
			for (int j=1;j<=m;j++)
				if (vis[ a[i][j] ]) {
					cnt[ a[i][j] ]++;
					break;
				}
		int mx = 0, id = 0;
		for (int i=1;i<=m;i++)
			if (cnt[i] >= mx)
				mx = cnt[i], id = i;
		ans = min(ans, mx);
		vis[id] = 0;
	}
	printf("%d\n",ans);
	return 0;
}

