const int Nmax = 303;

int n, m, i, st, dr, mid, a[Nmax][Nmax], ap[Nmax], p[Nmax], j;
bool sel[Nmax];

bool verif(int x)
{
    int i, id;
    for(i=1; i<=m; ++i) sel[i] = 1, ap[i] = 0;
    for(i=1; i<=n; ++i) p[i] = 1, ++ap[a[i][1]];

    while(true)
    {
        id = 0;
        for(i=1; i<=m; ++i)
            if(ap[i] > ap[id]) id = i;

        if(ap[id] <= x) return 1;
        sel[id] = 0; ap[id] = 0;

        for(i=1; i<=n; ++i)
        if(a[i][p[i]] == id)
        {
            while(!sel[a[i][p[i]]] && p[i] <= m) ++p[i];
            if(p[i] == m+1) return 0;
            ++ap[a[i][p[i]]];
        }
    }
}

