    rep(i,N)rep(j,M){
        cin >> A[i][j]; A[i][j]--;
    }

    set<int> sports; // 開催する競技の集合
    rep(i,M) sports.insert(i);

    int ans = solve(sports);
    cout << ans << endl;
}

