int N, M;

bool Check(int ans)
{
	int f[MAXN + 5], sum[MAXN + 5];
	bool t[MAXN + 5];
	for(int i = 1; i <= N; i++) f[i] = 1;
	for(int i = 1; i <= M; i++) t[i] = true;
	bool check = false;
	while(!check){
		memset(sum, 0, sizeof(sum));
		for(int i = 1; i <= N; i++){
			int tot = f[i], c = A[i][tot];
			sum[c]++;
		}
		bool ok = true;
		for(int i = 1; i <= M; i++){
			if(sum[i] > ans) ok = false;
		}
		if(ok){
			check = true;
			break;
		}
		else{
			for(int i = 1; i <= N; i++){
				int tot = f[i], c = A[i][tot];
				if(sum[c] > ans){
					t[c] = false;
					while(f[i] <= M && !t[A[i][f[i]]]) f[i]++;
				}
				if(f[i] > M) ok = true;
			}
			if(ok) break;
		}
	}
	return check;
}

