        for(int j = 0; j < m; ++j) {
            cin >> a[i][j];
            a[i][j] -= 1;
        }

    auto getState = [&] (vector<int> mask) {
        vector<int> has(m, 0);
        vector<int> cnt(m, 0);

        for(auto val : mask)
            has[val] = 1;

        for(int i = 0; i < n; ++i)
            for(int j = 0; j < m; ++j)
                if(has[a[i][j]]) {
                    cnt[a[i][j]] += 1;
                    break;
                }
        return cnt;
    };

    vector<int> mask;
    for(int i = 0; i < m; ++i)
        mask.push_back(i);
    vector<int> deleted(m, 0);

    int ans = 1e9;

    while(not mask.empty()) {
        vector<int> state = getState(mask);
        int maxx = 0;
        for(int i = 0; i < m; ++i) {
            maxx = max(state[i], maxx);
        }

        vector<int> new_mask;

        for(int i = 0; i < m; ++i) {
            if(state[i] != maxx and not deleted[i]) {
                new_mask.push_back(i);
            } else {
                deleted[i] = 1;
            }
        }

        ans = min(ans, maxx);
        mask = new_mask;
    }

    cout << ans << "\n";
