ll BinarySearchMin(ll lb, ll ub) {
  // 返り値の範囲：(lb, ub]
  // 条件：
  //   (lb, ub)で検証できること
  //   C(lb)==false, C(ub)==true
  while (ub - lb > 1) {
    ll mid = ((lb + ub) >> 1);
    if (C(mid)) {
      // (lb, mid]
      ub = mid;
    } else {
      // (mid, ub]
      lb = mid;
    }
  }
  return ub;
}

