const int MAXN = 305;

int N, M;
int A[MAXN][MAXN];

void input()
{
    read(N); read(M);
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= M; ++j) {
            read(A[i][j]);
        }
    }
}

void solve()
{
    static bool flag[MAXN];
    int ans = +oo;

    std::fill(flag + 1, flag + M + 1, true);
    for (int k = 1; k <= M; ++k) {
        static int cnt[MAXN];
        std::fill(cnt + 1, cnt + M + 1, 0);
        for (int i = 1; i <= N; ++i) {
            for (int j = 1; j <= M; ++j) {
                if (flag[A[i][j]]) {
                    ++cnt[A[i][j]];
                    break;
                }
            }
        }
        int t = std::max_element(cnt + 1, cnt + M + 1) - cnt;
        chkmin(ans, cnt[t]);
        flag[t] = false;
    }

    printf("%d\n", ans);
}

