int n, m;
int a[N][M];

bool test(int p) {
  int cnt[M], first[N];
  bool select[N];
  fill(first + 1, first + n + 1, 1);
  fill(select + 1, select + m + 1, true);

  bool flag = true;
  while (flag) {
    fill(cnt + 1, cnt + m + 1, 0);
    for (int i = 1; i <= n; i++) {
      cnt[a[i][first[i]]]++;
    }

    flag = false;
    for (int i = 1; i <= m; i++) {
      if (cnt[i] > p) {
//        printf("%d [%d]\n", i, cnt[i]);
        select[i] = false;
        flag = true;
      }
    }
    for (int i = 1; i <= n; i++) {
      while (first[i] <= m && !select[a[i][first[i]]]) {
        first[i]++;
      }
      if (first[i] > m) return false;
    }
  }
  return true;
}

int main() {
  scanf("%d%d", &n, &m);
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) scanf("%d", a[i] + j);
  }

  int lb = 1, ub = n;
  while (lb < ub) {
    int mid = (lb + ub) / 2;
    if (test(mid)) ub = mid;
    else lb = mid + 1;
  }
  printf("%d", lb);

  return 0;
}

