const int INF = 1 << 30;

int N, M;

void dfs(const vector<vector<int>>& A, set<int>& S, int& ans) {
    vector<int> cnt(M, 0);
    rep(i, 0, N) {
        rep(j, 0, M) {
            if (S.count(A[i][j])) {
                ++cnt[A[i][j]];
                break;
            }
        }
    }
    int max_sport;
    int max_participants = 0;
    rep(i, 0, M) {
        if (chmax(max_participants, cnt[i])) {
            max_sport = i;
        }
    }
    chmin(ans, max_participants);
    S.erase(max_sport);
    if (S.size()) {
        dfs(A, S, ans);
    }
}

int main() {
