    rep(i, 0, N) rep(j, 0, M) {
        cin >> A[i][j];
        --A[i][j];
    }
    int ans = INF;
    set<int> S;
    rep(i, 0, M) {
        S.insert(i);
    }
    dfs(A, S, ans);
    cout << ans << endl;
    return 0;
}

