bool P(const int x)
{
    map< int,set<int> > game;
    VI J(N+1,1), vis(N+1,false), canuse(M+1,true);
    while (true) {
        FOR(i,1,N+1) if (!vis[i]) {
            const int j = J[i];
            if (j >= M)
                return false;
            const int g = A[i][j];
            if (canuse[g]) {
                game[g].insert(i);
                vis[i] = true;
                if (game[g].size() > x) {
                    canuse[g] = false; 
                    FOR_ALL(p,game[g]) {
                        vis[*p] = false; J[*p]++;
                    }
                }
            }
            else
                J[i]++;
        }
        int cnt = 0;
        FOR(i,1,N+1) if (vis[i])
            cnt++;
        if (cnt == N)
            break;
    }
    return true;
}

