				if(!check[A[i][j]]) {
					cnt[A[i][j]]++;
					break;
				}
			}
		}
		int idx = max_element(cnt, cnt + M) - cnt;
		check[idx] = 1;
		ans = min(ans, cnt[idx]);
	}

	cout << ans << endl;
}

