bool nibu(int c, vector<queue<int> > A)
{
    while (true) {
        map<int, int> d;
        for (auto v : A) d[v.front()]++;
        set<int> del;
        for (auto k : d) if (k.second > c) del.insert(k.first);
        if (del.empty()) return true;
        for (auto &v : A) if (del.find(v.front()) != del.end()) {
            v.pop();
            if (v.empty()) return false;
        }
    }
}

int main()
{
    cin >> N >> M;
    vector<queue<int>> A(N);
    REP(i, N) REP(j, M) {
        int tmp;
        cin >> tmp;
        A[i].push(tmp);
    }
    int l = 0, r = N; // l:不可能 r:可能
    while (r - l > 1) {
        int c = (l + r) / 2;
        (nibu(c, A) ? r : l) = c;
    }
    cout << r << endl;
}

