pll calc(vector<deque<ll>> &a,ll n,ll m){
	vll cnt(m+1);
	rep(i,0,n-1){
		ll idx=a[i].front();
		cnt[idx]++;
	}
	ll kind=MaxI(cnt);
	ll nm=cnt[kind];
	return {kind,nm};
}


