ll solve(const V<V<ll>> &alist, ll n, ll m, ll idxs[303], bool removed[303])
{
    debug_printf("---- removed\n");
    debug_print(removed, m);

    rep (i, n) {
        for ( ; ; ) {
            if (idxs[i] >= m) return 1e18;
            debug_printf("xx1 i=%lld idxs[i]=%lld\n", i, idxs[i]);
            ll a = alist[i][idxs[i]];
            if (!removed[a]) break;
            idxs[i]++;
        }
    }

    S ll cnts[303];
    memset(cnts, 0, sizeof(cnts));
    rep (i, n) {
        debug_printf("xx2 i=%lld idxs[i]=%lld\n", i, idxs[i]);
        cnts[alist[i][idxs[i]]]++;
    }

    ll maxcnt = 0LL;
    rep (i, m) maxcnt = max(maxcnt, cnts[i]);
    rep (i, m) if (cnts[i] == maxcnt) removed[i] = true;

    return min(maxcnt, solve(alist, n, m, idxs, removed));
}

