bool check(int mid)
{
	memset(cnt,0,sizeof(cnt));
	memset(vis,0,sizeof(vis));
	for(int i=1;i<=n;++i)choice[i]=1,++cnt[a[i][1]];
	while(1)
	{
		int full=0;
		for(int i=1;i<=m;++i)
			if(cnt[i]>mid)
			{
				full=i;
				break;
			}
		if(!full)return true;
		vis[full]=true;
		for(int i=1;i<=n;++i)
		{
			if(a[i][choice[i]]==full)
			{
				--cnt[full];
				while(choice[i]<=m && vis[a[i][choice[i]]])++choice[i];
				if(choice[i]>m)return false;
				++cnt[a[i][choice[i]]];
			}
		}
	}
}

