				yes=true;
				vis[i]=1;
				break;
			}
		}
		if(yes==false){
			return 1;
		}
		for(int i=1;i<=m;i++){
			tong[i]=0;
		}
		for(int i=1;i<=n;i++){
			for(int j=point[i];j<=m;j++){
				if(vis[a[i][j]]){
