const int MX=311;
int n,m;
int a[MX][MX];
int g[MX][MX];

int ckfst(int v){
	static int c[MX];
	memset(c+1,0,sizeof(int)*m);
	for(int i=1;i<=n;i++)
		for(int j=1;j<=m;j++)if(g[i][j]){
			if(++c[g[i][j]]>v)return g[i][j];
			else break;
		}
	return 0;
}
bool ck(int mid){
	memcpy(g,a,sizeof(a));
	int C=0,R;
	while(R=ckfst(mid)){
		++C;
		for(int i=1;i<=n;i++)
			for(int j=1;j<=m;j++)
				if(g[i][j]==R)g[i][j]=0;
	}
	return C<m;
}
int main(){
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n;i++)
		for(int j=1;j<=m;j++)
			scanf("%d",&a[i][j]);
	int l=1,r=m;
	while(l<r){
		int mid=(l+r)>>1;
		if(ck(mid))r=mid;else l=mid+1;
	}
	printf("%d\n",l);
	return 0;
}

