void Init()
{
	scanf("%d%d" , &n , &m);
	For(i , 1 , n)
		For(j , 1 , m)
			scanf("%d" , &a[i][j]);
}

void dfs(int now)
{
	if (now == n + 1)
	{
		maxx = 0;
		For(i , 1 , m)
			maxx = max(maxx , ans[i]);
		minn = min(minn , maxx);
		return ;
	}
	For(i , 1 , m)
	{
		if (choose[a[now][i]])
		{
			++ ans[a[now][i]];
			choose[a[now][i]] = 1;
			dfs(now + 1);
			choose[a[now][i]] = 0;
			-- ans[a[now][i]];
			For(j , i , m)
				++ cannot[a[now][j]];
			break;
		}
		if (cannot[a[now][i]] || ans[a[now][i]] + 1 >= minn)
		{
			++ cannot[a[now][i]];
			continue;
		}
		++ ans[a[now][i]];
		choose[a[now][i]] = 1;
		dfs(now + 1);
		choose[a[now][i]] = 0;
		-- ans[a[now][i]];
		++ cannot[a[now][i]];
	}
	For(i , 1 , m)
		-- cannot[a[now][i]];
}

