int n,m;

void solve(vector<int> v)
{
    if (v.empty()) return;
    memset(cnt,0,sizeof(cnt));
    for (int i=1;n>=i;i++)
    {
        int mx=-1;
        int mx_id = -1;
        for (int j:v)
        {
            if (a[i][j] > mx)
            {
                mx = a[i][j];
                mx_id = j;
            }
        }
        assert(mx_id != -1);
        cnt[mx_id]++;
    }
    int mx=-1;
    int sum=0;
    for (int j:v)
    {
        mx = max(mx,cnt[j]);
        sum += cnt[j];
    }
    assert(sum == n);
    ans = min(ans,mx);
    assert(mx != -1);
    vector<int> vv;
    bool found = false;
    for (int j:v)
    {
        if (found) vv.push_back(j);
        else if (cnt[j] == mx) found = true;
        else vv.push_back(j);
    }
    solve(vv);
    return;
}

