int N, M;
vector<vector<int>> A(310, vector<int>(310));

bool allUsed(vector<bool> used){
  int n = used.size();
  rep(i, n) if(used[i] == 0) return 0;
  return 1;
}

bool can(int x){
  vector<bool> used(N, 0);
  vector<bool> dont(M, 0);
  while(!allUsed(used)){
    if(allUsed(dont)) return 0;
    vector<int> cnt(M, 0);
    rep(i, N){
      if(used[i]) continue;
      rep(j, M+1){
        if(j == M) return 0;
        if(dont[A[i][j]]) continue;
        cnt[A[i][j]]++;
        break;
      }
    }
    bool l = 0;
    rep(i, M) if(cnt[i] > x) l = 1;
    rep(i, M){
      if(cnt[i] > x) dont[i] = 1;
    }
    if(l) continue;
    rep(i, N){
      if(used[i]) continue;
      rep(j, M+1){
        if(j == M) return 0;
        if(dont[A[i][j]]) continue;
        used[i] = 1;
        break;
      }
    }
    rep(i, M){
      if(cnt[i]){
        dont[i] = 1;
      }
    }
  }
  return 1;
}

