bool is_valid(int k, int N, int M, const vector<vector<int>> &A){
    vector<int> idx(N, 0);
    vector<bool> used(M + 1, true);
    used[0] = false;
    int n_used = M;
    while (true){
        vector<int> freq(M + 1, 0);
        for (int i = 0; i != N; ++i){
            while (idx[i] < M and not used[A[i][idx[i]]]){
                ++idx[i];
                if (idx[i] == M) return false;
            }
            ++freq[A[i][idx[i]]];
        }
        bool ok = true;
        for (int m = 1; m <= M; ++m){
            if (freq[m] > k){
                used[m] = false;
                --n_used;
                ok = false;
            }
        }
        if (ok) return true;
        if (n_used * k < N) return false;
    }
}


int solve(int N, int M, const vector<vector<int>> &A){
    for (int k = 1; k <= N; ++k){
        if (is_valid(k, N, M, A)){
            return k;
        }
    }
    return N;
}


