int naive() {
    int ans = 1010;
    rep(mask, 1, 1 << M) {
        map<int, int> m;
        rep(y, 0, N) {
            rep(x, 0, M) if (mask & (1 << A[y][x])) {
                m[A[y][x]]++;
                break;
            }
        }
        int ma = 0;
        fore(p, m) ma = max(ma, p.second);
        ans = min(ans, ma);
    }

    return ans;
}
//---------------------------------------------------------------------------------------------------
int check(int x) {
    vector<queue<int>> vq(N);
    vector<int> used(M, 0);
    vector<int> ok(N, 0);
    rep(y, 0, N) rep(x, 0, M) vq[y].push(A[y][x]);

    int loop = 1;
    while(loop) {
        map<int, int> m;
        rep(y, 0, N) m[vq[y].front()]++;
        vector<int> ng;
        fore(p, m) if (x < p.second) ng.push_back(p.first);

        if (ng.size() == 0) return 1;

        fore(j, ng) used[j] = 1;

        rep(y, 0, N) {
            while (!vq[y].empty() && used[vq[y].front()]) vq[y].pop();
            if (vq[y].empty()) return 0;
        }

        loop = 1;
    }

    return 0;
}
int solve() {
    if (M == 1) return N;

    int ng = 0, ok = M;
    while (ng + 1 != ok) {
        int x = (ng + ok) / 2;
        if (check(x)) ok = x;
        else ng = x;
    }
    return ok;
}
