inline void solve()
{
	static int cnt[MAXN + 5], p[MAXN + 5], ban[MAXN + 5];

	for(int i = 1; i <= n; ++i) ++cnt[a[i][1]], p[i] = 1;

	int ans = *max_element(cnt + 1, cnt + m + 1);
	for(int k = 1; k < m; ++k)
	{
		int pos = max_element(cnt + 1, cnt + m + 1) - cnt;
		ban[pos] = 1;
		for(int i = 1; i <= n; ++i) while(ban[a[i][p[i]]]) --cnt[a[i][p[i]]], ++cnt[a[i][++p[i]]];
		chkmin(ans, *max_element(cnt + 1, cnt + m + 1));
	}
	printf("%d\n", ans);
}

