bool ck (int k, vector<vector<int>>& a) {
  set<int> st;
  for (int j = 0; j < m; j++) st.insert(j);
  vector<int> pos(n, 0);
  while (true) {
    multiset<int> mlt;
    int sus = -1;
    for (int i = 0; i < n; i++) {
      int crr = a[i][pos[i]];
      mlt.insert(crr);
      if (mlt.count(crr) > k) {
        sus = crr;
        break;
      }
    }
    if (sus == -1) return true;
    st.erase(sus);
    for (int i = 0; i < n; i++) {
      for (int j = pos[i]; j <= m; j++) {
        if (j == m) return false;
        if (st.find(a[i][j]) != st.end()) {
          pos[i] = j;
          break;
        }
      }
    }
  }
}
