int read() {
  if (scanf("%d%d", &n, &m) < 2) {
    return false;
  }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      scanf("%d", &a[i][j]);
      a[i][j]--;
    }
  }
  return true;
}

int pos[maxn];
int cnt[maxn];
int del[maxn];

void getNxt(int id) {
  auto &i = pos[id];
  while (i < m && del[a[id][i]]) {
    i++;
  }
  if (i < m) {
    cnt[a[id][i]]++;
  }
}

void solve() {
  for (int i = 0; i < n; i++) {
    pos[i] = 0;
  }
  for (int i = 0; i < m; i++) {
    cnt[i] = 0;
    del[i] = false;
  }
  for (int i = 0; i < n; i++) {
    getNxt(i);
  }
  int res = inf;
  for (int it = 0; it < m; it++) {
    int todel = -1;
    for (int i = 0; i < m; i++) {
      if (del[i]) {
        continue;
      }
      if (todel == -1 || cnt[i] > cnt[todel]) {
        todel = i;
