void dfs(vector<queue<ll>> q, vector<ll> v, set<ll> s) {
    for(int i=0;i<v.size();i++) {
        //cout << " id : " << v[i]<< endl;
        vector<queue<ll>> qtmp = q;
        set<ll> stmp = s;
        stmp.insert(v[i]);
        if(stmp.size()==M) return;
        for(int j=0;j<N;j++) {
            while(stmp.find(qtmp[j].front())!=stmp.end()) {
                qtmp[j].pop();
            }
        }        
        vector<ll> btmp(M, 0);
        for(int j=0;j<N;j++) {
            btmp[qtmp[j].front()]++;
        }
        tmp = -1;
        vector<vector<ll>> ctmp(N+1);
        for(int j=0;j<M;j++) {
            tmp = max(tmp, btmp[j]);
            ctmp[btmp[j]].push_back(j);
        }
        ans = min(ans, tmp);   
        cout << ans << endl; 
        dfs(qtmp, ctmp[tmp], stmp);
    }
}

