bool check(vec<vec<int>> A, int x)
{
   while (true)
   {
      rep(i, 0, SZ(A)) {
         if (SZ(A[i]) == 0) return false;
      }

      map<int,int> m;
      rep(i, 0, SZ(A)) {
         m[A[i][0]]++;
      }
      set<int> s;
      EACH(i, m) {
         if (i->second > x) s.insert(i->first);
      }
      bool flag = true;
      rep(i, 0, SZ(A)) {
         rep(j, 0, SZ(A[i])) {
            if (EXIST(s, A[i][j])) {
               A[i].erase(A[i].begin() + j);
               flag = false;
            }
         }
      }
      if (flag) {
         return true;
      }
   }
}


int solve(vec<vec<int>>& A, int x)
{
   rep(i, 0, SZ(A)) {
      if (SZ(A[i]) == 0) return INF;
   }

   map<int,int> m;
   rep(i, 0, SZ(A)) {
      m[A[i][0]]++;
   }

   int MAX = -INF;
   EACH(i, m) {
      MAX = max(MAX, i->second);
   }
   int MIN = min(MAX, x);

   set<int> s;
   EACH(i, m) {
      if (i->second >= MIN) s.insert(i->first);
   }

   rep(i, 0, SZ(A)) {
      rep(j, 0, SZ(A[i])) {
         if (EXIST(s, A[i][j])) {
            A[i].erase(A[i].begin() + j);
         }
      }
   }

   return min(MIN, solve(A, MIN));
}

