INLINE bool isok(int n, int m, int x) {
  int remain = m;
  bool ok = true;

  for(int i = 0; i < n; ++i) {
    cursor[i] = 0;
    fr[matr[i][0]]++;
    if(fr[matr[i][0]] > x)
      ok = false;
  }

  for(int i = 0; i < m; ++i)
    deleted[i] = false;

  while(!ok && remain > 1) {
    --remain;
    int mustdelete = 0;
    for(int i = 0; i < m; ++i)
      if(fr[i] > x) //trebuie sters
        mustdelete = i;
    deleted[mustdelete] = true;
    ok = true;
    for(int i = 0; i < n; ++i) {
      --fr[matr[i][cursor[i]]];
      while(deleted[matr[i][cursor[i]]])
        ++cursor[i];
      fr[matr[i][cursor[i]]]++;
    }
    for(int i = 0; i < m; ++i)
      if(fr[i] > x)
        ok = false;
  }
  return ok;
}

