void solve(long long N, long long M, std::vector<std::vector<long long>> A) {
  rep(i, N) {
    rep(j, M) { A[i][j]--; }
  }

  vector<bool> checked(M);
  ll ans = INF;
  rep(i, M) {
    vector<int> sum(M);
    rep(j, N) {
      rep(k, M) {
        if (!checked[A[j][k]]) {
          sum[A[j][k]]++;
          break;
        }
      }
    }

    ll maxSum = 0;
    ll maxSumi = 0;
    rep(k, M) {
      if (sum[k] > maxSum) {
        maxSum = sum[k];
        maxSumi = k;
      }
    }

    if (ans > maxSum) {
      ans = maxSum;
    }

    checked[maxSumi] = true;
  }

  print(ans);
}

