bool rem(int game)
{
    played[game] = 0;
    for (auto i : is_in[game]) {
        int cnt(0);
        while (!played[a[i][cnt]] && cnt <= m)
            cnt++;
        if (cnt > m)
            return false;
        is_in[a[i][cnt]].push_back(i);
    }
    is_in[game].clear();
    return true;
}

