int solve(int n, int m, vector<vector<int>> &a){
    set<int> sports;
    int count[m];
    int min_ans = INF;
    int max_num;
    int max_itr;
    for (int i=0; i<n; ++i){
        sports.insert(i);
    }
    while(!sports.empty()){
        for (int i=0; i<m; ++i){
            count[i] = 0;
        }
        for (int i=0; i<n; ++i){
            for (int j=0; j<m; ++j){
                if(sports.find(a[i][j]) != sports.end()){
                    count[a[i][j]]++;
                    break;
                }
            }
        }
        max_num = -1;
        max_itr = -1;
        for (int i=0; i<m; ++i){
            if(max_num < count[i]){
                max_num = count[i];
                max_itr = i;
            }
        }
        min_ans = min(min_ans, max_num);
        sports.erase(max_itr);
    }
    return min_ans;
}

