bool can(int number){
    vector<int> sport[300];
    int rank[300];
    bool which[300];
    for(i = 0;i < m;i++){
        which[i] = true;
    }
    for(i = 0;i < n;i++){
        rank[i] = 0;
        sport[a[i][0]].push_back(i);
    }
    while(true){
        bool f = true;
        for(i = 0;i < m;i++){
            if(which[i] && sport[i].size() > number){
                which[i] = false;
                for(j = 0;j < sport[i].size();j++){
                    int target = sport[i][j];
                    for(int k = rank[sport[i][j]]+1;true;k++){
                        if(k == m) return false;
                        if(which[a[target][k]]){
                            sport[a[target][k]].push_back(target);
                            rank[target] = k;
                            break;
                        }
                    }
                }
                f = false;
            }
        }
        if(f) break;
    }
    return true;
}

