ll bisection(ll low, ll high, std::function<bool(ll)> check) {
	if (high - low == 1) return high;
	ll mid = (high + low) / 2;
	if (check(mid)) return bisection(low, mid, check);
	else            return bisection(mid, high, check);
}

signed main() {
	INIT;
	VAR(int, n, m);
	MAT(int, a, n, m);

	auto check = [&](int k) {
		std::vector<bool> unused(m, false);
		std::vector<std::set<int>> set(n);
		REP(i, n) REP(j, m) set[i].insert(j + 1);
		while (true) {
			if (set[0].empty()) return false;
			bool flag = false;
			REP(j, m) {
				if (unused[j]) continue;
				int cnt = 0;
				REP(i, n) {
					if (*set[i].rbegin() == a[i][j]) ++cnt;
				}
				if (cnt > k) {
					flag = true;
					REP(i, n) {
						set[i].erase(a[i][j]);
					}
					unused[j] = true;
				}
			}
			if (flag) continue;
			return true;
		}
	};

	OUT(bisection(0, n, check))BR;
	return 0;
}

