                z[tmp].push_back(i);
            }
            if (fin) {
                break;
            }
            int del = 0;
            for (i = 0; i < m; i++) {
                if (z[i].size() > mm) {
                    for (j = 0; j < (int)z[i].size(); j++) {
                        int id = z[i][j];
                        curr[id]++;
                    }
                    flag[i] = 1;
                    del = 1;
                }                
            }
            if (del == 0) {
                break;
            }
        }
        if (fin) {
            l = mm;
        }
        else {
            r = mm;
        }
    }
    printf("%d\n", r);



    return;
}


