pair<int, int> next_pop(vector<queue<int>>& qs) {
  vector<int> cnt(m + 1, 0);

  for (int i = 1; i <= n; ++i) {
    cnt[qs[i].front()] += 1;
  }

  int max_sport = 0;
  int max_times = -1;
  for (int i = 1; i <= m; ++i) {
    if (cnt[i] > max_times) {
      max_sport = i;
      max_times = cnt[i];
    }
  }

  return make_pair(max_sport, max_times);
}

void pop_one(vector<queue<int>>& qs) {
  for (int i = 1; i <= n; ++i) {
    while (!remain[qs[i].front()]) {
      qs[i].pop();
    }
  }
