const int MAX_N = 300;

int N, M;
int A[MAX_N][MAX_N];

struct Data {
  int type;
  int num;
};

int solve(vector< int > p)
{
  if (p.empty()) return N;
  int res = N;
  int tmpAns = 0;
  int maxNum;

  {
    map< int, int > m;
    REP(ni, N) {
      REP(mi, M) {
	if (binary_search(ALL(p), A[ni][mi])) {
	  m[A[ni][mi]]++;
	  break;
	}
      }
    }

    EACH(mi, m) {
      if (tmpAns < mi.second) {
	maxNum = mi.first;
	tmpAns = mi.second;
      } else if (tmpAns == mi.second) {
	vector< int > tmpP(p);
	tmpP[mi.first - 1] = tmpP.back();
	tmpP.pop_back();
	vector< int > tmpRaw(p);
	tmpRaw[maxNum - 1] = tmpRaw.back();
	tmpRaw.pop_back();
	if (solve(tmpP) < solve(tmpRaw)) {
	  maxNum = mi.first;
	  tmpAns = mi.second;
	}
      }
    }
    p[maxNum - 1] = p.back();
    p.pop_back();

    sort(ALL(p));
    // debug(tmpAns);
    res = min(res, tmpAns);

    if (!p.empty()) {
      res = min(solve(p), res);
    }
  }
  return res;
}

