            while (cancel[g[v][++idx[v]]]);
            sport[g[v][idx[v]]].emplace_back(v);
          }
          sport[j].clear();
          possible = false;
          break;
        }
      }
      if (possible) {
        ok = mid;
        break;
      }
      if (n > (m-i) * mid) break;
    }

    if (ok != mid) ng = mid;
  }

  cout << ok << endl;
}


