int N, M, A[303][303];

int main() {
    cin.tie(0); ios::sync_with_stdio(false);
    cin >> N >> M;
    for (int j = 0; j < N; ++j) {
        for (int k = 0; k < M; ++k) {
            cin >> A[j][k];
        }
    }

    char held[303];
    fill(held, held+M+1, true);
    queue<int> que[303];
    for (int j = 0; j < N; ++j) {
        for (int k = 0; k < M; ++k) {
            que[j].push(A[j][k]);
        }
    }

    int ans = N;

    int count[303];
    for (int n = 0; n < M; ++n) {
        fill(count, count+M+1, 0);
        for (int j = 0; j < N; ++j) {
            assert(!que[j].empty());
            while (!held[que[j].front()]) que[j].pop();
            ++count[que[j].front()];
        }
        int idx = -1;
        for (int j = 1; j <= M; ++j) {
            if (idx == -1 || count[idx] < count[j]) {
                idx = j;
            }
        }
        ans = min(ans, count[idx]);
        held[idx] = false;
    }
    cout << ans << endl;



    return 0;
}

