using namespace std;

int N, M;
int a[304][304];
int freq[304];
int eliminated[304];

int check(int maximSaFie) {
    int maximActual = 0;
    int elim = 0;
    memset(freq, 0, sizeof(freq));
    memset(eliminated, 0, sizeof(eliminated));
    for(int i = 1; i <= N; ++i) {
        freq[a[i][1]]++;
        maximActual = max(maximActual, freq[a[i][1]]);
        a[i][0] = 1;
    }

    while(maximActual > maximSaFie && elim < M) {
        int pos = 0;
        int maximDeElim = 0;
        for(int i = 1; i <= N; ++i) {
            if(maximDeElim < freq[a[i][a[i][0]]]) {
                maximDeElim = freq[a[i][a[i][0]]];
                pos = i;
            }
        }

        eliminated[a[pos][a[pos][0]]] = 1;
        ++elim;

        for(int i = 1; i <= N; ++i) {
            while(eliminated[a[i][a[i][0]]] == 1) {
                freq[a[i][a[i][0]]]--;
                ++a[i][0];
                freq[a[i][a[i][0]]]++;
            }
        }

        maximActual = 0;
        for(int i = 1; i <= M; ++i) {
            maximActual = max(maximActual, freq[i]);
        }
    }

    if(maximActual <= maximSaFie && elim < M) {
        return 1;
    }

    return 0;
}

int main() {
    cin >> N >> M;

    for(int i = 1; i <= N; ++i) {
        for(int j = 1; j <= M; ++j) {
            cin >> a[i][j];
        }
    }

    int in, sf;

    in = 1, sf = N;

    while(in < sf) {
        int mij = (in + sf) / 2;

        if(check(mij) == 1) {
            sf = mij;
        }
        else {
            in = mij + 1;
        }
    }

    cout << sf << '\n';

    return 0;
}

