const int MaxN = 300;
const int MaxM = 300;

int n, m;
int a[MaxN][MaxM];

int cur[MaxN];

bool valid[MaxM];
int occur[MaxM];

inline bool check(int lim)
{
	for (int i = 0; i < n; ++i)
		cur[i] = 0;
	for (int i = 0; i < m; ++i)
		valid[i] = true;

	while (true)
	{
		for (int i = 0; i < m; ++i)
			occur[i] = 0;

		bool ok = true;
		for (int i = 0; i < n; ++i)
		{
			int &k = cur[i];
			while (k < n && !valid[a[i][k]])
				++k;
			if (k == n)
				return false;

			if (++occur[a[i][k]] > lim)
			{
				valid[a[i][k]] = false;
				ok = false;
			}
		}

		if (ok)
			return true;
	}
}

int main()
{
	ios::sync_with_stdio(false);

	cin >> n >> m;
	for (int i = 0; i < n; ++i)
		for (int j = 0; j < m; ++j)
			cin >> a[i][j], --a[i][j];

	int l = 0, r = n;
	while (l <= r)
	{
		int mid = l + r >> 1;
		if (check(mid))
			r = mid - 1;
		else
			l = mid + 1;
	}

	cout << l << endl;

	return 0;
}

