    rep(n, N) rep(m, M) cin >> A[n][m];

    vector<int> ptr(N, 0);
    int ans = INF;
    set<int> erased;

    while (true) {
        PII t = max_sports(A, ptr);
        ans = min(ans, t.first);
        erased.insert(t.second);
        if (erased.size() == M) break;

        rep(i, N) {
            while (erased.count(A[i][ptr[i]])) {
                ptr[i]++;
            }
        }
    }

    cout << ans << endl;
}

