bool f(int m,vector< vector<int> > v)
{
	vector<int> cnt(M);
	deque<bool> erased(M);
	FOR(i,0,N) cnt [v [i].back()]++;
	while(true){
		int mx = -1,mxIdx = -1;
		FOR(i,0,M) if(chmax(mx,cnt [i])){
			mxIdx = i;
		}
		if(mx <= m) return true;
		erased [mxIdx] = true;
		FOR(i,0,N) if(erased [v [i].back()]){
			cnt [v [i].back()]--;
			while(v [i].empty() == false && erased [v [i].back()]){
				v [i].pop_back();
			}
			if(v [i].empty()) return false;
			cnt [v [i].back()]++;
		}
	}
}

