			cin >> Ais[i][j];
			Ais[i][j]--;
		}
	}
	ll lower = 0;
	ll upper = M;
	while (upper - lower >= 2) {
		ll half = (lower + upper) / 2;
		if (can_leq(half)) {
			upper = half;
		} else {
			lower = half;
		}
	}
	cout << upper << endl;
}

