void solve(){
	int N,M;
	cin >> N >> M;
	vector< vector<int> > fld(N,vector<int>(M));
	for(int i=0;i<N;++i){
		for(int j=0;j<M;++j){
			cin >> fld[i][j];
			fld[i][j]--;
		}
	}

	vector<bool> use(M,true);//選択しているかどうか
	vector<int> index(N,0);//現在の順位
	int ans = INF;
	for(int m=0;m<M;++m){//競技数分繰り返す。
		for(int i=0;i<N;++i){
			//選択されている競技までindexを進める。
			while( use[ fld[i][ index[i] ] ] == false ){
				index[i]++;
			}
		}

		int selMax = 0;
		int selMaxIndex = 0;
		vector<int> sel(M,0);//選ばれている数
		for(int i=0;i<N;++i){
			sel[ fld[i][ index[i] ] ]++;
			if( selMax < sel[ fld[i][ index[i] ] ] ){
				selMax = sel[ fld[i][ index[i] ] ];
				selMaxIndex = fld[i][ index[i] ];
			}
		}
		ans = min(ans,selMax);
		//selMaxIndexを除外する。
		use[ selMaxIndex ] = false;
	}
	cout << ans << endl;
}

