pair<ll, ll> f(map<ll, ll>& mp){
  ll ans = 0;
  ll max_sport_id = -1;
  for(auto pa : mp){
    ll count = pa.second;
    if(count > ans){
      ans = count;
      max_sport_id = pa.first;
    }
    chmax(ans, pa.second);
  }
  return make_pair(ans, max_sport_id);
}

