inline bool check(int md)
{
    for (int i = 1; i <= n; i++)
    {
        st[i].clear();
        p[i] = m;
        st[i] = sup[i];
    }

    bad.clear();

    for (int j = 1; j <= m; j++)
    {
        cnt[j] = cur[j],
        u[j] = 0;

        if ( cnt[j] > md )
            bad.pb(j),
            u[j] = 1;
    }

    int j;

    for (int l = 0; l < bad.size(); l++)
    {
        j = bad[l];

        cnt[j] = 0;

        for (int i = 1; i <= n; i++)
        {
            if (st[i].size() <= 1 )
                return false;

            int sz = st[i].size();

            st[i].erase( st[i].find( mk( ar[i][j], j ) ) );

            if ( ar[i][j] == p[i] )
            {
                p[i] = st[i].begin()->fr;

                cnt[ pos[i][ p[i] ] ]++;

                if (cnt[ pos[i][ p[i] ] ] > md && !u[ pos[i][ p[i] ] ] )
                {
                    bad.pb( pos[i][ p[i] ] );
                    u[ pos[i][ p[i] ] ] = 1;
                }
            }
        }
    }
    sum = 0;
    for (int j = 1; j <= m; j++)
        sum += cnt[j];

    return sum == n;
}

