                if(use[A[i][j]-1]) {
                    num[A[i][j]-1]++;
                    break;
                }
            }
        }
        int mx=(*max_element(ALL(num)));
        int ret=mx;
        REP(i,M) {
            if(num[i]==mx) {
                use[i]=false;
                chmin(ret,rec());
            }
        }
        return ret;
    };
    cout<<rec()<<endl;
    return 0;
}

