int solve(int N, int M, vector<vector<int>> A)
{
    auto check = [&](int k)
    {
        vector<int> V(M, true);

        for (int r=0; r<M-1; r++)
        {
            vector<int> C(M, 0);

            for (int i=0; i<N; i++)
                for (int j=0; j<M; j++)
                    if (V[A[i][j]])
                    {
                        C[A[i][j]]++;
                        break;
                    }

            int m = *max_element(C.begin(), C.end());
            if (m <= k)
                return true;

            for (int j=0; j<M; j++)
                if (C[j] == m)
                {
                    V[j] = false;
                    break;
                }
        }
        return false;
    };

    int ans = 512;
    for (int b=256; b>0; b/=2)
        if (check(ans-b))
            ans -= b;
    return ans;
}

int naive(int N, int M, vector<vector<int>> A)
{
    int ans = M;

    for (int b=1; b<(1<<M); b++)
    {
        vector<int> C(M);
        for (int i=0; i<N; i++)
            for (int j=0; j<M; j++)
            if (b>>A[i][j]&1)
            {
                C[A[i][j]]++;
                break;
            }
        ans = min(ans, *max_element(C.begin(), C.end()));
    }
    return ans;
}

