#define REP(i,n) for (ll i = 0; i < n; i++)
template <class T> using reversed_priority_queue = priority_queue<T, vector<T>, greater<T> >;
typedef long long ll;

int N,M;
int A[300][300];
bool enable[300];
int cnt[300];
int idx;
int max_v;
bool flag;

int get_popular ()
{
    flag = false;
    fill (cnt, cnt + 300, 0);
    int sum = 0;
    REP(i,N) {
        REP(j,M) {
            if (enable[A[i][j]]) {
                cnt[A[i][j]]++;
                sum++;
                goto nxt;
            }
        }
        nxt:;
    }
    idx = -1;
    max_v = -1;
    REP(i,M) {
        if (max_v < cnt[i]) {
            max_v = cnt[i];
            idx = i;
        }
    }
    if (sum == N) {
        flag = true;
    }
    return idx;
}

int main ()
{
    cin >> N >> M;
    REP(i,N)REP(j,M) cin >> A[i][j];
    REP(i,N)REP(j,M) A[i][j]--;
    fill (enable, enable + 300, true);

    int idx = get_popular();
    int ans = max_v;
    REP(i,M) {
        enable[idx] = false;
        idx = get_popular();
        if (!flag) {
            break;
        } else {
            ans = min(ans, max_v);
        }
    }

    cout << ans << endl;

    return 0;
}

