const int N = 305;

int n, m, a[N][N];
int act[N], tot[N];

bool OK(int can){
	memset(tot, 0, sizeof(tot));
	memset(act, 0, sizeof(act));
	for(int i = 1; i <= m; ++i) act[i] = 1;
	for(int i = 1; i <= n; ++i) tot[a[i][1]]++;
	int cnt = m;
	while(cnt > 0){
		bool ok = true;
		for(int i = 1; i <= m; ++i){
			if(act[i] == 0) continue;
			if(tot[i] > can){
				ok = false;
				act[i] = 0;
				cnt -= 1;
			}
		}
		if(ok == true) return true;
		memset(tot, 0, sizeof(tot));
		for(int i = 1; i <= n; ++i){
			for(int j = 1; j <= m; ++j){
				if(act[a[i][j]]){
					++tot[a[i][j]];
					break;
				}
			}
		}
	}
	return false;
}

int main(){
	scanf("%d %d", &n, &m);
	for(int i = 1; i <= n; ++i){
		for(int j = 1; j <= m; ++j){
			scanf("%d", &a[i][j]);
		}
	}
	int lo = 1, hi = m, ans = m;
	while(lo <= hi){
		int mid = (lo + hi) / 2;
		if(OK(mid)) ans = mid, hi = mid - 1;
		else lo = mid + 1;
	}
	printf("%d\n", ans);
	return 0;
}

