template<typename T>
class Counter {
 private:
  unordered_map<T, ll> counts;

  static bool compare(const pair<T, ll> &a, const pair<T, ll> &b) {
    if (a.second != b.second) {
      return a.second > b.second;
    } else {
      return a.first < b.first;
    }
  }

 public:
  explicit Counter(vector<T> &values) {
    for (auto &&v: values) {
      if (counts.count(v)) {
        counts[v]++;
      } else {
        counts[v] = 1;
      }
    }
  }

  unordered_map<T, ll> values() {
    return counts;
  }

  vector<pair<T, ll>> most_common() {
    vector<pair<T, ll>> ret;
    for (auto &&item: counts) {
      ret.emplace_back(item.first, item.second);
    }
    sort(ret.begin(), ret.end(), compare);
    return ret;
  }
};

