bool ok(int x){
	int cnt[310] = {};
	int in[310] = {};
	bool unuse[310] = {};
	int max_c = 0, max_in = 0;
	int max_c_n = 0;
	REP(i, N){
		cnt[A[i][0]]++;
		if(max_c < cnt[A[i][0]]++){
			max_c = cnt[A[i][0]];
			max_c_n = A[i][0];
		}
	}

	int a = 0;
	while(max_c > x && max_in < M){
		unuse[max_c_n] = true;
		REP(i, N){
			while(in[i] < M && unuse[A[i][in[i]]]){
				cnt[A[i][in[i]]]--;
				in[i]++;
				if(in[i] < M)
					cnt[A[i][in[i]]]++;
			}
		}
		max_c = 0;
		REP(j, M){
			if(max_c < cnt[j] && !unuse[j]){
				max_c = cnt[j];
				max_c_n = j;
			}
		}
		REP(j, N){
			max_in = max(max_in, in[j]);
		}
	}
	int c = 0;
	REP(i, M){
		c += unuse[i];
	}
	return max_in < M && c < M;
}

