int N, M, arr[305][305];
int solve() {
	vector<vector<pair<int, int> > >person; // <참여도 경기번호>
	for (register int i = 0; i < N; ++i) {
		person.push_back(vector<pair<int, int> >());
		for (register int j = 0; j < M; ++j) {
			person[i].push_back(make_pair(arr[i][j], j));
		}
	}
	//개인당 참여도 순으로 정렬시킨다.
	for (register int i = 0; i < N; ++i) {
		sort(range(person[i]), [](pair<int, int>&lv, pair<int, int>&rv) {
			return lv.first > rv.first;
		});
	}

	vector<int> participants(M, 0);
	vector<int> NoSport;
	int ret = 305;
	int c = M-1;
	while (c--) {
		//경기를 시작한다.
		for (register int i = 0; i < N; ++i) {
			for (register int j = 0; j < M; ++j) {
				if (!binary_search(range(NoSport), person[i][j].second)) {
					participants[person[i][j].second]++;
					break;
				}
			}
		}
		//가장많이 참여한 경기를 지우고 다시 시작한다.
		int s = 0, t = 0;
		for (register int i = 0; i < M; ++i) {
			if (t < participants[i]) {
				t = participants[i];
				s = i;
			}
		}
		if (ret > t) {
			ret = t;
			NoSport.push_back(s);
		}
		else {
			break;
		}
	}
	return ret;
}
int main() {
	scanf("%d%d", &N, &M);
	for (register int i = 0; i < N; ++i) {
		for (register int j = 0; j < M; ++j) {
			scanf("%d", &arr[i][j]);
		}
	}
	printf("%d", solve());
}

