bool check(const vector<vector<int>>& A, int maxNum){
	const int N = A.size();
	const int M = A[0].size();
	vector<int> hold(M, 1);
	vector<int> idx(N, 0);
	vector<int> part(M, 0);
	for(int i=0;i<N;i++) part[A[i][0]]++;
	while(true){
		bool update = false;
		for(int i=0;i<M;i++){
			if(part[i] > maxNum){
				hold[i] = 0;
				for(int j=0;j<N;j++){
					if(A[j][idx[j]] != i) continue;
					--part[i];
					while(idx[j] < A[j].size() && !hold[A[j][idx[j]]]) ++idx[j];
					if(idx[j] == A[j].size()) return false;
					part[A[j][idx[j]]]++;
				}
				update = true;
			}
		}
		if(!update) break;
	}
	return true;
}

