   Solver() { fprintf(stderr, "--------Solver begin--------\n"); }
   ~Solver() { fprintf(stderr, "--------Solver end--------\n"); }
   long gcd(long x, long y) {
      if( y == 0 ) return x;
      return gcd(y, x%y);
   }
   long table[333][333];
   void solve() {
      long n, m; scan(n, m);
      for(long i = 0; i < n; ++i) {
         for(long k = 0; k < m; ++k) {
            scan(table[i][k]);
         }
