         for(long i = 0; i < n; ++i) {
            for(long k = 0; k < m; ++k) {
               if( table[i][k] == t ) break;
               count[table[i][k]] += 1;
            }
         }
         LI pass(m+1, 0);
         for(long i = 1; i <= m; ++i) {
            if( count[i] <= n / 2 ) pass[i] = 1;
