  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      cin >> orders[i][j];
      orders[i][j]--;
    }
  }

  vector<int> indexes(n, 0);
  vector<int> removed(m, 0);
  int ans = INT32_MAX;
  for (int k = 0; k < m; k++) {
    vector<int> counter(m);
    int max_value = -1;
    int max_arg = -1;
    for (int i = 0; i < n; i++) {
      int type = orders[i][indexes[i]];
      counter[type]++;
      if (UpdateMax(max_value, counter[type])) {
        max_arg = type;
      }
    }

    UpdateMin(ans, max_value);

    removed[max_arg] = 1;

    if (k == m - 1) break;

    for (int i = 0; i < n; i++) {
      while(removed[orders[i][indexes[i]]]) indexes[i]++;
    }
  }
  cout << ans << endl;
}

