const int N = 1234;

int a[N][N];
bool alive[N];
int cnt[N], ptr[N];

int main() {
  int n, m;
  scanf("%d %d", &n, &m);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      scanf("%d", a[i] + j);
      a[i][j]--;
    }
  }
  int low = 1, high = n;
  while (low < high) {
    int mid = (low + high) >> 1;
    for (int i = 0; i < m; i++) {
      alive[i] = true;
      cnt[i] = 0;
    }
    for (int i = 0; i < n; i++) {
      cnt[a[i][0]]++;
      ptr[i] = 0;
    }
    bool found = false;
    for (int it = 0; it < m; it++) {
      int id = -1;
      for (int j = 0; j < m; j++) {
        if (cnt[j] > mid) {
          id = j;
          break;
        }
      }
      if (id == -1) {
        found = true;
        break;
      }
      if (it == m - 1) {
        break;
      }
      alive[id] = false;
      for (int i = 0; i < n; i++) {
        cnt[a[i][ptr[i]]]--;
        while (!alive[a[i][ptr[i]]]) {
          ptr[i]++;
        }
        cnt[a[i][ptr[i]]]++;
      }
    }
    if (!found) {
      low = mid + 1;
    } else {
      high = mid;
    }
  }
  printf("%d\n", low);
  return 0;
}

