bool check(int x, int N, int M) {
     memset(gone, 0, sizeof(gone));
     for (int i = 0; i < N; i++) {
         for (int j = 0; j < M; j++)
             ta[i][j] = a[i][j];
     }
     //m = biggest
     for (int m = M; m >= 1; m--) {
         memset(cnt, 0, sizeof(cnt));
         for (int i = 0; i < M; i++) {
             if (gone[i]) continue;
             for (int j = 0; j < N; j++) {
                 if (ta[j][i] == m) cnt[i]++;
             }
         }
         bool upd = false;
         int tg;
         for (tg = 0; tg < M; tg++) {
             if (gone[tg]) continue;
             if (cnt[tg] > x) {
                gone[tg] = 1;
                upd = true;
                break;
             }
         }
         if (!upd) return true;
         for (int i = 0; i < N; i++) {
             for (int j = 0; j < M; j++) {
                 if (gone[j]) continue;
                 if (ta[i][j] > ta[i][tg]) ta[i][j]--;
             }
         }
     }
     return false;
}

