    for ( int n = 0; n < N; n++ ) {
        for ( int m = 0; m < M; m++ ) {
            cin >> A[n][m];
        }
    }

    auto check = [&](ll k) {
        vector<int> ix(N);
        vector<int> ng(M+1), num(M+1);
        for ( int n = 0; n < N; n++ ) {
            num[A[n][0]]++;
        }
        for(;;) {
            vector<int> nm;
            for ( int m = 1; m <= M; m++ ) {
                if ( num[m] > k ) nm.push_back(m);
            }
            if ( nm.empty() ) return true;
            for ( int m : nm ) {
                ng[m]++;
            }
            for ( int n = 0; n < N; n++ ) {
                for ( int m : nm  ) {
                    if ( A[n][ix[n]] == m ) {
                        num[A[n][ix[n]]]--;
                        while ( ng[A[n][ix[n]]] > 0 ) {
                            ix[n]++;
                            if ( ix[n] >= M ) return false;
                        } 
                        num[A[n][ix[n]]]++;
                        break;
                    }
                }
            }
        }
        return false;
    };

    ll l = 0, r = N;
    while ( r - l > 1 ) {
        ll m = (l+r)/2;
        if ( check(m) ) r = m;
        l = m;
    }
    return r;
}

