int n,m,i,j,k,l,r,mid,ans,num[305][305],now[305][305],mx[305];
bool check(int x)
{
	if (x<1) return 0;
	if (x>n) return 1;
	int i,j,k,s;
	vector<int> no;
	for (i=1;i<=n;i++)
	{
		for (j=1;j<=m;j++)
		{
			now[i][j]=1;
		}
		mx[i]=m;
	}		
	for (i=m;i;i--)
	{
		no.clear();
		for (j=1;j<=m;j++)
		{
			s=0;
			for (k=1;k<=n;k++)
			{
				if (mx[k]==num[k][j])
				{
					s++;
				}
			}
			if (s>x) no.push_back(j);
		}
		for (j=0;j<no.size();j++)
		{
			for (k=1;k<=n;k++)
			{
				now[k][num[k][no[j]]]=0;
			}
		}
		for (j=1;j<=n;j++)
		{
			for (k=m;k;k--)
			{
				if (now[j][k]) break;
			}
			mx[j]=k;
		}
	}
	for (i=1;i<=n;i++) if (mx[i]<=0) return 0;
	return 1;
}
int main()
{
	cin>>n>>m;
	for (i=1;i<=n;i++)
	{
		for (j=1;j<=m;j++)
		{
			cin>>num[i][j];
		}
	}
	l=0;r=n+1;ans=n;
	while (l<r)
	{
		mid=(l+r+1)/2;
		if (check(mid))
		{
			ans=mid;
			r=mid-1;
		}
		else l=mid;
	}
	cout<<ans;
	return 0;
}

