ll C[305];
bool U[305];

bool solve(ll n)
{
    memset(B, 0, sizeof(B));
    memset(U, 0, sizeof(U));
    while (true)
    {
        memset(C, 0, sizeof(C));
        REP(i, N)
        {
            C[A[i][B[i]]]++;
        }
        bool e = true;
        REP(i, M)
        {
            if (C[i] > n || (C[i] > 0 && U[i]))
            {
                U[i] = true;
                e = false;
            }
        }
        if (e)
            return true;
        bool f = true;
        REP(i, N)
        {
            while (U[A[i][B[i]]] && B[i] < M)
                B[i]++;
            if (B[i] >= M)
                f = false;
        }
        if (!f)
            break;
    }
    return false;
}

