int n, m;
std::vector< std::vector<short> > table;

int calc() {
  if(m == 1)
    return 1;

  std::vector<bool> rm(m, false);
  int min = 1000;
  for(int i = 0; i < m - 1; i++) {
    std::vector<short> ranks(m, 0);
    for(int j = 0; j < n; j++) {
      int x = 0;
      while(rm[table[j][x]])
        x++;
      int best = table[j][x];
      ranks[best]++;
    }
    int max_ranked = -1;
    int max_ind = -1;
    for(int k = 0; k < m; k++) {
      if(rm[k])
        continue;
      if(max_ranked < ranks[k]) {
        max_ranked = ranks[k];
        max_ind = k;
      }
    }
    min = max_ranked < min ? max_ranked : min;
    rm[max_ind] = true;
  }

  return min;
}

int main() {
  std::cin >> n;
  std::cin >> m;
  table.resize(n);
  for(int i = 0; i < n; i++) {
    table[i].resize(m);
    for(int j = 0; j < m; j++) {
      int x;
      std::cin >> x;
      table[i][j] = x - 1;
    }
  }
  std::cout << calc() << "\n";
}

