ll N, M;
bool out[301];

ll solve(int remain, vector<vector<long long>> &A) {
  ll ret = 0;
  if (!remain)
    return 10000;

  ll L[M] = {};
  int index = 0;
  REP(n, N) REP(m, M) if (!out[A[n][m]]) {
    L[A[n][m]]++;

    if (ret < L[A[n][m]]) {
      ret = max(ret, L[A[n][m]]);
      index = A[n][m];
    }
    break;
  }

  out[index] = true;
  return min(ret, solve(remain - 1, A));
}

