bool check(int lim) {
    for(int i=1; i<=m; i++)not_choose[i]=false;
    for(int i=1; i<=n; i++)ptr[i]=1;
    while(1) {
        for(int i=1; i<=m; i++)cnt[i]=0;
        for(int i=1; i<=n; i++) {
            while(ptr[i]<=m&&not_choose[a[i][ptr[i]]])ptr[i]++;
            if(ptr[i]>m)return false;
            cnt[a[i][ptr[i]]]++;
        }
        bool sign=0;
        for(int i=1; i<=m; i++)if(cnt[i]>lim) {
                sign=1;
                break;
            }
        if(!sign)return true;
        for(int i=1; i<=n; i++)if(cnt[a[i][ptr[i]]]>lim) {
                not_choose[a[i][ptr[i]]]=true;
                ptr[i]++;
            }
    }
    return false;
}

