void change(int j,int x)
{
	pp[j]=1;
	for (int k=0;k<tmp[j].size();k++)
	{
		int d=tmp[j][k];
		if (np[tmp[j][k]]!=j) continue;
		np[tmp[j][k]]=0;
		for (int l=1;l<=m;l++)
			if (!pp[a[d][l]])
