const int N=500;
int A[N][N];
bool E[N];
int I[N];
int C[N];

int main(){
  ios::sync_with_stdio(0); cin.tie(0);
  int n,m; cin>>n>>m;
  FOR(i,n) FOR(j,m) {
    cin>>A[i][j]; --A[i][j];
  }
  FOR(i,N) I[i]=0;
  FOR(i,N) E[i]=1;

  int best = n;
  FOR(j_,m) {
    FOR(i,m) C[i]=0;
    FOR(i,n) {
      while(!E[A[i][I[i]]]) { I[i] += 1; }
      C[A[i][I[i]]] += 1;
    }
    int bix=-1, bcnt=-1;
    FOR(i,m) if(C[i]>bcnt) { bix=i; bcnt = C[i]; }
    best=min(best,bcnt);
    E[bix]=0;
  }
  cout << best << endl;

  return 0;
}

