void Main()
{
	int N, M;
	std::cin >> N >> M;
	std::vector<std::vector<int>> likes(N, std::vector<int>(M));
	for (auto& vec : likes)
	{
		for (auto& v : vec)
		{
			std::cin >> v;
			--v;
		}
	}
	std::vector<int> top(N, 0);
	int min = std::numeric_limits<int>::max();
	std::set<int> removed;
	std::vector<int> tops;
	for (int i = 1; i < M; ++i)
	{
		tops.clear();
		tops.resize(M, 0);
		for (int j = 0; j < N; ++j)
		{
			++tops[likes[j][top[j]]];
		}
		auto t = std::max_element(tops.begin(), tops.end());
		removed.emplace(t - tops.begin());
		min = std::min(*t, min);
		for (int j = 0; j < N; ++j)
		{
			while (removed.count(likes[j][top[j]]))
			{
				++top[j];
			}
		}
	}
	std::cout << min << std::endl;
}

