void update(int id, priority_queue<ii> &pq) {
  set<int> mudou;
  for(int i = 1; i <= n; i++) {
    for(int j = 1; j <= m; j++) {
      if(tala[a[i][j]] and a[i][j] != id) break;
      if(tala[a[i][j]]) {
        for(int k = j + 1; k <= m; k++) {
          if(tala[a[i][k]]) {
            qte[a[i][k]]++;
            mudou.insert(a[i][k]);
            break;
          }
        }
        break;
      }
    }
  }
  tala[id] = false;
  for(int v : mudou) pq.push(mp(qte[v], v));
}

int main() {
  sc2(n, m);
  memset(tala, true, sizeof(tala));
  for(int i = 1; i <= n; i++) {
    for(int j = 1; j <= m; j++) {
      sc(a[i][j]);
    }
    qte[a[i][1]]++;
  }
  priority_queue<ii> pq;
  int maior = 0;
  for(int i = 1; i <= m; i++) {
    if(qte[i] > qte[maior]) maior = i;
  }
  pq.push(mp(qte[maior], maior));
  int resp = qte[maior];
  while(!pq.empty()) {
    ii p = pq.top();
    pq.pop();
    int id = p.second;
    int qt = p.first;
    if(qt != qte[id]) continue;
    resp = min(resp, qt);
    update(id, pq);
  }
  pri(resp);
  return 0;
}

