bool calc(int x, vector<queue<int>>dt) {
	vector<bool>flag(m, false);
	while (true){
		vector<int>count(m, 0);
		for (int i = 0; i < n; i++) {
			if (dt[i].empty())return false;
			count[dt[i].front() - 1]++;
		}
		int l = -1;
		for (int i = 0; i < m; i++) {
			if (count[i] > x) {
				l = i;
				break;
			}
		}
		if (l < 0)break;
		flag[l] = true;
		for (int i = 0; i < n; i++) {
			while (flag[dt[i].front() - 1]) {
				dt[i].pop();
				if (dt[i].empty())return false;
			}
		}
	}
	return true;
}

