#include <ios>
#include <iostream>
#include <vector>

std::vector<int> tak[305] = {};
int arr[305][305] = {};
bool rej[305] = {}; //rejected
bool has[305] = {};
int pos[305] = {};
int n, m;

bool can(int k)
{
    for (int i = 0; i < n; i++)
    {
        has[i] = false;
        pos[i] = 0;
    }
    for (int i = 0; i < m; i++)
    {
        rej[i] = false;
        tak[i].clear();
    }
    bool found = false;
    bool ok = true;
    while (!found && ok)
    {
        found = true;
        for (int i = 0; i < n && ok; i++)
        {
            if (!has[i])
            {
                found = false;
                while (rej[arr[i][pos[i]]])
                {
                    pos[i]++;
                    if (pos[i] >= m)
                        return false;
                }
                has[i] = true;
                tak[arr[i][pos[i]]].push_back(i);
                if (tak[arr[i][pos[i]]].size() > k)
                {
                    int gy = arr[i][pos[i]];
                    for (std::vector<int>::iterator it = tak[gy].begin(); it != tak[gy].end(); it++)
                    {
                        pos[*it]++;
                        has[*it] = false;
                        if (pos[*it] >= m)
                            return false;
                    }
                    tak[arr[i][pos[i]-1]].clear();
                    rej[arr[i][pos[i]-1]] = true;
                }
            }
        }
    }
    return found;
}

int main()
{
    //std::ios_base::sync_with_stdio(false);
    //std::cin.tie(NULL);
    //std::cout.tie(NULL);
    std::cin >> n >> m;
    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < m; j++)
        {
            std::cin >> arr[i][j];
            arr[i][j]--;
        }
    }
    int lo = 1;
    int hi = n;
    int ans = -1;
    while (lo <= hi)
    {
        int mid = (lo+hi)/2;
        if (can(mid))
        {
            hi = mid-1;
            ans = mid;
        }
        else
            lo = mid+1;
    }
    std::cout << ans << '\n';
}

