using namespace std;

int main(int argc, char const *argv[]) {
	int N,M;
	std::cin >> N >> M;
	int a[N][M];
	// 各スポーツの人数
	int s[M];
	// 各スポーツが開催されるか
	bool flag[M];
	// 初期化
	for (size_t i = 0; i < M; i++) {
		flag[i] = true;
	}
	// 行列の入力
	for (size_t i = 0; i < N; i++) {
		for (size_t j = 0; j < M; j++) {
			std::cin >> a[i][j];
			a[i][j]--;
		}
	}

	int mmax = 10000;
	int submax = 0;
	int sport;
	// スポーツを一つづつ閉鎖していく
	for (size_t i = 0; i < M; i++) {
		//初期化
		for (size_t j = 0; j < M; j++) {
			s[j] = 0;
		}
		// 各スポーツに参加する人数を数える
		for (size_t j = 0; j < N; j++) {
			for (size_t k = 0; k < M; k++) {
				if (flag[a[j][k]]) {
					s[a[j][k]]++;
					break;
				}
			}
		}

		submax = 0;
		// 最も人数の多いスポーツを探索
		for (size_t j = 0; j < M; j++) {
			if (submax < s[j]) {
				submax = s[j];
				sport = j;
			}
		}
		// 人数の少ない方を選ぶ
		mmax = min(mmax,submax);
		// 最も人数の多かったスポーツを閉鎖
		flag[sport] = false;
	}

	std::cout << mmax << '\n';
	return 0;
}

