signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int N, M; cin >> N >> M;
	vector<vector<int>> A(N, vector<int>(M));
	rep(i, 0, N) rep(j, 0, M) { cin >> A[i][j]; A[i][j]--; }

	int ans = INF;

	function<void(vector<bool>, int)> dfs = [&](vector<bool> used, int t) {
		dump(used, t);
		if (t != 0) {
			vector<int> num(M);
			rep(i, 0, N)rep(j, 0, M) {
				if (used[A[i][j]]) {
					num[A[i][j]]++;
					break;
				}
			}
			dump(num);
			chmin(ans, *max_element(all(num)));
		}
		if (t == M)return;

		vector<vector<int>> B(M, vector<int>(M));
		rep(i, 0, N)rep(j, 0, M) {
			if (used[A[i][j]])break;
			B[A[i][j]][j]++;
		}
		rep(i, 0, M)rep(j, 0, M - 1) {
			B[i][j + 1] += B[i][j];
		}
		dump(B);
		vector<int> mini(M, INF);
		int midx = -1;
		rep(i, 0, M) {
			if (used[i])continue;
			bool changed = false;
			rep(j, 0, M) {
				if (mini[j] > B[i][j]) {
					midx = i;
					changed = true;
					break;
				}
				else if (mini[j] < B[i][j])
					break;
			}
			if (!changed)continue;
			rep(j, 0, M) {
				mini[j] = B[i][j];
			}
		}

		rep(i, 0, M) {
			if (used[i])continue;
			bool same = true;
			rep(j, 0, M) {
				if (mini[j] != B[i][j])
					same = false;
			}
			if (same) {
				used[i] = true;
				dfs(used, t + 1);
				used[i] = false;
			}
		}
	};
	dfs(vector<bool>(M), 0);
	cout << ans << endl;

	return 0;
}

