using namespace std;
int main()
{
	int N, M;
	cin >> N >> M;
	int** arr = new int*[N];
	for (int i = 0; i < N; i++)
	{
		arr[i] = new int[M];
		for (int j = 0; j < M; j++)
		{
			int tmp;
			cin >> tmp;
			arr[i][j] = tmp;
		}
	}
	//init point
	int* point = new int[N];
	bool* deleted = new bool[N];
	for (int i = 0; i < N; i++)
	{
		point[i] = 0;
		deleted[i] = true;
	}
	//compute
	int min_people = 0x0fffffff;
	for (int i = 0; i < M; i++)
	{
		vector<int> people(M, 0);
		int max_people = -1;
		int max_event = -1;
		for (int j = 0; j < N; j++)
		{
			while (!deleted[arr[j][point[j]]-1])
				point[j]++;
			if (max_people < ++people[arr[j][point[j]] - 1])
			{
				max_people = people[arr[j][point[j]] - 1];
				max_event = arr[j][point[j]] - 1;
			}
		}
		min_people = min(min_people, max_people);
		deleted[max_event] = false;
	}
	cout << min_people << endl;
}

