int main(){
    int h,w;
    cin>>h>>w;
    assert(h<=300 && w<=300);
    vector<vector<int>> v(h,vector<int>(w));
    rep(i,h)rep(j,w)cin>>v[i][j];
    rep(i,h)rep(j,w)v[i][j]--;

    priority_queue<pii,vector<pii>,greater<pii>> pq[400];
    rep(i,h){
        rep(j,w){
            pq[i].push(pii(j,v[i][j]));
        }
    }

    int less = w;
    vector<bool> used(400,false);

    int ans = h;
    while(less){
        vector<int> score(400,0);
        rep(i,h){
            while( pq[i].size() && used[ pq[i].top().second ]==true )pq[i].pop();
            assert( used[ pq[i].top().second ] == false );
            score[pq[i].top().second]++;
        }
        int res = *max_element(all(score));
        ans = min(ans, res);
        rep(j,w){
            if(score[j]==res){
                assert(used[j]==false);
                used[j] = true;
                less--;
            }
        }
    }
    cout<<ans<<endl;
}

