            int s;
            cin>>s;
            poscnt[s][j]++;
            personpref[i][s]=j;
            firstpos[s]=min(firstpos[s],j);
        }
    }
    FREP(i,1,m){
        int diff = 0;
        FREP(j,1,m){
            if(poscnt[i][j]){
                diff++;
            }
        }
        difpos[i]=make_pair(make_pair(-diff,-firstpos[i]),i);
    }
    sort(difpos+1,difpos+1+m);
    cout<<realsolve(n,m)<<"\n";
    return 0;
}

