std::vector<int> tak[305] = {};
int arr[305][305] = {};
bool rej[305] = {}; //rejected
bool has[305] = {};
int n, m;

bool can(int k)
{
    for (int i = 0; i < n; i++)
        has[i] = false;
    for (int i = 0; i < m; i++)
    {
        rej[i] = false;
        tak[i].clear();
    }
    for (int j = 0; j < m; j++)
    {
        for (int i = 0; i < n; i++)
        {
            if (!has[i] && !rej[arr[i][j]])
            {
                has[i] = true;
                tak[arr[i][j]].push_back(i);
                if (tak[arr[i][j]].size() > k)
                {
                    for (std::vector<int>::iterator it = tak[arr[i][j]].begin(); it != tak[arr[i][j]].end(); it++)
                        has[*it] = false;
                    tak[arr[i][j]].clear();
                    rej[arr[i][j]] = true;
                }
            }
        }
    }
    for (int i = 0; i < n; i++)
    {
        if (!has[i])
            return false;
    }
    return true;
}

int main()
{
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    std::cout.tie(NULL);
    std::cin >> n >> m;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            std::cin >> arr[i][j];
    int lo = 1;
    int hi = n;
    int ans = -1;
    while (lo <= hi)
    {
        int mid = (lo+hi)/2;
        if (can(mid))
        {
            hi = mid-1;
            ans = mid;
        }
        else
            lo = mid+1;
    }
    std::cout << ans << '\n';
}

