void check(int n, int m, int banned[], int a[][m], int* maxPop, int* maxGame){
	int num[m];
	for(int i = 0; i < m; i++){
		num[i] = 0;
	}
	for(int i = 0; i < n; i++){
		int b = play(m, a[i], banned);
		num[b]++;
	}
	*maxPop = 0;
	*maxGame = -1;
	for(int i = 0; i < m; i++){
		if(num[i] > *maxPop){
			*maxPop = num[i];
			*maxGame = i;
		}
	}
	return;
}

