#define ABS(a) ((a)>(0)?(a):-(a))

#define POS(i,j) ((i)*m+(j))

int calcMax(int *a,int *b,int n,int m,int *maxRef){
  int cnt[301];
  int i;
  for(i=0;i<=m;i++) cnt[i]=0;
  for(i=0;i<n;i++){
    cnt[a[POS(i,b[i])]]++;
  }
  int max=0;
  int maxIndex=0;
  for(i=1;i<=m;i++){
    if(max<cnt[i]){
      max=cnt[i];
      maxIndex=i;
    }
  }
  *maxRef=max;
  return maxIndex;
}

