  for(i=0;i<n;i++){
    for(j=0;j<m;j++){
      scanf("%d",a+POS(i,j));
    }
  }
  int assign[300];
  for(i=0;i<n;i++) assign[i]=0;
  int can[300];
  for(i=1;i<=m;i++) can[i]=1;
  int min=n;
