fun PrintWriter.solve(sc: FastScanner) {
    val n = sc.nextInt()
    val m = sc.nextInt()
    val a = Array(n) { Array(m) { 0 } }
    for (i in 0 until n) {
        for (j in 0 until m) {
            a[i][j] = sc.nextInt() - 1
        }
    }
    println(dfs(a, Array(n) { 0 }, 0))
}

fun dfs(a: Array<Array<Int>>, p:Array<Int>, i: Int): Int {
    val n = a.count()
    val m = a[0].count()
    if (i == n) {
        val set = mutableSetOf<Int>()
        val count = mutableMapOf<Int, Int>()
        for (j in 0 until n) {
            count[a[j][p[j]]] = (count[a[j][p[j]]] ?: 0) + 1
            set.add(a[j][p[j]])
        }
        for (j in 0 until n) {
            for (k in 0 until p[j]) {
                if (set.contains(a[j][k])) {
                    return Int.MAX_VALUE
                }
            }
        }
        return count.values.max()!!
    }
    var min = Int.MAX_VALUE
    for (j in 0 until m) {
        p[i] = a[i][j]
        min = Math.min(min, dfs(a, p, i + 1))
        var ok = true
        for (k in 0 until i) {
            if (a[i][j] == a[k][p[k]]) {
                ok = false
                break
            }
        }
        if (!ok) {
            p[i] = 0
            break
        }
    }
    return min
}

