fun main(args: Array<String>) {
    val (N, M) = readLine()!!.split(" ").map{it.toInt()}

    val A = Array(N) { readLine()!!.split(" ").map{it.toInt()}}

    var l = 0
    var u = N

    while (u - l > 1) {
        val c = (l + u) / 2

        if (judge(c, A, N, M)) {
            u = c
        } else {
            l = c
        }
    }

    println(u)
}

fun judge(c: Int, A: Array<List<Int>>, N: Int, M: Int): Boolean {
    for (u in 1..M) {
        val used = (1..M).filter { idx ->
            A.filter { row -> row.indexOf(idx) < row.indexOf(u) }.count() <= c
        }.map {
            val res = ArrayList<Int>()
            for (i in A.indices) {
                if (A[i].indexOf(it) < A[i].indexOf(u)) {
                    res.add(i)
                }
            }
            res
        }

        val st = TreeSet<Int>()

        used.forEach { it.forEach { st.add(it) } }

        if (N - st.size <= c) {
            return true
        }
    }
    return false
}

