public class Main {

	/**
	 * @param args
	 * @throws IOException 
	 */
	public static void main(String[] args) throws IOException {
		// TODO Auto-generated method stub
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] tmpArray = br.readLine().split(" ");
		int n = Integer.parseInt(tmpArray[0]);
		int m = Integer.parseInt(tmpArray[1]);

		int[][] matrix = new int[n][m];

		for(int i = 0; i < n; i++){
			tmpArray = br.readLine().split(" ");
			for(int j = 0; j < m ; j++){
				matrix[i][j] = Integer.parseInt(tmpArray[j]);

			}
		}

		//そのスポーツをやるかどうか
		boolean[] hold = new boolean[m + 1];
		Arrays.fill(hold, true);
		hold[0] = false;

		System.out.println(calcMaxNum(matrix, hold));
	}

	static int calcMaxNum (int[][] matrix, boolean[] hold){
		int n = matrix.length;
		int m = matrix[0].length;

		//実施するスポーツがあるか
		int count = 0;
		for(int i = 0; i < hold.length ;i++){
			if(hold[i] == true){
				count++;
			}
		}

		if(count == 0){
			return Integer.MAX_VALUE;
		}
		//System.out.println(count+"sports will be held");

		int[] member = new int[m + 1];
		Arrays.fill(member, 0);

		for(int i = 0; i < n; i++){
			for(int j = 0; j < m ; j++){
				if(hold[matrix[i][j]]){
					member[matrix[i][j]]++;
					break;
				}
			}
		}

		int max = 0;
		int maxSport = 1;
		for(int i = 1; i <= m; i++){
			if(max < member[i]){
				max = member[i];
				maxSport = i;
			}
		}

		//参加者最大のスポーツを外して再帰
		hold[maxSport] = false;
		int max2 = calcMaxNum(matrix, hold);
		return Math.min(max, max2);
	}

}

import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    private static boolean debug = false;
    private static boolean elapsed = false;

    private static PrintWriter _out = new PrintWriter(System.out);
    private static PrintWriter _err = new PrintWriter(System.err);

    private int ans = Integer.MAX_VALUE;

    private void solve(Scanner sc) {
        int N = sc.nextInt();
        int M = sc.nextInt();
        int[][] A = new int[N][M];
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < M; ++j) {
                A[i][j] = sc.nextInt() - 1;
            }
        }

        calc(A, N, M, 0, new ArrayList<>(), new HashSet<>());

        _out.println(ans);
    }
    private void calc(int[][] A, int N, int M, int start, List<Integer> list, Set<Integer> set) {
        if (set.size() > 0) {
            check(A, M, set);
        }
        for (int i = start; i < M; ++i) {
            if (set.contains(i)) {
                continue;
            }
            list.add(i);
            set.add(i);
            calc(A, N, M, i + 1, list, set);
            list.remove(list.size() - 1);
            set.remove(i);
        }
    }
    private void check(int[][] A, int M, Set<Integer> set) {
        int[] cnt = new int[M];
        for (int i = 0; i < A.length; ++i) {
            for (int j = 0; j < A[i].length; ++j) {
                if (set.contains(A[i][j])) {
                    ++cnt[A[i][j]];
                    break;
                }
            }
        }
        int max = 0;
        for (int c : cnt) {
            max = Math.max(max, c);
        }
        if (max < ans) {
            ans = max;
        }
    }
    private static BigInteger C(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        for (long i = r; i > 1; --i) {
            res = res.divide(BigInteger.valueOf(i));
        }
        return res;
    }
    private static BigInteger P(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        return res;
    }
    /*
     * 10^10 > Integer.MAX_VALUE = 2147483647 > 10^9
     * 10^19 > Long.MAX_VALUE = 9223372036854775807L > 10^18
     */
    public static void main(String[] args) {
        long S = System.currentTimeMillis();

        Scanner sc = new Scanner(System.in);
        new Main().solve(sc);
        _out.flush();

        long G = System.currentTimeMillis();
        if (elapsed) {
            _err.println((G - S) + "ms");
        }
        _err.flush();
    }
}

