	public static void main(String[] args) throws Exception {
		FastScanner sc = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);

		int n = sc.nexI();

		int kind = sc.nexI();

		int[][] dt = new int[n][kind];
		for(int i=0; i<n; i++){
		    for(int j=0; j<kind; j++){
		        dt[i][j] = sc.nexI()-1;
		    }
		}

		int left=0, right=n; //lできないrできる
		int mid=-1;

		while((right-left)>1){
			mid = left + (right-left)/2;



			if(possible(n,kind,dt,mid)) right=mid;
			else left=mid;
		}
		out.println(right);

	    out.flush();
	}

	private static boolean possible(int n, int kind, int[][] dt, int target){
	    //System.out.println("limit:"+target);
	    boolean[] held =new boolean[kind];
	    fill(held,true);
	    int[] moving = new int[n];
	    fill(moving,0);
	    Graph0n gathered = new Graph0n(kind);
	    for(int i=0; i<n; i++){
	        gathered.add(dt[i][moving[i]],i);
	    }

	    ArrayDeque<Integer> todo = new ArrayDeque<>();
	    for(int i=0; i<kind; i++){
	        todo.add(i);
	    }
	    while(todo.size()>0){
	        int dw = todo.poll();
	        if((gathered.sizeOf(dw)>target) || !held[dw]){
	            //System.out.println(" killed:"+(dw+1));
	            for(int e: gathered.get(dw)){
	                moving[e]++;
	                if(moving[e]==kind) return false;
	                int nextpos = dt[e][moving[e]];
	                gathered.add(nextpos, e);
	                todo.add(nextpos);
	            }
	            held[dw]=false;
	            gathered.clear(dw);
	        }
	    }
	    return true;
    }

