			int[] joinCnt = new int[m];
			for(int j=0;j<n;j++) {
				for(int k=0;k<m;k++) {
					if(noUse[a[j][k]])continue;
					joinCnt[a[j][k]]++;
					break;
				}
			}
			int maxJoin = 0;
			int maxSport = -1;
			for(int k=0;k<m;k++) {
				if(maxJoin < joinCnt[k]) {
					maxJoin = joinCnt[k];
					maxSport = k;
				}
			}
			min = min(min, maxJoin);
			noUse[maxSport] = true;
		}
