		if (y < N) {
			if (p == 4) {
				B += arr[y + 1] - arr[y];
			}
			if (p == 2) {
				if (arr[y + 1] - arr[y] < K) {
					recur(x, y - 1, 2);
				} else
					val = arr[y + 1] - arr[y];
			}
		}
		B += val;
		if (x == y) {
			System.out.println(B + " " + a);
			fa += B * a;
		}
		// System.out.println(Q);
		a *= Q;
		recur(x + 1, y, 1);
		recur(x, y - 1, 2);
		a /= Q;
		a *= (1 - Q);
		recur(x + 1, y, 3);
		recur(x, y - 1, 4);
		a /= (1 - Q);
		B -= val;
		// System.out.println(a+" "+B);
	}

