	private static void solve() {
		int n = sc.nextInt();
		int m = sc.nextInt();

		List<Queue<Integer>> a = new ArrayList<>(n);
		for (int i = 0; i < n; i++) {
			a.add(new ArrayDeque<>(m));
		}

		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				a.get(i).add(sc.nextInt() - 1);
			}
		}

		int min = Integer.MAX_VALUE;
		Set<Integer> no = new HashSet<>();
		out:
		while (true) {
			int[] cnt = new int[m];
			int max = 0;
			for (int i = 0; i < n; i++) {
				Queue<Integer> q = a.get(i);

				while (!q.isEmpty() && no.contains(q.peek())) {
					q.remove();
				}

				if (q.isEmpty()) {
					break out;
				}

				cnt[q.peek()]++;
				max = Math.max(max, cnt[q.peek()]);
			}

			min = Math.min(min, max);

			for (int i = 0; i < m; i++) {
				if (cnt[i] == max) {
					no.add(i);
				}
			}
		}

		pr.println(min);
	}

