/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        BSportsFestival solver = new BSportsFestival();
        solver.solve(1, in, out);
        out.close();
    }

    static class BSportsFestival {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int m = in.readInt();
            int[][] a = in.readIntTable(n, m);
            MiscUtils.decreaseByOne(a);

            int high = n;
            int low = 1;
            while (high - low > 1) {
                int mid = (high + low) / 2;
                boolean[] excl = new boolean[m];
                int[] idx = new int[n];
                boolean ok = false;
                for (int i = 0; i < m; i++) {
                    Map<Integer, Integer> map = new TreeMap<>();
                    for (int j = 0; j < n; j++) {
                        map.merge(a[j][idx[j]], 1, Integer::sum);
                    }
                    int cnt = 0;
                    for (int key : map.keySet()) {
                        if (map.get(key) > mid) {
                            excl[key] = true;
                            cnt++;
                        }
                    }
                    for (int j = 0; j < n; j++) {
                        while (idx[j] < m && excl[a[j][idx[j]]]) idx[j]++;
                    }
                    if (cnt == 0) {
                        ok = true;
                        break;
                    }
                    i += cnt - 1;
                }
                if (ok) high = mid;
                else low = mid;
            }
            out.printLine(high);
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void printLine(int i) {
            writer.println(i);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int[][] readIntTable(int rowCount, int columnCount) {
            int[][] table = new int[rowCount][];
            for (int i = 0; i < rowCount; i++) {
                table[i] = readIntArray(columnCount);
            }
            return table;
        }

        public int[] readIntArray(int size) {
            int[] array = new int[size];
            for (int i = 0; i < size; i++) {
                array[i] = readInt();
            }
            return array;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class MiscUtils {
        public static void decreaseByOne(int[]... arrays) {
            for (int[] array : arrays) {
                for (int i = 0; i < array.length; i++) {
                    array[i]--;
                }
            }
        }

    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Map.Entry;
import java.util.Scanner;
import java.util.stream.IntStream;

public class Main{
	static final Scanner s=new Scanner(System.in);
	static IntStream REPS(int v){return IntStream.range(0,v);}
	static IntStream REPS(int l,int r){return IntStream.rangeClosed(l,r);}
	static IntStream INS(int n){return REPS(n).map(i->getInt());}
	static int getInt(){return Integer.parseInt(s.next());}
	public static void main(String[]$){
		int n=getInt(),m=getInt();
		ArrayList<ArrayList<Integer>>a=new ArrayList<>();

		for(int i=0;i<n;++i) {
			ArrayList<Integer>d=new ArrayList<>();
			a.add(d);
			INS(m).forEach(d::add);
		}

		HashMap<Integer,Integer>count=new HashMap<>();
		int r=n;
		for(int i=0;i<m-1;++i){
			count.clear();
			for(int j=0;j<n;++j) {
				count.merge(a.get(j).get(0),1,Integer::sum);
			}
			r=Math.min(r,count.values().stream().max(Comparator.naturalOrder()).get());
			int hoge=count.entrySet().stream().max(Entry.comparingByValue()).get().getKey();
			a.stream().forEach(o->o.removeIf(oo->oo==hoge));
		}
		System.out.println(r);
	}
}

import java.io.*;
import java.util.StringTokenizer;

public class Main  {
    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner();

        int n = in.nextInt();
        int m = in.nextInt();

        int matrix[][] = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                matrix[i][j] = in.nextInt() - 1;
            }
        }

        int curIndex[] = new int[n];
        int numPlayers[] = new int[m];


        int best = 301;

        for (int i = 0; i < n; i++) numPlayers[matrix[i][0]]++;

        for (int i = 0; i < m; i++) {
            int curMax = 0;
            int maxSport = -1;
            for (int j = 0; j < m; j++) {
                if (numPlayers[j] > curMax) {
                    curMax = numPlayers[j];
                    maxSport = j;
                }
            }

            if (curMax < best) best = curMax;

            numPlayers[maxSport] = -1;
            if (i == n-1) break;
            for (int j = 0; j < m; j++) if (numPlayers[j] != -1) numPlayers[j] = 0;

            for (int j = 0; j < n; j++) {
                while (numPlayers[matrix[j][curIndex[j]]] == -1) curIndex[j]++;
                numPlayers[matrix[j][curIndex[j]]]++;
            }
        }
        System.out.println(best);
    }

    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(String s) {
            try {
                br = new BufferedReader(new FileReader(s));
            } catch (FileNotFoundException e) {
                // TODO Auto-generated catch block
                e.printStackTrace();
            }
        }

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    // TODO Auto-generated catch block
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        String nextLine() {
            st = null;
            try {
                return br.readLine();
            } catch (IOException e) {
                // TODO Auto-generated catch block
                e.printStackTrace();
            }
            return null;
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }

        double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

import java.io.ByteArrayInputStream;
