    static class TaskB {
        public void solve(int testNumber, Scanner sc, PrintWriter out) {
            int n = sc.nextInt(), m = sc.nextInt();
            int[][] a = new int[n][m];
            for (int i = 0; i < n; i++)
                for (int j = 0; j < m; j++)
                    a[i][j] = sc.nextInt() - 1;
            boolean[] removed = new boolean[m];
            int best = m;
            for (int c = 0; c < m; c++) {
                int[] cnt = new int[m];
                for (int i = 0; i < n; i++)
                    for (int j = 0; j < m; j++) {
                        if (!removed[a[i][j]]) {
                            cnt[a[i][j]]++;
                            break;
                        }
                    }
                int most = 0;
                for (int i = 1; i < m; i++)
                    if (cnt[i] > cnt[most])
                        most = i;
                best = Math.min(best, cnt[most]);
                removed[most] = true;
