	static void solve()
	{
		int n = ni(), m = ni();
		int[][] a = new int[n][];
		for(int i = 0;i < n;i++){
			a[i] = na(m);
			for(int j = 0;j < m;j++)a[i][j]--;
		}
		int ans = n;
		boolean[] alive = new boolean[m];
		Arrays.fill(alive, true);
		for(int rep = 0;rep < m;rep++){
			int[] f = new int[m];
			for(int i = 0;i < n;i++){
				for(int j = 0;j < m;j++){
					if(alive[a[i][j]]){
						f[a[i][j]]++;
						break;
					}
				}
			}
			int max = -1, argmax = -1;
			for(int i = 0;i < m;i++){
				if(f[i] > max){
					max = f[i];
					argmax = i;
				}
			}
			ans = Math.min(ans, max);
			alive[argmax] = false;
		}
		out.println(ans);
	}

