/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main
{
    public static void main(String[] args)
    {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB
    {
        int[][] a;
        int n;
        int m;

        public void solve(int testNumber, InputReader in, OutputWriter out)
        {
            n = in.readInt();
            m = in.readInt();
            a = IOUtils.readIntTable(in, n, m);
            int low = 0;
            int high = n;
            while (low < high)
            {
                int mid = (low + high) / 2;
                if (check(mid))
                {
                    high = mid;
                } else
                {
                    low = mid + 1;
                }
            }
            out.printLine(low);
        }

        boolean check(int x)
        {
            boolean[] set = new boolean[n];
            int[] ptr = new int[n];
            Arrays.fill(ptr, 0);
            Arrays.fill(set, false);
            boolean ret = true;
            HashSet<Integer> rejected = new HashSet<Integer>();
            while (x >= 0)
            {
                HashMap<Integer, Integer> hm = new HashMap<Integer, Integer>();
                for (int i = 0; i < n; i++)
                {
                    if (hm.containsKey(a[i][ptr[i]]))
                    {
                        hm.put(a[i][ptr[i]], hm.get(a[i][ptr[i]]) + 1);
                    } else
                    {
                        hm.put(a[i][ptr[i]], 1);
                    }
                }
                int cnt = 0;
                boolean check = false;
                for (int i = 0; i < n; i++)
                {
                    if (hm.get(a[i][ptr[i]]) > x)
                    {
                        rejected.add(a[i][ptr[i]]);
                        while (ptr[i] < m && rejected.contains(a[i][ptr[i]]))
                        {
                            ptr[i]++;
                        }
                        if (ptr[i] == m)
                        {
                            ret = false;
                            check = true;
                            break;
                        }
                    } else
                    {
                        cnt++;
                    }
                }
                if (cnt == n || check)
                {
                    break;
                }
            }
            return ret;
        }

    }

    static class OutputWriter
    {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream)
        {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer)
        {
            this.writer = new PrintWriter(writer);
        }

        public void close()
        {
            writer.close();
        }

        public void printLine(int i)
        {
            writer.println(i);
        }

    }

    static class IOUtils
    {
        public static int[] readIntArray(InputReader in, int size)
        {
            int[] array = new int[size];
            for (int i = 0; i < size; i++)
            {
                array[i] = in.readInt();
            }
            return array;
        }

        public static int[][] readIntTable(InputReader in, int rowCount, int columnCount)
        {
            int[][] table = new int[rowCount][];
            for (int i = 0; i < rowCount; i++)
            {
                table[i] = readIntArray(in, columnCount);
            }
            return table;
        }

    }

    static class InputReader
    {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream)
        {
            this.stream = stream;
        }

        public int read()
        {
            if (numChars == -1)
            {
                throw new InputMismatchException();
            }
            if (curChar >= numChars)
            {
                curChar = 0;
                try
                {
                    numChars = stream.read(buf);
                } catch (IOException e)
                {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt()
        {
            int c = read();
            while (isSpaceChar(c))
            {
                c = read();
            }
            int sgn = 1;
            if (c == '-')
            {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do
            {
                if (c < '0' || c > '9')
                {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c)
        {
            if (filter != null)
            {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c)
        {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter
        {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    private static boolean debug = false;
    private static boolean elapsed = false;

    private static PrintWriter _out = new PrintWriter(System.out);
    private static PrintWriter _err = new PrintWriter(System.err);

    private int ans = Integer.MAX_VALUE;

    private void solve(Scanner sc) {
        int N = sc.nextInt();
        int M = sc.nextInt();
        int[][] A = new int[N][M];
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < M; ++j) {
                A[i][j] = sc.nextInt() - 1;
            }
        }

        calc(A, N, M, 0, new ArrayList<>(), new HashSet<>());

        _out.println(ans);
    }
    private Set<String> memo = new HashSet<>();
    private void calc(int[][] A, int N, int M, int start, List<Integer> list, Set<Integer> set) {
        String key = list.toString();
        if (memo.contains(key)) {
            memo.add(key);
            return;
        }
        if (set.size() > 0) {
            check(A, M, set);
        }
        for (int i = start; i < M; ++i) {
            if (set.contains(i)) {
                continue;
            }
            list.add(i);
            set.add(i);
            calc(A, N, M, i + 1, list, set);
            list.remove(list.size() - 1);
            set.remove(i);
        }
    }
    private void check(int[][] A, int M, Set<Integer> set) {
        int[] cnt = new int[M];
        for (int i = 0; i < A.length; ++i) {
            for (int j = 0; j < A[i].length; ++j) {
                if (set.contains(A[i][j])) {
                    ++cnt[A[i][j]];
                    break;
                }
            }
        }
        int max = 0;
        for (int c : cnt) {
            max = Math.max(max, c);
        }
        if (max < ans) {
            ans = max;
        }
    }
    private static BigInteger C(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        for (long i = r; i > 1; --i) {
            res = res.divide(BigInteger.valueOf(i));
        }
        return res;
    }
    private static BigInteger P(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        return res;
    }
    /*
     * 10^10 > Integer.MAX_VALUE = 2147483647 > 10^9
     * 10^19 > Long.MAX_VALUE = 9223372036854775807L > 10^18
     */
    public static void main(String[] args) {
        long S = System.currentTimeMillis();

        Scanner sc = new Scanner(System.in);
        new Main().solve(sc);
        _out.flush();

        long G = System.currentTimeMillis();
        if (elapsed) {
            _err.println((G - S) + "ms");
        }
        _err.flush();
    }
}

import static java.util.Comparator.naturalOrder;
import static java.util.stream.Collectors.toList;
import java.util.*;
import java.util.Map.Entry;
import java.util.stream.IntStream;

public class Main{
	static final Scanner s=new Scanner(System.in);
	static IntStream REPS(int v){return IntStream.range(0,v);}
	static IntStream INS(int n){return REPS(n).map(i->getInt());}
	static int getInt(){return Integer.parseInt(s.next());}
	public static void main(String[]$){
		int n=getInt(),m=getInt();
		List<List<Integer>>a=REPS(n).mapToObj(i->INS(m).boxed().collect(toList())).collect(toList());
		HashMap<Integer,Integer>count=new HashMap<>();
		int r=n;
		for(int i=0;i<m-1;++i){
			count.clear();
			for(int j=0;j<n;++j)
				count.merge(a.get(j).get(0),1,Integer::sum);
			r=Math.min(r,count.values().stream().max(naturalOrder()).get());
			Integer remove=count.entrySet().stream().max(Entry.comparingByValue()).get().getKey();
			a.stream().forEach(o->o.remove(remove));
		}
		System.out.println(r);
	}
