        int[] d = new int[m];
        for (int xx = 0; xx < m; xx++) {
            Arrays.fill(d, 0);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (!z[a[i][j]]) {
                        d[a[i][j]]++;
                        break;
                    }
                }
            }
            int max = 0;
            for (int i = 0; i < m; i++) {
                max = Math.max(max, d[i]);
            }
            res = Math.min(res, max);
            for (int i = 0; i < m; i++) {
