            int count = countMap.getOrDefault(sport, 0);
            countMap.put(sport, count  + 1);
        }

        Data data = null;
        for(int sport: countMap.keySet()) {
            int count = countMap.get(sport);
            if(data == null) data = new Data(sport, count);
            else {
                if(data.count < count) {
                    data = new Data(sport, count);
                }
            }
        }

        return data;
    }

