	private static int getMaxIndex(int[] a, boolean[] mask) {
		int max = -1;
		int index = -1;
		for (int i = 0; i < a.length; i++) {
			if (mask[i] && max < a[i]) {
				max = a[i];
				index = i;
			}
		}

		return index;
	}

