class Main {
    static In in = new In();
    static Out out = new Out();
    static long mod = 1000000007;
    static long inf = 0xfffffffffffffffL;

    void solve() {
        int n = in.nextInt();
        int m = in.nextInt();
        boolean[] used = new boolean[m];
        int[][] a = new int[n][m];
        int[] count = new int[m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                a[i][j] = in.nextInt() - 1;
            }
            count[a[i][0]]++;
        }
        int[] index = new int[n];
        int ans = n;
        for (int i = 1; i < m; i++) {
            int poll = 0;
            for (int j = 1; j < m; j++) {
                if (used[poll] || (!used[j] && count[poll] < count[j])) {
                    poll = j;
                }
            }
            ans = Math.min(ans, count[poll]);
            used[poll] = true;
            for (int j = 0; j < n; j++) {
                if (a[j][index[j]] == poll) {
                    while (used[a[j][index[j]]]) {
                        count[a[j][index[j]]]--;
                        index[j]++;
                        count[a[j][index[j]]]++;
                    }
                }
            }
        }
        out.println(ans);
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

