                if (check(mid))
                {
                    high = mid;
                } else
                {
                    low = mid + 1;
                }
            }
            out.printLine(low);
        }

        boolean check(int x)
        {
            boolean[] set = new boolean[n];
            int[] ptr = new int[n];
            Arrays.fill(ptr, 0);
            Arrays.fill(set, false);
            boolean ret = true;
            while (x > 0)
            {
                HashMap<Integer, Integer> hm = new HashMap<Integer, Integer>();
                for (int i = 0; i < n; i++)
                {
                    if (hm.containsKey(a[i][ptr[i]]))
                    {
                        hm.put(a[i][ptr[i]], hm.get(a[i][ptr[i]]) + 1);
                    } else
                    {
