    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {


            int n = in.nextInt();
            int m = in.nextInt();

            int[][] a = new int[n][m];

            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    a[i][j] = in.nextInt();
                }
            }

            int bst = m;

            int[] nxt = new int[n];
            boolean[] used = new boolean[n];

            int[] sports = new int[m + 1];
            boolean[] blocked = new boolean[m + 1];

            for (int j = 0; j < m; ++j) {

                int mx_sport = 0;

                for (int i = 0; i < n; ++i) {
                    if (used[i]) continue;
                    int x = nxt[i];
                    while (x < m && blocked[a[i][x]]) x++;
                    if (x >= m) break;
                    nxt[i] = x;
                    mx_sport = Math.max(++sports[a[i][nxt[i]]], mx_sport);
                    used[i] = true;
                }

                for (int i = 0; i < n; ++i) {
                    if (sports[a[i][nxt[i]]] == mx_sport) {
                        blocked[a[i][nxt[i]]] = true;
                        used[i] = false;
                    }

                }

                bst = Math.min(mx_sport, bst);
            }

            out.println(bst);
        }

    }

