    a = new int[n][m];
    for(int i = 0; i < n; i++){
      for(int j = 0; j < m; j++){
        a[i][j] = sc.nextInt() - 1;
      }
    }

    int[] count = new int[m];
    for(int i = 0; i < n; i++){
      count[a[i][0]]++;
    }

    int min = 0;
    int maxi = -1;
    for(int i = 0; i < m; i++){
      if(min < count[i]){
        maxi = i;
        min = count[i];
      }
    }

    if(DEBUG){
      System.out.println("min = " + min);
    }

    boolean[][] check = new boolean[n][m];
    for(int i = 0; i < n; i++){
      check[i][0] = true;
    }

    for(int i = 0; i < m - 1; i++){
      for(int j = 0; j < n; j++){
        for(int k = 0; k < m; k++){
          if(check[j][k] && a[j][k] == maxi){
            check[j][k] = false;
            if(k == 0){
              check[j][1] = true;
            }
            else{
              check[j][k - 1] = true;
            }
            break;
          }
        }
      }
      count = new int[m];
      for(int j = 0; j < n; j++){
        for(int k = 0; k < m; k++){
