	static class TaskB {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			int m = in.nextInt();
			int[][] a = new int[n][m];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					a[i][j] = in.nextInt() - 1;
				}
			}
			int[] b = new int[m];
			boolean[] dead = new boolean[m];
			int[] ptr = new int[n];
			for (int ans = 1; ans <= n; ans++) {
				Arrays.fill(b, 0);
				Arrays.fill(dead, false);
				Arrays.fill(ptr, 0);
				for (int i = 0; i < n; i++) {
					++b[a[i][ptr[i]]];
				}
				int numAlive = m;
				while (numAlive > 0) {
					int bad = -1;
					for (int i = 0; i < m; i++) {
						if (dead[i]) {
							continue;
						}
						if (b[i] > ans) {
							bad = i;
							break;
						}
					}
					if (bad < 0) {
						break;
					}

					dead[bad] = true;
					--numAlive;
					for (int i = 0; i < n; i++) {
						if (a[i][ptr[i]] != bad) {
							continue;
						}
						--b[bad];
						while (ptr[i] < m && dead[a[i][ptr[i]]]) {
							++ptr[i];
						}
						if (ptr[i] < m) {
							++b[a[i][ptr[i]]];
						}
					}
				}
				if (numAlive > 0) {
					out.println(ans);
					return;
				}
