public class Main {
  private static int solve(int n, int m, int[][] am) {
    List<Deque<Integer>> favoriteSportDequeList = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      Deque<Integer> favoriteSportDeque = new ArrayDeque<>();
      for (int j = 0; j < m; j++) {
        favoriteSportDeque.addLast(am[i][j]);
      }
      favoriteSportDequeList.add(favoriteSportDeque);
    }

    int minMaxCount = Integer.MAX_VALUE;
    boolean[] excluded = new boolean[m + 1];
    for (int i = 0; i < m; i++) {
      int[] countList = new int[m + 1];
      int maxCount = 0;
      int maxSportIndex = 0;
      for (int j = 0; j < n; j++) {
        Deque<Integer> favoriteSportDeque = favoriteSportDequeList.get(j);
        int sportIndex = favoriteSportDeque.peekFirst();
        while (excluded[sportIndex]) {
          favoriteSportDeque.pollFirst();
          sportIndex = favoriteSportDeque.peekFirst();
        }
        countList[sportIndex]++;
        if (maxCount < countList[sportIndex]) {
          maxCount = countList[sportIndex];
          maxSportIndex = sportIndex;
        }
      }
      minMaxCount = Math.min(minMaxCount, maxCount);
      excluded[maxSportIndex] = true;
    }
    return minMaxCount;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int m = reader.nextInt();
    int[][] am = reader.nextIntMatrix(n, m);
    out.println(solve(n, m, am));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

