	public class Program
	{
		static void Main(string[] args)
		{
			var cin = new Scanner2();
			int n = cin.Int();
			int m = cin.Int();
			int[,] a = new int[n, m];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					a[i, j] = cin.Int();
				}
			}

			var ps = new PriorityQueue<PriorityPair<int, int>>[n];
			for (int i = 0; i < n; i++) {
				ps[i] = new PriorityQueue<PriorityPair<int, int>>(true);
			}

			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					ps[i].Enqueue(new PriorityPair<int, int>(j, a[i, j] - 1));
				}
			}

			List<int>[] favs = new List<int>[m];
			for (int i = 0; i < m; i++) {
				favs[i] = new List<int>();
			}

			for (int i = 0; i < n; i++) {
				favs[ps[i].Top.Item].Add(i);
			}

			int ans = favs.Max(x => x.Count());
			bool[] done = new bool[m];
			for (int i = 0; i < m; i++) {
				int count = 0;
				int index = 0;
				for (int j = 0; j < m; j++) {
					if (done[j]) {
						continue;
					}

					if (favs[j].Count > count) {
						count = favs[j].Count;
						index = j;
					}
				}

				done[index] = true;
				foreach (int p in favs[index]) {
					ps[p].Dequeue();
					while (ps[p].Count > 0 && done[ps[p].Top.Item]) {
						ps[p].Dequeue();
					}

					if (ps[p].Count > 0) {
						int next = ps[p].Top.Item;
						favs[next].Add(p);
					}
				}

				favs[index].Clear();
				int tempMax = favs.Max(x => x.Count);
				if (tempMax != 0) {
					ans = Math.Min(ans, tempMax);
				}
			}

			Console.WriteLine(ans);
		}
	}

	public class PriorityQueue<T>
	{
		private readonly List<T> heap_;
		private readonly Comparison<T> comparison_;
		private readonly bool reverses_;

		public T Top => heap_[0];
		public int Count => heap_.Count;

		public PriorityQueue(bool reverses = false)
			: this(Comparer<T>.Default, reverses) { }

		public PriorityQueue(int capacity, bool reverses = false)
			: this(capacity, Comparer<T>.Default.Compare, reverses) { }

		public PriorityQueue(IComparer<T> comparer, bool reverses = false)
			: this(16, comparer.Compare, reverses) { }

		public PriorityQueue(Comparison<T> comparison, bool reverses = false)
			: this(16, comparison, reverses) { }

		public PriorityQueue(
			int capacity,
			Comparison<T> comparison,
			bool reverses = false)
		{
			heap_ = new List<T>(capacity);
			comparison_ = comparison;
			reverses_ = reverses;
		}

		public void Enqueue(T item)
		{
			int c = heap_.Count;
			heap_.Add(item);
			while (c > 0) {
				int p = (c - 1) >> 1;
				if (Compare(p, c) < 0) {
					Swap(p, c);
				} else {
					break;
				}

				c = p;
			}
		}

		public T Dequeue()
		{
			T ret = heap_[0];
			int n = heap_.Count - 1;

			heap_[0] = heap_[n];
			heap_.RemoveAt(n);
			for (int p = 0, c; (c = (p << 1) + 1) < n; p = c) {
				if (c != n - 1 && Compare(c + 1, c) > 0) {
					++c;
				}

				if (Compare(p, c) < 0) {
					Swap(p, c);
				} else {
					break;
				}
			}

			return ret;
		}

		private int Compare(int x, int y)
			=> comparison_(heap_[x], heap_[y]) * (reverses_ ? -1 : 1);

		private void Swap(int x, int y)
		{
			var t = heap_[x];
			heap_[x] = heap_[y];
			heap_[y] = t;
		}
	}

	public struct PriorityPair<T, U> : IComparable<PriorityPair<T, U>>
			where T : IComparable<T>
	{
		public T Priority { get; set; }
		public U Item { get; set; }

		public PriorityPair(T priority, U item)
		{
			Priority = priority;
			Item = item;
		}

		public int CompareTo(PriorityPair<T, U> target)
			=> Priority.CompareTo(target.Priority);

		public override string ToString()
			=> $"{Priority} {Item}";
	}

	public class Scanner2
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private readonly string filePath_;
		private string[] buf_;
		private int index_;
		Func<string> reader_;

		public Scanner2(string file = "")
		{
			if (string.IsNullOrWhiteSpace(file)) {
				reader_ = Console.ReadLine;
			} else {
				filePath_ = file;
				var fs = new StreamReader(file);
				reader_ = fs.ReadLine;
			}
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = reader_();
			while (st == "") {
				st = reader_();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int() => int.Parse(Next());
		public long Long() => long.Parse(Next());
		public double Double() => double.Parse(Next());

		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long[] ArrayLong(int N, long add = 0)
