static class Program
{
    public static void Main()
    {
        var sw = new StreamWriter(OpenStandardOutput()) { NewLine = "\n" };
#if DEBUG
        sw.AutoFlush = true;
#else
        sw.AutoFlush = false;
#endif
        SetOut(sw);
        Solve(new IO(In));
        Out.Flush();
    }

    static void Solve(IO io)
    {
        var n = io.I;
        var m = io.I;
        var a = new int[n][];
        for (var i = 0; i < n; i++) a[i] = io.Is(m);

        var idx = new int[n][];
        for (var i = 0; i < n; i++)
        {
            idx[i] = new int[m];
            for (var j = 0; j < m; j++)
                idx[i][a[i][j] - 1] = j + 1;
        }

        var set = new HashSet<int>(Enumerable.Range(0, m));
        var ans = int.MaxValue;
        while (set.Any())
        {
            var max = 0;
            var maxidx = 0;
            for (var j = 0; j < m; j++)
            {
                if (!set.Contains(j)) continue;

                var cnt = 0;
                for (var i = 0; i < n; i++)
                    if (idx[i][j] == idx[i].Min()) cnt++;

                if (cnt > max)
                {
                    max = Max(max, cnt);
                    maxidx = j;
                }
            }
            ans = Min(ans, max);
            for (var i = 0; i < n; i++) idx[i][maxidx] = int.MaxValue;
            set.Remove(maxidx);
        }

        ans = Max(m - n + 1, ans);
        io.Write(ans);
    }
}

