            {
                int[] X = new int[M];
                int[] Chosen = new int[N];
                for(int i=0;i<N;i++){
                    Chosen[i] = 0;
                }
                int[] stack = new int[2*N];
                int p = 0;
                for(int i=0;i<N;i++){
                    X[B[i,0]]++;
                    if(X[B[i,0]] == bc+1){
                        stack[p] = B[i,0];
                        p++;
                    }
                }
                bool[] deleted = new bool[M];
                while(b && p != 0){
                    int C = stack[p-1];
                    p--;
                    deleted[C] = true;
                    for(int i=0;i<N;i++){
                        if(Chosen[i] == A[i,C]){
                            while(Chosen[i] <= M-1 && deleted[B[i,Chosen[i]]]){
                                Chosen[i]++;
                            }
                            if(Chosen[i] == M){
                                b = false;
                                break;
                            }
                            else{
                                X[B[i,Chosen[i]]]++;
                                if(X[B[i,Chosen[i]]] == bc+1){
                                    stack[p] = B[i,Chosen[i]];
                                    p++;
                                }
                            }
                        }
                    }
                }
            }
            if(b){
                bl = bc;
            }
            else{
                bf = bc+1;
            }
        }
        sb.Append(bf+"\n");
    }
}

