    class Program
    {
        static void Main(string[] args)
        {
            var N = RInt;
            var M = RInt;
            int[,] A = new int[N, M];
            for (int i = 0; i < N; i++)
            {
                var input = RInts;
                for (int j = 0; j < M; j++)
                {
                    A[i, j] = input[j] - 1;
                }
            }

            int l = 0;
            int r = N;
            while (r - l > 1)
            {
                int i = (r + l) / 2;

                Queue<int>[] que = new Queue<int>[N].Select(x => new Queue<int>()).ToArray();
                for (int j = 0; j < N; j++)
                {
                    for (int k = 0; k < M; k++)
                    {
                        que[j].Enqueue(A[j, k]);
                    }
                }

                int[] front = new int[N];
                for (int j = 0; j < N; j++)
                {
                    front[j] = que[j].Dequeue();
                }

                bool ok = false;
                bool[] ng = new bool[M];
                for (int m = 0; m < M; m++)
                {
                    int[] count = new int[M];
                    foreach (var f in front)
                    {
                        count[f]++;
                        if (count[f] > i) ng[f] = true;
                    }

                    List<int> next = new List<int>();
                    for (int j = 0; j < N; j++)
                    {
                        if (count[front[j]] > i) next.Add(j);
                    }

                    foreach (var n in next)
                    {
                        bool updated = false;
                        for (int j = 0; j < M; j++)
                        {
                            if (que[n].Count > 0)
                            {
                                int cand = que[n].Dequeue();
                                if (ng[cand]) continue;
                                else
                                {
                                    front[n] = cand;
                                    updated = true;
                                }
                            }
                            if (updated) break;
                        }
                    }
                    if (next.Count == 0) { ok = true; break; }
                }

                if (ok) r = i;
                else l = i;
            }

            Console.WriteLine(r);
        }


    }


