public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		int M = GetInt();
		int[,] A = new int[N, M];
		for(int i = 0; i < N; i++)
			for(int j = 0; j < M; j++)
				A[i, j] = GetInt() - 1;

		int ans = int.MaxValue / 2;
		bool[] removed = new bool[M];
		for(int i = 0; i < M; i++)
		{
			int[] cnt = new int[M];
			for(int j = 0; j < N; j++)
			{
				for(int k = 0; k < M; k++)
				{
					if(removed[A[j, k]])
						continue;

					cnt[A[j, k]]++;
					break;
				}
			}

			int max = cnt.Max();
			int iMax = Array.FindIndex(cnt, x => x == max);
			removed[iMax] = true;
			ans = Math.Min(ans, max);
		}

		Console.WriteLine(ans);
	}
}


