            while (list[0].Count > 0)
            {
                Dictionary<int, int> dic = new Dictionary<int, int>();
                for (int i = 0; i < x[0]; i++)
                {
                    if (!dic.ContainsKey(list[i][0])) dic[list[i][0]] = 0;
                    dic[list[i][0]]++;
