        public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
        public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
        public void Solve()
        {
            if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
            else SolveOne();
        }
        public void Dispose()
        {
            sc.Dispose();
            pr.Dispose();
        }
        public int Size { get { return 1; } }
        public const long Mod = 1000000007;

        // 使用する変数をここに書く
        // string S;
        // int a;
        int n, m, ans;
        int[,] a;
        bool[] use;
        int[] now;
        /// <summary>
        /// 読み込み処理をここに書く
        /// </summary>
        void Read()
        {

        }
        /// <summary>
        /// メイン処理をここに書く
        /// </summary>
        void SolveOne()
        {
            n = sc.nextInt();
            m = sc.nextInt();
            a = new int[n, m];
            use = new bool[m];
            ans = n;
            now = new int[n];

            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < m; j++)
                {
                    a[i, j] = sc.nextInt() - 1;
                }
            }
            for (int i = 0; i < m; i++)
            {
                use[i] = true;
            }

            MyCalc();
            Console.WriteLine(ans);
        }

        private void MyCalc()
        {
            for (int i = 0; i < m; i++)
            {
                int[] useCnt = new int[m];
                for (int j = 0; j < n; j++)
                {
                    useCnt[a[j, now[j]]]++;
                }
                int maxCnt = 0;
                int maxNum = -1;
                for (int j = 0; j < m; j++)
                {
                    if (useCnt[j] > maxCnt)
                    {
                        maxCnt = useCnt[j];
                        maxNum = j;
                    }
                }
                ans = Math.Min(ans, maxCnt);
                use[maxNum] = false;
                for (int j = 0; j < n; j++)
                {
                    while (use[a[j, now[j]]] == false)
                    {
                        now[j]++;
                        if (now[j] >= m)
                        {
                            return;
                        }
                    }
                }
            }
        }
    }
