namespace Competitive
{
    internal class Solution
    {
        public int N;
        public int M;
        public int[,] A;
        public void Run()
        {
            {
                var line = Input.ReadIntArray();
                N = line[0];
                M = line[1];
            }

            A = new int[N, M];

            for (int i = 0; i < N; i++)
            {
                var line = Input.ReadIntArray();
                for (int j = 0; j < M; j++)
                {
                    // (j + 1) 番目に好きなスポーツは A[i, j] - 1
                    A[i, line[j] - 1] = j + 1;
                }
            }

            int ret = int.MaxValue;

            for (int a = 0; a < M; a++)
            {
                var count = new int[M];

                for (int i = 0; i < N; i++)
                {   
                    for (int j = 0; j < M; j++)
                    {
                        if (A[i, j] == 1) count[j]++;
                    }
                }

                var s_mx = -1;
                var mx = -1;
                for (int j = 0; j < M; j++)
                {
                    if (count[j] > mx)
                    {
                        s_mx = j;
                        mx = count[j];
                    }
                }

                ret = Math.Min(ret, mx);

                for (int i = 0; i < N; i++)
                {
                    int priority = A[i, s_mx];
                    A[i, s_mx] = -1;

                    for (int j = 0; j < M; j++)
                    {
                        if (A[i, j] > priority) A[i, j]--;
                    }
                }
            }

            Console.WriteLine(ret);

        }
    }

