			aa[i][j] = getNextInt(scanner) - 1
		}
	}

	ans := n
	ii := make([]int, n)

	zero := make([]int, m)
	counter := make([]int, m)
	delete := make([]int, m)

	for d := 0; d < m-1; d++ {
		copy(counter, zero)
		for i := 0; i < n; i++ {
			for delete[aa[i][ii[i]]] == 1 {
				ii[i]++
			}
			counter[aa[i][ii[i]]]++
		}
		mx := 0
		mi := 0
		for i := 0; i < m; i++ {
			if mx < counter[i] {
				mx = counter[i]
				mi = i
			}
