void solve(){
	int n = rint, m = rint;
	int[][] af = rint(n, m);
	foreach(i; 0 .. n) foreach(j; 0 .. m) af[i][j] -= 1;
	log("n:", n, "m:", m, "af:", af);

	int best = n;
	bool[] isAlive = new bool[](m);
	foreach(k; 0 .. m) isAlive[k] = 1;
	log("best:", n, "isAlive:", isAlive);
	while(1){
		int[] count = new int[](m);
		foreach(i; 0 .. n) foreach(j; 0 .. m){
			int k = af[i][j];
			if(isAlive[k]){
				count[k] += 1;
				break;
			}
		}
		log("count:", count);

		int temp = 0;
		foreach(k, cnt; count){
			temp = max(temp, cnt);
		}
		best = min(best, temp);
		log("temp:", temp, "best:", best);

		foreach(k; 0 .. m){
			if(count[k] >= best) isAlive[k] = 0;
		}
		log("isAlive:", isAlive);

		int alivecount;
		foreach(k; 0 .. m) if(isAlive[k]) alivecount += 1;
		log("alivecount:", alivecount);
		if(alivecount == 0) break;
	}
	best.writeln;
}

