proc eval(n, m: int; a: seq2[int]; x: int): bool =
  if x >= n:
    return true

  var ban = newSeq[bool](m)
  var siz = newSeq[int](m)
  var pos = newSeq[int](n)

  for i in 0..<n:
    siz[a[i][pos[i]]] += 1

  for groupCount in countdown(m, 2):
    var g = -1
    for i in 0..<m:
      if siz[i] > x:
        g = i
        break

    if g == -1:
      break

    ban[g] = true
    siz[g] = 0

    for i in 0..<n:
      if a[i][pos[i]] != g:
        continue
      while ban[a[i][pos[i]]]:
        pos[i] += 1
      siz[a[i][pos[i]]] += 1

  return siz.all(it => it <= x)

