def is_possible(l, n, m, a):
    s = set(range(1, m + 1))
    while len(s) > 0:
        c = Counter()
        for i in range(n):
            for j in range(m):
                if a[i][j] in s:
                    c[a[i][j]] += 1
                    break
        ns = len(s)
        s = set(filter(lambda x: c[x] <= l, s))
        if len(s) == ns:
            return True
    return False


