def sports_fes():
	import collections
	n, m = map(int, raw_input().split(" "))
	a = []
	for i in range(n):
		a.append(map(int, raw_input().split(" ")))
	a = np.array(a)

	def _find_minimun(mat, ans):
		if not mat.any():
			return ans
		else:
			max_values = np.argmax(mat, axis=1)
			c = collections.Counter(max_values)
			index_to_remove = max(c, key=c.get)
			ans = min(ans, c.get(index_to_remove))
			new_mat = np.delete(mat, [index_to_remove], axis=1)
			return _find_minimun(new_mat,ans)

	print _find_minimun(a, n)


