def update_rank_lis(rank_lis, drop_sport):
    return [
        [sport for sport in ranks if sport != drop_sport]
        for ranks in rank_lis
    ]

def count_first(rank_lis):
    first_cnt = Counter([ranks[0] for ranks in rank_lis])
    sorted_cnt_sports = sorted([(cnt, sport) for sport, cnt in first_cnt.items()])[::-1]
    max_cnt = sorted_cnt_sports[0][0]
    return ((cnt, sport) for cnt, sport in sorted_cnt_sports if cnt == max_cnt)


def search(rank_lis,  min_value, depth):
