            min_value = min(most_pop_cnt, min_value)
            updated_rank_lis = update_rank_lis(rank_lis, most_pop_sport)
            searched_value = search(updated_rank_lis, min_value, depth - 1)
            min_value = min(min_value, searched_value)
    return min_value


