// https://qiita.com/tanakh/items/0ba42c7ca36cd29d0ac8
macro_rules! input {
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, [ $t:tt ]) => {{
        let len = read_value!($next, usize);
        (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    }};

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

macro_rules! println_stderr(
    ($($arg:tt)*) => { {
        let r = writeln!(&mut ::std::io::stderr(), $($arg)*);
        r.expect("failed printing to stderr");
    } }
);

fn solve() {
    input! {
        n: usize,
        m: usize,
        a: [[usize;m];n],
    }  
    let mut ans = n;
    let mut seen = vec![false;m];
    for i in 0..m {
        let mut v = vec![0;m];
        for j in 0..n {
            for k in 0..m {
                let b = a[j][k]-1;
                if seen[b] {continue;}
                v[b]+=1;
                break;
            }
        }
        let (id,&ma) = v.iter().enumerate().max_by(|x, y| x.1.cmp(y.1)).unwrap();
        // println!("{} {}", id, ma);
        seen[id] = true;
        ans = min(ans, ma);
    }
    println!("{}", ans);

}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

use std::io::*;
use std::str::FromStr;

fn main() {
    let n: usize = read();
    let m: usize = read();
    let a: Vec<Vec<usize>> = (0..n).map(|_| (0..m).map(|_| read()).collect()).collect();

    let mut cnt: Vec<usize> = vec![0; m];
    for i in 0..n {
        cnt[a[i][0]-1] += 1;
    }

    let mut ans = m;
    let mut num: Vec<usize> = vec![0; n];
    let mut ng: Vec<bool> = vec![false; m];
    for j in 0..m {
        let mut max_n = 0;
        for i in 0..m {
            if !ng[i] && cnt[max_n] < cnt[i] {
                max_n = i;
            }
        }
        ans = std::cmp::min(ans, cnt[max_n]);
        if j == m-1 {
            break;
        }
        ng[max_n] = true;
        for i in 0..m {
            cnt[i] = 0;
        }
        for i in 0..n {
            while ng[a[i][num[i]] - 1] {
                num[i] += 1;
            }
            cnt[a[i][num[i]]-1] += 1;
        }
    }
    println!("{}", ans);
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

