#[allow(dead_code)]
fn max_with_index<T: Ord>(slice: &[T]) -> (usize, &T) {
    let mut value: Option<&T> = None;
    let mut index = 0;
    for i in 0..slice.len() {
        if let Some(v) = value {
            if v < &slice[i] {
                index = i;
                value = Some(&slice[i]);
            }
        } else {
            index = i;
            value = Some(&slice[i]);
        }
    }
    (index, value.expect("not found max value"))
}

