fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut buf_it = buf.split_whitespace();

    let N = buf_it.next().unwrap().parse::<usize>().unwrap();
    let M = buf_it.next().unwrap().parse::<usize>().unwrap();
    let A = (0..N).map(|_| 
        (0..M).map(|_|
            buf_it.next().unwrap().parse::<usize>().unwrap()-1).collect::<Vec<_>>()
                ).collect::<Vec<_>>();

    let check = |n:usize| {
        let mut popped = HashSet::new();
        let mut idx = (0..N).map(|_| 0).collect::<Vec<_>>();
        loop{
            let mut cnt = (0..M).map(|_| 0).collect::<Vec<_>>();
            for i in 0..N{
                cnt[A[i][idx[i]]] += 1;
            }
            if *(cnt.iter().max().unwrap())<=n{ return true; }
            for j in 0..M{
                if cnt[j] > n{
                    popped.insert(j);
                }
            }
            if popped.len()==M {break;}
            for i in 0..N{
                while popped.contains(&A[i][idx[i]]) {
                    idx[i] += 1;
                }
            }
        }
        false
    };
    let ans = 1 + binary_search(0,N,check);
    println!("{}",ans);
}

fn binary_search<F>(l:usize,r:usize,func:F) -> usize
where F : Fn(usize) -> bool{
    let mut l = l;
    let mut r = r;
    while l+1 < r{
        let i = (l+r)/2;
        if func(i){ r = i;} else {l = i;}
    }
    l
}

