fn solve() {
    let (n,m) = get!(usize, usize);
    let mut a = Vec::new();
    for _ in 0..n {
        a.push(get!([usize]).into_iter().collect::<VecDeque<_>>());
    }
    let mut list = HashSet::new();
    let mut mn = m;
    for i in 0..m {
        let mut nums = vec![0; m+1];
        for i in 0..n {
            while list.contains(a[i].front().unwrap()) {
                a[i].pop_front();
            }
            nums[*a[i].front().unwrap()] += 1;
        }
        let mut mx = 0;
        let mut mxm = 0;
        for i in 1..m+1 {
            if nums[i] > mx {
                mx = nums[i];
                mxm = i;
            }
        }
        list.insert(mxm);
        mn = min!(mn, mx);
    }
    println!("{}", mn);
}

