    }
    let mut removed = HashSet::new();
    removed.insert(remained_index);
    for _ in 0..m - 2 {
        let mut count = vec![0; m];
        for i in 0..n {
            while removed.contains(&a[i][0]) {
                a[i].pop_front();
            }
            count[a[i][0]] += 1;
        }

        let mut max_v = 0;
        let mut max_index = 0;
        for j in 0..m {
            if count[j] > max_v {
                max_v = count[j];
                max_index = j;
            }
        }
        ans = min(ans, max_v);
        removed.insert(max_index);
    }

    println!("{}", ans);
}

