fn possible(a: &Vec<Vec<usize>>, max_count: usize) -> bool {
    let n = a.len();
    let m = a[0].len();
    let mut cnt = vec![0; m + 1];
    let mut rank = vec![0; n];
    for i in 0..n {
        cnt[a[i][rank[i]]] += 1;
    }
    let mut ng = vec![false; m + 1];
    for iter in 0..m {
        if iter == m - 1 {
            return false;
        }
        if let Some((idx, _)) = cnt
            .iter()
            .enumerate()
            .filter(|&(_, &c)| c > max_count)
            .next()
        {
            ng[idx] = true;
            for i in 0..n {
                while ng[a[i][rank[i]]] {
                    let r = rank[i];
                    rank[i] = r + 1;
                    cnt[a[i][r]] -= 1;
                    cnt[a[i][r + 1]] += 1;
                }
            }
        } else {
            break;
        }
    }
    true
}

fn run() {
    let n: usize = scan();
    let m: usize = scan();
    let a: Vec<Vec<usize>> = (0..n).map(|_| scan_iter().take(m).collect()).collect();
    let mut ng = 0;
    let mut ok = n;
    while ok - ng > 1 {
        let mid = (ok + ng) / 2;
        if possible(&a, mid) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    println!("{}", ok);
}

fn main() {
    std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap()
}

