use std::collections::*;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut a = vec![vec![0 as usize; m]; n];
    for i in 0..n {
        for j in 0..m {
            a[i][j] = sc.read();
            a[i][j] -= 1;
        }
    }
    let ans = solve(&a, vec![true; m], m - 1);
    println!("{}", ans);
}

fn solve(a: &Vec<Vec<usize>>, mut now: Vec<bool>, rep: usize) -> i32 {
    let (n, m) = (a.len(), a[0].len());
    let mut count: Vec<i32> = vec![0; m];
    for i in 0..n {
        for j in 0..m {
            if now[a[i][j]] {
                count[a[i][j]] += 1;
                break;
            }
        }
    }
    let mut cand = -1;
    let mut index = 0;
    for i in 0..m {
        if count[i] > cand {
            cand = count[i];
            index = i;
        }
    }
    if rep == 0 {
        cand
    } else {
        now[index] = false;
        std::cmp::min(cand, solve(a, now, rep - 1))
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
