use std::cmp::{min, max};
#[allow(unused_imports)]
use std::io::{stdout, stdin, BufWriter, Write};

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      m: usize,
      aa: [[usize; m]; n],
    }

    use std::collections::HashSet;
    use std::collections::HashMap;
    let mut removed = HashSet::new();

    let mut map = HashMap::new();
    for i in 0..n {
        let v = aa[i][0];
        let e = map.entry(v).or_insert(vec![]);
        e.push((i,0usize));
    }


    let mut ans = n;
    while removed.len() < m {
        let mut temp: Vec<_> = map.iter().map(|v| (v.1.len(), *v.0)).collect();
        temp.sort();
        temp.reverse();

        ans = min(ans, temp[0].0);
        let to_remove = temp[0].1;
        removed.insert(to_remove);

        let xys = map.remove(&to_remove).unwrap();
        for (x, y) in xys {
            for y in y+1..m {
                let v = aa[x][y];
                if removed.contains(&v) {
                    continue;
                }
                let e = map.entry(v).or_insert(vec![]);
                e.push((x,y));
                break;
            }
        }
    }
    puts!("{}\n", ans);
}

