// (sport, number of people)
fn max_sport(table: &mut [Vec<usize>], inclusion: &[bool], sport_count: usize) -> (usize, usize) {
    let mut nums = vec![0; sport_count];
    for row in table {
        while !inclusion[*row.last().unwrap()] {
            row.pop();
        }
        nums[*row.last().unwrap()] += 1;
    }
    nums.iter().cloned().enumerate().max_by_key(|&(_, n)| n).unwrap()
}

