    let mut ans: usize = INF_USIZE;
    for i in 0..n {
        a[i].reverse();
    }

    let mut d = INF_USIZE;
    for c in 0..m {
        for i in 0..n {
            if a[i].len() != 1 && *a[i].last().unwrap() == d {
                a[i].pop();
            }

            let k = *a[i].last().unwrap();
            let mut hp = h.entry(k).or_insert(vec![]);
            match hp.iter().position(|x| *x == i) {
                Some(y) => {}
                None => {
                    hp.push(i);
                }
            }
        }
        let tmp = h.iter().max_by_key(|x| x.1.len()).unwrap();
        ans = min(ans, tmp.1.len());
        d = *tmp.0;
        h.remove_entry(&d);
    }

    echo!(ans);
}

use std::io::{BufRead, Write};
use std::io;

fn calc(held: &[bool], fav: &[Vec<u16>]) -> Vec<usize> {
    let mut result = vec![0; fav[0].len()];
    for person in fav {
        for &like in person {
            if held[like as usize] {
                result[like as usize] += 1;
                break;
            }
        }
    }
    result
}

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut s = String::new();
    input.read_line(&mut s).unwrap();
    let mut split = s.split_whitespace();
    let n: usize = split.next().unwrap().parse().unwrap();
    let m: usize = split.next().unwrap().parse().unwrap();
    let a: Vec<Vec<u16>> = (0..n)
        .map(|_| {
            let mut s = String::new();
            input.read_line(&mut s).unwrap();
            s.split_whitespace()
                .map(|s| s.parse::<u16>().unwrap() - 1)
                .collect()
        })
        .collect();
    let mut held = vec![true; m];
    let mut cur = calc(&held, &a);
    loop {
        let cur_max = cur.iter().cloned().max().unwrap();
        let mut max_index = 0;
        let mut best = None;
        while let Some(x) = cur[max_index + 1..].iter().position(|x| x == &cur_max) {
            max_index += x + 1;
            held[max_index] = false;
            let new_max = calc(&held, &a).into_iter().max().unwrap();
            // Rollback
            held[max_index] = true;
            if new_max <= cur_max &&
                match best {
                    None => true,
                    Some((x, _)) => new_max <= x,
                } {
                best = Some((new_max, max_index));
            }
        }
        if let Some(best) = best {
            eprintln!("{:?}", best);
            held[best.1] = false;
            cur = calc(&held, &a);
        } else {
            break;
        }
    }
    writeln!(output, "{}", cur.into_iter().max().unwrap()).unwrap();
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    solve(stdin.lock(), stdout.lock());
}

