use std::io;
use std::io::{Read, BufReader};
use std::cmp;

fn next_token<R: Read>(reader: &mut R) -> Vec<u8> {
    let mut buf: [u8; 1] = [0];
    let mut read_chars = false;
    let mut ret: Vec<u8> = vec![];

    loop {
        if reader.read(&mut buf).unwrap() == 0 {
            break;
        } else {
            if buf[0] == '\r' as u8 || buf[0] == '\n' as u8 || buf[0] == ' ' as u8 {
                if read_chars {
                    break;
                }
            } else {
                read_chars = true;
                ret.push(buf[0]);
            }
        }
    };
    ret
}
fn next_i64<R: Read>(reader: &mut R) -> i64 {
    let token = next_token(reader);
    let mut ret: i64 = 0;
    let mut sgn = false;

    for c in token {
        if '0' as u8 <= c && c <= '9' as u8 {
            ret = ret * 10 + (c - ('0' as u8)) as i64;
        } else if '-' as u8 == c {
            sgn = true;
        }
    };
    ret * if sgn { -1 } else { 1 }
}
fn next_i32<R: Read>(reader: &mut R) -> i32 {
    next_i64(reader) as i32
}

fn check(lim: usize, a: &Vec<Vec<usize>>) -> bool {
    let n = a.len();
    let m = a[0].len();
    let mut forbid = vec![false; m];
    let mut cnt = vec![0 as usize; m];
    let mut ptr = vec![0 as usize; n];
    for i in 0..n {
        cnt[a[i][0]] += 1;
    }
    loop {
        let mut invalid = None;
        for j in 0..m {
            if cnt[j] > lim {
                invalid = Some(j);
                break;
            }
        }
        if invalid == None {
            return true;
        }
        let invalid = invalid.unwrap();
        forbid[invalid] = true;
        for i in 0..n {
            while forbid[a[i][ptr[i]]] {
                cnt[a[i][ptr[i]]] -= 1;
                ptr[i] += 1;
                if ptr[i] == m {
                    return false;
                }
                cnt[a[i][ptr[i]]] += 1;
            }
        }
    }
    false
}
fn main() {
    let buf = &mut BufReader::new(io::stdin());

    let n = next_i32(buf) as usize;
    let m = next_i32(buf) as usize;
    let mut a = vec![vec![]; n];
    for i in 0..n {
        let row = &mut a[i];
        for _ in 0..m {
            row.push((next_i32(buf) - 1) as usize);
        }
    }

    let mut left = 1;
    let mut right = n;
    while left < right {
        let mid = (left + right) / 2;
        if check(mid, &a) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    println!("{}", left);
}

