    }).collect();
    if result.len() < n {
        panic!("expected reading {} lines, but only {} lines are read",
               n, result.len());
    }
    result
}
#[macro_export]
macro_rules! readn_loop {
    ( $n:expr, |$pat:pat = $t:ty| $body:expr ) => {
        {
            use std::io::BufRead;
            let stdin = std::io::stdin();
            let mut lock = stdin.lock();
            for _ in 0..$n {
                let mut line = String::new();
                lock.read_line(&mut line).expect("read from stdin failed");
                let $pat = <$t>::read_line(&line).unwrap();
                $body
            }
        }
    };
    ( $n:expr, |$($pat:pat = $t:ty),*| $body:expr ) => {
        readn_loop!($n, |($($pat),*) = ($($t),*)| $body);
    };
}
pub trait Words {
    fn read<T: Readable>(&self) -> T::Output;
}
impl<'a> Words for [&'a str] {
    fn read<T: Readable>(&self) -> T::Output {
        T::read_words(self).unwrap()
    }
}
impl<'a> Words for &'a str {
    fn read<T: Readable>(&self) -> T::Output {
        T::read_words(&[self]).unwrap()
    }
}

// (sport, number of people)
fn max_sport(table: &[Vec<usize>], inclusion: &[bool]) -> (usize, usize) {
    let mut nums = vec![0; table[0].len()];
    for row in table {
        let i = row.iter().cloned().find(|&s| inclusion[s]).unwrap();
        nums[i] += 1;
    }
    nums.iter().cloned().enumerate().max_by_key(|&(_, n)| n).unwrap()
}

fn main() {
    read!(participant_count = usize, sport_count = usize);
    let table = readx::<Vec<usize_>>();
    let ans = (1..participant_count+1).bsearch_right_min(|&k| {
        let mut inclusion = vec![true; sport_count];
        for _ in 0..sport_count {
            let (s, count) = max_sport(&table, &inclusion);
            if count <= k {
                return true;
            }
            inclusion[s] = false;
        }
        false
    }).unwrap();
    println!("{}", ans);
}

#![allow(non_snake_case,unused_imports,dead_code)]
use std::io::Read;
use std::cmp::max;
use std::cmp::min;
use std::str::FromStr;
use std::collections::HashMap;
use std::collections::HashSet;
use std::collections::BinaryHeap;

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut buf_it = buf.split_whitespace();

    let N = buf_it.next().unwrap().parse::<usize>().unwrap();
    let M = buf_it.next().unwrap().parse::<usize>().unwrap();
    let A = (0..N).map(|_| 
        (0..M).map(|_|
            buf_it.next().unwrap().parse::<usize>().unwrap()-1).collect::<Vec<_>>()
                ).collect::<Vec<_>>();

    let check = |n:usize| {
        let mut popped = HashSet::new();
        let mut idx = (0..N).map(|_| 0).collect::<Vec<_>>();
        'outer: loop{
            let mut cnt = (0..M).map(|_| 0).collect::<Vec<_>>();
            for i in 0..N{
                cnt[A[i][idx[i]]] += 1;
            }
            if *(cnt.iter().max().unwrap())<=n{ return true; }
            for j in 0..M{
                if cnt[j] > n{
                    popped.insert(j);
                }
            }
            if popped.len()==N {break;}
            for i in 0..N{
                while popped.contains(&A[i][idx[i]]) {
                    idx[i] += 1;
                    if idx[i]>=N{break 'outer;}
                }
            }
        }
        false
    };
    let mut l = 0;
    let mut r = N;
    while l+1 < r{
        let i = (l+r)/2;
        if check(i) {r = i;}
        else {l = i;}
    }
    println!("{}",r);
}

use std::io::*;
use std::str::FromStr;

fn main() {
    let n: usize = read();
    let m: usize = read();
    let a: Vec<Vec<usize>> = (0..n).map(|_| (0..m).map(|_| read()).collect()).collect();

    let mut cnt: Vec<usize> = vec![0; m];
    for i in 0..n {
        cnt[a[i][0]-1] += 1;
    }

    let mut ans = m;
    let mut num: Vec<usize> = vec![0; n];
    for j in 0..m {
        let mut max_n = 0;
        for i in 0..m {
            if cnt[max_n] < cnt[i] {
                max_n = i;
            }
        }
        ans = std::cmp::min(ans, cnt[max_n]);
        cnt[max_n] = 0;
        if j == m-1 { break; }
        for i in 0..n {
            if max_n == a[i][num[i]]-1 {
                num[i] += 1;
                cnt[a[i][num[i]]-1] += 1;
            }
        }
    }
    println!("{}", ans);
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

