}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

fn gcd(a: i64, b: i64) -> i64 {
    if b == 0 {
        return a;
    }
    gcd(b, a % b)
}

fn main() {
    let mut v: Vec<usize> = read_vec();
    let (n, m) = (v[0], v[1]);
    let mut a = vec![VecDeque::new(); n];
    for i in 0..n {
        let v = read_vec::<usize>();
        let v = v.into_iter().map(|x| x - 1).collect::<VecDeque<_>>();
        a[i] = v;
    }

    let mut ans = n + 1;
    let mut removed = HashSet::new();
    let mut b = a.clone();
    for _ in 0..m - 1 {
        let mut count = vec![0; m];
        for i in 0..n {
            while removed.contains(&a[i][0]) {
                a[i].pop_front();
            }
            count[a[i][0]] += 1;
        }

        let mut max_v = 0;
        let mut max_index = 0;
        for j in 0..m {
            if count[j] > max_v {
                max_v = count[j];
                max_index = j;
            }
        }
        ans = min(ans, max_v);
        removed.insert(max_index);
    }

    let mut remained_index = 0;
    for i in 0..m {
        if removed.contains(&i) {
            remained_index = i;
            break;
        }
    }
    let mut removed = HashSet::new();
    removed.insert(remained_index);
    for _ in 0..m - 2 {
        let mut count = vec![0; m];
        for i in 0..n {
            while removed.contains(&b[i][0]) {
                b[i].pop_front();
            }
            count[b[i][0]] += 1;
        }

        let mut max_v = 0;
        let mut max_index = 0;
        for j in 0..m {
            if count[j] > max_v {
                max_v = count[j];
                max_index = j;
            }
        }
        ans = min(ans, max_v);
        removed.insert(max_index);
    }

    println!("{}", ans);
}
